INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C1','math',5,2,'u3',2,'도형의 이동과 포개어 보기 — 밀기·뒤집기·돌리기를 해도 자리와 방향만 바뀔 뿐 변의 길이·각의 크기·모양·크기는 그대로임을 되짚고, 두 도형이 꼭 같은지는 눈으로가 아니라 포개어 보거나 재어 보아 확인하기',ARRAY['6수03-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C2','math',5,2,'u3',2,'도형의 합동 — 모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라 하고, 밀거나 뒤집거나 돌려서 겹쳐도 합동이지만 크기가 다르거나 넓이만 같은 도형은 합동이 아님을 알기',ARRAY['6수03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C3','math',5,2,'u3',3,'대응점·대응변·대응각 — 합동인 두 도형을 포개었을 때 겹치는 점·변·각을 이름 차례가 아니라 겹치는 자리로 찾고, 대응변의 길이와 대응각의 크기가 같음을 이용해 재지 않고 길이·각도·둘레를 구하기',ARRAY['6수03-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C4','math',5,2,'u3',4,'선대칭도형과 대칭축 — 한 직선을 따라 접었을 때 완전히 겹치는 도형과 그 직선(대칭축)을 알고, 대칭축이 도형마다 여러 개일 수 있으며 넓이를 반으로 나누는 선이 모두 대칭축은 아님을 알기',ARRAY['6수03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C5','math',5,2,'u3',5,'선대칭도형의 성질 — 대칭축으로 접어 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대칭축은 대응점을 이은 선분을 수직으로 이등분함을 알기',ARRAY['6수03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C6','math',5,2,'u3',6,'선대칭도형 그리기 — 각 꼭짓점에서 대칭축까지의 거리를 재어 대칭축과 수직인 방향으로 반대쪽에 같은 거리만큼 대응점을 찍고(대칭축 위의 점은 그대로) 차례대로 이은 뒤 접어서 확인하기',ARRAY['6수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C7','math',5,2,'u3',7,'점대칭도형과 대칭의 중심 — 한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형과 그 점(대칭의 중심, 언제나 하나)을 알고, 가운데에 점이 있다고 점대칭도형인 것은 아니며 접기와 돌리기를 모두 해 보아야 도형을 가를 수 있음을 알기',ARRAY['6수03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C8','math',5,2,'u3',8,'점대칭도형의 성질 — 반 바퀴 돌려 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대응점을 이은 선분은 모두 대칭의 중심을 지나고 중심이 그 선분을 이등분함(수직은 아님)을 알기',ARRAY['6수03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C9','math',5,2,'u3',9,'점대칭도형 그리기 — 꼭짓점에서 대칭의 중심까지 간 만큼(가로·세로 칸 수)을 세어 중심을 지나 반대쪽으로 같은 만큼 더 간 자리에 대응점을 찍고 차례대로 이은 뒤 반 바퀴 돌려 확인하기',ARRAY['6수03-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C10','math',5,2,'u3',10,'문제 해결 — 땅을 합동인 도형 몇 개로 나눌 때 나눗셈으로 한 조각의 칸 수를 먼저 정하고, 조각들이 서로 합동인지와 조건(나무가 한 그루씩)을 모두 확인하며 「똑같이 나눈다」는 넓이가 같은 것이 아니라 합동이라는 뜻임을 알기',ARRAY['6수03-01']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X01','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2']::text[],'도형을 밀거나 뒤집거나 돌리면 변의 길이·각의 크기·넓이가 달라진다고 여긴다','움직여도 모양과 크기는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X02','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C10']::text[],'포개거나 재어 보지 않고 겉보기(색·자리·대강의 모양)로 같은 도형인지 판단한다','포개어 보거나 재어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X03','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C3']::text[],'모양만 같으면 크기가 달라도 합동이라고 여긴다','크기까지 같아야 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X04','math',5,'u3',ARRAY['M5-2-u3-C2']::text[],'뒤집거나 돌려야 겹치는 두 도형은 합동이 아니라고 여긴다','뒤집거나 돌려서 겹쳐도 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X05','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C10']::text[],'넓이나 둘레가 같으면 합동이라고 여긴다','넓이가 같아도 겹치지 않으면 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X06','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응점을 겹치는 자리가 아니라 이름 차례나 놓인 자리(왼쪽·위쪽)로 짝짓는다','겹치는 자리끼리 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X07','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응변·대응각을 이웃한 다른 변·각과 헷갈리거나, 대응각의 크기가 다르다고 여긴다','대응변·대응각은 크기가 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X08','math',5,'u3',ARRAY['M5-2-u3-C4']::text[],'대칭축의 개수를 잘못 센다(대각선 대칭축을 빠뜨리거나 대칭축이 아닌 선까지 센다)','접어서 겹치는 선만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X09','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C7']::text[],'도형을 넓이가 같은 둘로 나누는 선은 모두 대칭축이라고 여긴다(직사각형의 대각선 등)','반으로 나누기 ≠ 접어서 겹치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X10','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C8','M5-2-u3-C9']::text[],'대칭축·대칭의 중심까지의 거리와 대응점 사이의 거리를 헷갈린다(두 배와 절반을 바꾼다)','한쪽 거리 × 2 = 대응점 사이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X11','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6']::text[],'대칭축이 대응점을 이은 선분과 수직으로 만나 똑같이 둘로 나누는 것을 모른다','대칭축은 수직이등분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X12','math',5,'u3',ARRAY['M5-2-u3-C6']::text[],'선대칭도형을 그릴 때 대칭축과 수직인 방향이 아닌 쪽으로 가거나 칸 수를 잘못 세고, 대칭축 위의 점을 옮긴다','수직으로 같은 칸 수만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X13','math',5,'u3',ARRAY['M5-2-u3-C9']::text[],'점대칭도형을 그릴 때 중심까지만 가거나 중심을 지나지 않는 방향으로 대응점을 찍는다','중심을 지나 같은 만큼 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X14','math',5,'u3',ARRAY['M5-2-u3-C7']::text[],'가운데에 점이 있으면 점대칭도형이라고 여기거나, 반 바퀴가 아닌 만큼 돌려서 판단한다','반 바퀴 돌려 겹치는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X15','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9']::text[],'선대칭과 점대칭을 섞는다 — 접기와 돌리기, 대칭축과 대칭의 중심, 수직이등분과 이등분을 바꿔 말한다','선대칭은 접기, 점대칭은 돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X16','math',5,'u3',ARRAY['M5-2-u3-C10']::text[],'문제 해결에서 조건 하나만 보고(칸 수만, 나무 자리는 빼고) 나누거나 나눗셈으로 한 조각의 칸 수를 구하지 못한다','칸 수 정하기 → 두 조건 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X17','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C3','M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9','M5-2-u3-C10']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 아닌↔인, 틀린↔알맞은, 대응점↔대응변','물음의 「아닌·틀린」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X18','math',5,'u3',ARRAY['M5-2-u3-C2']::text[],'「합동」을 낱말 모양대로 「합한 도형」으로 알아, 합동인 도형을 그리라는데 두 도형을 붙인 모양을 그린다','합동 = 포개어 완전히 겹치는 두 도형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X19','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C7']::text[],'원·타원처럼 곧은 변이 없는 도형은 대칭축·대칭의 중심이 눈에 안 띄어 선대칭도형도 점대칭도형도 아니라고 여긴다','접어 보고 돌려 보면 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X20','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C7']::text[],'한 도형이 선대칭도형이면 점대칭도형일 수 없다고 여겨 둘 가운데 한쪽으로만 가른다','둘 다인 도형도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#1','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'mc','auto','배운 내용 — 오각형을 왼쪽으로 밀었어요. 민 오각형에서 처음과 달라진 것은 어느 것인가요?',ARRAY['M5-2-u3-X01']::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"mc","stem":"배운 내용 — 오각형을 왼쪽으로 밀었어요. 민 오각형에서 처음과 달라진 것은 어느 것인가요?","options":[{"t":"도형의 위치","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X01"},{"t":"각의 크기","mis":"M5-2-u3-X01"},{"t":"도형의 모양","mis":"M5-2-u3-X01"}],"explanation":["오각형을 왼쪽으로 밀면 모양은 변하지 않고 위치만 변해요.","변의 길이와 각의 크기도 그대로예요.","그래서 달라진 것은 도형의 위치예요."],"variant_rule":{"alt":[{"stem":"진단 평가 — 도형을 아래쪽으로 밀었어요. 민 도형에서 처음과 달라진 것은 어느 것인가요?","options":[{"t":"도형의 위치","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X01"},{"t":"각의 크기","mis":"M5-2-u3-X01"},{"t":"도형의 크기","mis":"M5-2-u3-X01"}],"explanation":["밀기는 도형을 그대로 옮기는 거예요.","모양과 크기, 변의 길이와 각의 크기는 그대로예요.","달라진 것은 도형이 놓인 위치뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#2','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'mc','auto','배운 내용 — 삼각형을 시곗바늘이 돌아가는 방향으로 180°만큼 돌렸더니 삼각형의 아래쪽 부분이 위쪽으로 갔어요. 돌린 삼각형에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X01']::text[],false,'{"seq":2,"concept":"M5-2-u3-C1","difficulty":1,"kind":"mc","stem":"배운 내용 — 삼각형을 시곗바늘이 돌아가는 방향으로 180°만큼 돌렸더니 삼각형의 아래쪽 부분이 위쪽으로 갔어요. 돌린 삼각형에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"모양과 크기는 그대로이고 놓인 방향만 바뀌었다","correct":true},{"t":"크기가 반으로 줄었다","mis":"M5-2-u3-X01"},{"t":"각의 크기가 180°만큼 커졌다","mis":"M5-2-u3-X01"},{"t":"모양이 다른 삼각형이 되었다","mis":"M5-2-u3-X01"}],"explanation":["180°만큼 돌리면 위쪽과 아래쪽이 서로 바뀌어요.","돌려도 변의 길이와 각의 크기는 그대로예요.","그래서 모양과 크기는 같고 놓인 방향만 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#3','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'mc','auto','달곰 도형 마술 — 달곰이가 모자에 삼각형을 넣자 똑같은 삼각형들이 나왔어요. 순달이는 삼각형들이 똑같은지 어떻게 알았을까요?',ARRAY['M5-2-u3-X02']::text[],true,'{"seq":3,"concept":"M5-2-u3-C1","difficulty":1,"kind":"mc","stem":"달곰 도형 마술 — 달곰이가 모자에 삼각형을 넣자 똑같은 삼각형들이 나왔어요. 순달이는 삼각형들이 똑같은지 어떻게 알았을까요?","options":[{"t":"삼각형들을 포개어 보았다","correct":true},{"t":"삼각형들의 색을 견주어 보았다","mis":"M5-2-u3-X02"},{"t":"멀리서 바라보았다","mis":"M5-2-u3-X02"},{"t":"변의 개수만 세어 보았다","mis":"M5-2-u3-X02"}],"explanation":["비슷해 보인다고 꼭 같은 것은 아니에요.","포개어 보면 조금만 달라도 삐져나와 알 수 있어요.","그래서 포개어 완전히 겹치는지 보아야 해요."],"variant_rule":{"alt":[{"stem":"합동인 도형 찾기 놀이 — 도형 카드 2장을 뒤집어 두 도형이 합동이면 카드를 가져가요. 두 도형이 합동인지 가장 확실하게 알아보는 방법은 어느 것인가요?","options":[{"t":"두 도형을 포개어 본다","correct":true},{"t":"두 도형의 색을 견주어 본다","mis":"M5-2-u3-X02"},{"t":"카드를 멀리 놓고 바라본다","mis":"M5-2-u3-X02"},{"t":"꼭짓점의 개수만 세어 본다","mis":"M5-2-u3-X02"}],"explanation":["합동은 포개었을 때 완전히 겹치는 두 도형이에요.","색이나 꼭짓점 수가 같아도 크기가 다를 수 있어요.","그래서 포개어 보는 것이 가장 확실해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#4','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',1,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#5','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','도형 가를 본떠 뒤집거나 돌려서 도형 나, 다, 라, 마와 각각 포개어 보았어요. 포개었을 때 도형 가와 완전히 겹치는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X03','M5-2-u3-X04','M5-2-u3-X02']::text[],false,'{"seq":5,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"도형 가를 본떠 뒤집거나 돌려서 도형 나, 다, 라, 마와 각각 포개어 보았어요. 포개었을 때 도형 가와 완전히 겹치는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다, 라","correct":true},{"t":"나, 다, 라, 마","mis":"M5-2-u3-X03"},{"t":"라","mis":"M5-2-u3-X04"},{"t":"마","mis":"M5-2-u3-X02"}],"explanation":["나는 가를 뒤집어서, 다는 가를 돌려서, 라는 가를 그대로 포개면 완전히 겹쳐요.","마는 모양은 비슷해도 가보다 커서 겹치지 않아요.","그래서 나, 다, 라예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":112.0,"poly":[[[16.0,16.0],[16.0,96.0],[116.0,96.0]]],"cap":"가"},{"w":132.0,"h":112.0,"poly":[[[116.0,16.0],[116.0,96.0],[16.0,96.0]]],"cap":"나"},{"w":112.0,"h":132.0,"poly":[[[96.0,16.0],[96.0,116.0],[16.0,116.0]]],"cap":"다"},{"w":132.0,"h":112.0,"poly":[[[16.0,16.0],[16.0,96.0],[116.0,96.0]]],"cap":"라"},{"w":162.0,"h":136.0,"poly":[[[146.0,16.0],[146.0,120.0],[16.0,120.0]]],"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#6','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','모눈 위의 도형 가~바에서 서로 합동인 도형끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M5-2-u3-X03','M5-2-u3-X04','M5-2-u3-X02']::text[],false,'{"seq":6,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"모눈 위의 도형 가~바에서 서로 합동인 도형끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가와 마, 다와 바","correct":true},{"t":"가와 마, 나와 라, 다와 바","mis":"M5-2-u3-X03"},{"t":"다와 바","mis":"M5-2-u3-X04"},{"t":"가와 다, 마와 바","mis":"M5-2-u3-X02"}],"explanation":["가와 마는 모양과 크기가 같아서 뒤집어서 포개면 완전히 겹쳐요.","다와 바는 돌려서 포개면 완전히 겹쳐요.","나와 라는 둘 다 원이지만 크기가 달라 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":120,"h":100,"poly":[[[40,20],[100,20],[80,80],[20,80]]],"grid":20,"cap":"가"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"나"},{"w":120,"h":120,"poly":[[[20,100],[60,20],[100,100]]],"grid":20,"cap":"다"},{"w":100,"h":100,"circle":[[[50.0,50.0],30.0]],"grid":20,"cap":"라"},{"w":120,"h":100,"poly":[[[20,20],[80,20],[100,80],[40,80]]],"grid":20,"cap":"마"},{"w":120,"h":120,"poly":[[[20,20],[100,60],[20,100]]],"grid":20,"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#7','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','합동인 도형 만들기 — 색종이 한 장에 오각형을 그린 다음 색종이 2장을 겹쳐서 오렸어요. 오린 두 오각형에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X18','M5-2-u3-X05']::text[],true,'{"seq":7,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"합동인 도형 만들기 — 색종이 한 장에 오각형을 그린 다음 색종이 2장을 겹쳐서 오렸어요. 오린 두 오각형에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"포개면 완전히 겹치므로 서로 합동이다","correct":true},{"t":"색이 달라서 합동이 아니다","mis":"M5-2-u3-X02"},{"t":"두 오각형을 붙인 모양이 합동이다","mis":"M5-2-u3-X18"},{"t":"넓이만 같고 모양은 다르다","mis":"M5-2-u3-X05"}],"explanation":["겹쳐서 한 번에 오리면 두 도형의 모양과 크기가 같아요.","그래서 포개면 완전히 겹쳐요.","색은 합동과 상관없어요 — 두 오각형은 서로 합동이에요."],"variant_rule":{"alt":[{"stem":"합동인 도형 만들기 — 색종이를 반으로 접어 접힌 선을 따라 잘랐어요. 자른 두 조각에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"포개면 완전히 겹치므로 서로 합동이다","correct":true},{"t":"접힌 쪽 조각이 더 크다","mis":"M5-2-u3-X03"},{"t":"두 조각을 붙인 모양이 합동이다","mis":"M5-2-u3-X18"},{"t":"넓이만 같고 모양은 다르다","mis":"M5-2-u3-X05"}],"explanation":["반으로 접어 자르면 두 조각이 꼭 맞게 겹쳐 있던 거예요.","그래서 두 조각의 모양과 크기가 같아요.","포개면 완전히 겹치므로 서로 합동이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#8','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','형성 평가 — 처음 도형과 서로 합동인 도형을 찾아보세요.',ARRAY['M5-2-u3-X03','M5-2-u3-X02','M5-2-u3-X04']::text[],false,'{"seq":8,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"형성 평가 — 처음 도형과 서로 합동인 도형을 찾아보세요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u3-X03"},{"t":"㉡","mis":"M5-2-u3-X02"},{"t":"없어요","mis":"M5-2-u3-X04"}],"explanation":["㉢은 처음 도형을 뒤집으면 포개었을 때 완전히 겹쳐요.","㉠은 모양은 비슷해도 더 커서, ㉡은 위쪽 변이 비스듬하지 않아서 겹치지 않아요.","그래서 합동인 도형은 ㉢이에요."],"asset":{"type":"geo","items":[{"w":120,"h":100,"poly":[[[20,20],[100,40],[100,80],[20,80]]],"grid":20,"cap":"처음 도형"},{"w":140,"h":120,"poly":[[[20,20],[120,44.0],[120,92.0],[20,92.0]]],"grid":20,"cap":"㉠"},{"w":120,"h":100,"poly":[[[20,20],[100,20],[100,80],[20,80]]],"grid":20,"cap":"㉡"},{"w":120,"h":100,"poly":[[[20,40],[100,20],[100,80],[20,80]]],"grid":20,"cap":"㉢"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#9','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'ox','auto','친구가 「뒤집기 한 도형은 처음 도형과 합동이 아니에요.」라고 말했어요. 이 말이 맞나요?',ARRAY['M5-2-u3-X04']::text[],false,'{"seq":9,"concept":"M5-2-u3-C2","difficulty":2,"kind":"ox","stem":"친구가 「뒤집기 한 도형은 처음 도형과 합동이 아니에요.」라고 말했어요. 이 말이 맞나요?","answer":"X","reason_options":[{"t":"뒤집어도 모양과 크기는 그대로라 포개면 완전히 겹치므로","correct":true},{"t":"처음과 같은 방향으로 놓여야 합동이므로","mis":"M5-2-u3-X04"}],"mis":"M5-2-u3-X04","explanation":["4학년 때 배운 밀기, 뒤집기, 돌리기는 모양과 크기를 바꾸지 않아요.","도형을 본떠 뒤집어 포개면 완전히 겹쳐요.","그래서 뒤집기 한 도형도 처음 도형과 합동이에요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_basic#10','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',3,'mc','auto','형성 평가 — 선분을 따라 잘랐을 때 만들어지는 두 도형이 서로 합동인 것은 어느 것인가요?',ARRAY['M5-2-u3-X02']::text[],false,'{"seq":10,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"형성 평가 — 선분을 따라 잘랐을 때 만들어지는 두 도형이 서로 합동인 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M5-2-u3-X02"},{"t":"나","mis":"M5-2-u3-X02"},{"t":"라","mis":"M5-2-u3-X02"}],"explanation":["다(직사각형)를 대각선으로 자른 두 삼각형은 돌려서 포개면 완전히 겹쳐요.","가는 원의 가운데를 지나지 않게 잘라 두 조각의 크기가 달라요.","나와 라도 두 조각의 모양과 크기가 달라 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":96.0,"h":96.0,"seg":[[[25.06,15.23],[82.64,68.0]]],"circle":[[[48.0,48.0],40]],"cap":"가"},{"w":96.0,"h":96.0,"poly":[[[28.0,8.0],[68.0,8.0],[88.0,88.0],[8.0,88.0]]],"seg":[[[28.0,8.0],[88.0,88.0]]],"cap":"나"},{"w":76.0,"h":96.0,"poly":[[[8.0,8.0],[68.0,8.0],[68.0,88.0],[8.0,88.0]]],"seg":[[[68.0,8.0],[8.0,88.0]]],"cap":"다"},{"w":96.0,"h":96.0,"poly":[[[8.0,8.0],[8.0,88.0],[88.0,88.0]]],"seg":[[[8.0,48.0],[88.0,88.0]]],"cap":"라"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#1','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',2,'sa','auto','합동인 도형 만들기 — 정사각형 모양 색종이를 반으로 접어 접힌 선을 따라 자르면 서로 합동인 도형이 2개 생겨요. 이번에는 색종이를 반으로 접고 한 번 더 반으로 접은 다음, 펼쳐서 접힌 선을 따라 모두 자르면 서로 합동인 도형은 몇 개가 생기나요?','{}'::text[],false,'{"seq":1,"concept":"M5-2-u3-C2","difficulty":2,"kind":"sa","stem":"합동인 도형 만들기 — 정사각형 모양 색종이를 반으로 접어 접힌 선을 따라 자르면 서로 합동인 도형이 2개 생겨요. 이번에는 색종이를 반으로 접고 한 번 더 반으로 접은 다음, 펼쳐서 접힌 선을 따라 모두 자르면 서로 합동인 도형은 몇 개가 생기나요?","answer":["4"],"explanation":["반으로 한 번 접으면 접힌 선이 1개, 한 번 더 접으면 접힌 선이 2개 생겨요.","두 선을 따라 모두 자르면 크기가 같은 조각 4개가 돼요.","네 조각은 포개면 완전히 겹치므로 서로 합동인 도형 4개예요."],"mis":"M5-2-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#2','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',2,'mc','auto','스테인드글라스처럼 조각을 이어 붙인 작품에서 조각 하나가 떨어졌어요. 떨어진 자리에 붙일 조각을 찾으려면 어떻게 해야 할까요?',ARRAY['M5-2-u3-X02','M5-2-u3-X05','M5-2-u3-X03']::text[],false,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"스테인드글라스처럼 조각을 이어 붙인 작품에서 조각 하나가 떨어졌어요. 떨어진 자리에 붙일 조각을 찾으려면 어떻게 해야 할까요?","options":[{"t":"떨어진 자리와 포개었을 때 완전히 겹치는 조각을 찾는다","correct":true},{"t":"색이 같은 조각을 찾는다","mis":"M5-2-u3-X02"},{"t":"넓이가 같으면 아무 조각이나 붙인다","mis":"M5-2-u3-X05"},{"t":"모양만 비슷하면 크기가 달라도 붙인다","mis":"M5-2-u3-X03"}],"explanation":["떨어진 자리에 꼭 맞으려면 모양과 크기가 모두 같아야 해요.","포개었을 때 완전히 겹치는 조각이 바로 그 자리와 합동인 조각이에요.","넓이만 같거나 모양만 비슷하면 꼭 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#3','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'mc','auto','떡살로 떡에 찍은 무늬는 떡살의 모양과 합동이에요. 진하의 떡에는 꽃잎이 8장인 꽃무늬가 찍혀 있어요. 떡살 ㉠은 꽃잎이 5장인 꽃무늬, ㉡은 줄무늬가 칸마다 엇갈린 무늬, ㉢은 꽃잎이 8장인 꽃무늬예요. 진하가 사용한 떡살은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X03']::text[],false,'{"seq":3,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"떡살로 떡에 찍은 무늬는 떡살의 모양과 합동이에요. 진하의 떡에는 꽃잎이 8장인 꽃무늬가 찍혀 있어요. 떡살 ㉠은 꽃잎이 5장인 꽃무늬, ㉡은 줄무늬가 칸마다 엇갈린 무늬, ㉢은 꽃잎이 8장인 꽃무늬예요. 진하가 사용한 떡살은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u3-X02"},{"t":"㉡","mis":"M5-2-u3-X02"},{"t":"㉠과 ㉢","mis":"M5-2-u3-X03"}],"explanation":["떡에 찍힌 무늬와 포개었을 때 완전히 겹치는 떡살을 찾아요.","떡살은 입체라 무늬가 들어가고 나온 모양이 다를 수 있지만, 입체감은 빼고 무늬의 모양과 크기만 봐요.","꽃잎이 8장인 꽃무늬 ㉢이 합동인 떡살이에요 — ㉠은 꽃 모양이어도 꽃잎 수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#4','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'ox','auto','원은 모양이 모두 같으므로 크기가 달라도 서로 합동이에요.',ARRAY['M5-2-u3-X03']::text[],false,'{"seq":4,"concept":"M5-2-u3-C2","difficulty":3,"kind":"ox","stem":"원은 모양이 모두 같으므로 크기가 달라도 서로 합동이에요.","answer":"X","reason_options":[{"t":"원은 반지름이나 지름의 길이가 같을 때만 포개어 완전히 겹치므로","correct":true},{"t":"모양이 같은 도형은 모두 합동이므로","mis":"M5-2-u3-X03"}],"mis":"M5-2-u3-X03","explanation":["원은 모양이 모두 같아요.","하지만 반지름이 다르면 작은 원이 큰 원 안에 들어가 완전히 겹치지 않아요.","반지름(지름)의 길이가 같은 원끼리만 합동이에요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#5','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'error','auto','합동인 도형을 그려 보라고 했더니 친구들이 이렇게 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X18','M5-2-u3-X04','M5-2-u3-X03']::text[],false,'{"seq":5,"concept":"M5-2-u3-C2","difficulty":3,"kind":"error","stem":"합동인 도형을 그려 보라고 했더니 친구들이 이렇게 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"순달 — 「합동은 두 도형을 합한 도형이니까 삼각형 두 개를 붙여서 그릴래.」","correct":true,"mis_target":"M5-2-u3-X18"},{"t":"여울 — 「삼각형을 본떠서 뒤집어 그려도 합동이야.」","mis":"M5-2-u3-X04"},{"t":"달곰 — 「모양과 크기가 같게 하나 더 그리면 돼.」","mis":"M5-2-u3-X03"}],"explanation":["합동은 포개었을 때 완전히 겹치는 두 도형이에요.","「합동」이라는 말을 「합한 도형」으로 잘못 알면 두 도형을 붙여 그리게 돼요.","순달이의 말이 틀렸어요 — 뒤집어 그려도, 모양과 크기만 같게 그려도 합동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#6','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'mc','auto','정사각형이 아닌 정삼각형 모양 종이로도 합동인 도형을 만들 수 있어요. 정삼각형을 한 꼭짓점과 마주 보는 변의 가운데를 잇는 선으로 반을 접어 접힌 선을 따라 자르면 두 조각은 어떤가요?',ARRAY['M5-2-u3-X03','M5-2-u3-X02']::text[],false,'{"seq":6,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"정사각형이 아닌 정삼각형 모양 종이로도 합동인 도형을 만들 수 있어요. 정삼각형을 한 꼭짓점과 마주 보는 변의 가운데를 잇는 선으로 반을 접어 접힌 선을 따라 자르면 두 조각은 어떤가요?","options":[{"t":"서로 합동인 삼각형 2개","correct":true},{"t":"크기가 서로 다른 삼각형 2개","mis":"M5-2-u3-X03"},{"t":"정삼각형 2개","mis":"M5-2-u3-X02"},{"t":"서로 합동이 아닌 사각형 2개","mis":"M5-2-u3-X02"}],"explanation":["반으로 접었을 때 두 쪽이 꼭 맞게 겹쳤어요.","접힌 선을 따라 자르면 두 조각의 모양과 크기가 같아요.","그래서 서로 합동인 삼각형 2개가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#7','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C1',3,'mc','auto','달곰 도형 마술 — 달곰이가 별 모양을 꺼내자 순달이가 「반을 접으면 완전히 겹치는 별 모양이네!」라고 했어요. 이 말에서 알 수 있는 것은 어느 것인가요?',ARRAY['M5-2-u3-X01','M5-2-u3-X02','M5-2-u3-X15']::text[],false,'{"seq":7,"concept":"M5-2-u3-C1","difficulty":3,"kind":"mc","stem":"달곰 도형 마술 — 달곰이가 별 모양을 꺼내자 순달이가 「반을 접으면 완전히 겹치는 별 모양이네!」라고 했어요. 이 말에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"접은 선의 양쪽 모양과 크기가 같다","correct":true},{"t":"접으면 별의 넓이가 두 배가 된다","mis":"M5-2-u3-X01"},{"t":"별의 양쪽 색이 다르다","mis":"M5-2-u3-X02"},{"t":"별을 돌려야만 겹친다","mis":"M5-2-u3-X15"}],"explanation":["완전히 겹친다는 것은 한쪽도 삐져나오지 않는다는 뜻이에요.","그러려면 접은 선의 양쪽이 모양도 크기도 같아야 해요.","접어도 넓이는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#8','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'essay','teacher','도형 마는 도형 가와 모양이 비슷해 보이지만 도형 가와 합동이 아니에요. 그 까닭을 「포개어」라는 말을 넣어 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C2","difficulty":4,"kind":"essay","stem":"도형 마는 도형 가와 모양이 비슷해 보이지만 도형 가와 합동이 아니에요. 그 까닭을 「포개어」라는 말을 넣어 써 보세요.","answer_guide":{"answer":"도형 마는 도형 가보다 커서 뒤집거나 돌려서 포개어도 완전히 겹치지 않기 때문입니다. 합동은 모양과 크기가 모두 같아야 합니다.","scoring_points":["크기가 다르다고 썼는가","포개어도 완전히 겹치지 않는다고 썼는가","합동은 모양과 크기가 모두 같아야 함을 알았는가"]},"explanation":["합동은 포개었을 때 완전히 겹치는 두 도형이에요.","도형 마는 가보다 커서 어떻게 포개어도 삐져나와요.","모양이 비슷해도 크기가 다르면 합동이 아니에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":112.0,"poly":[[[16.0,16.0],[16.0,96.0],[116.0,96.0]]],"cap":"가"},{"w":132.0,"h":112.0,"poly":[[[116.0,16.0],[116.0,96.0],[16.0,96.0]]],"cap":"나"},{"w":112.0,"h":132.0,"poly":[[[96.0,16.0],[96.0,116.0],[16.0,116.0]]],"cap":"다"},{"w":132.0,"h":112.0,"poly":[[[16.0,16.0],[16.0,96.0],[116.0,96.0]]],"cap":"라"},{"w":162.0,"h":136.0,"poly":[[[146.0,16.0],[146.0,120.0],[16.0,120.0]]],"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#9','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'essay','teacher','정사각형이 아닌 다른 모양의 종이로 서로 합동인 도형을 만드는 방법을 하나 쓰고, 만든 두 도형이 합동인지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C2","difficulty":4,"kind":"essay","stem":"정사각형이 아닌 다른 모양의 종이로 서로 합동인 도형을 만드는 방법을 하나 쓰고, 만든 두 도형이 합동인지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예) 정삼각형 모양 종이를 반으로 접어 접힌 선을 따라 자릅니다(또는 종이 2장을 겹쳐서 함께 오립니다). 만든 두 도형을 포개어 완전히 겹치면 서로 합동입니다.","scoring_points":["합동인 도형을 만드는 방법(반으로 접어 자르기·겹쳐 오리기)을 썼는가","포개어 확인한다고 썼는가","완전히 겹치면 합동이라고 썼는가"]},"explanation":["반으로 접어 자르거나 2장을 겹쳐 오리면 모양과 크기가 같은 도형이 생겨요.","만든 도형은 포개어 보아 확인해요.","완전히 겹치면 서로 합동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L02_challenge#10','math',5,2,'u3','L02','tb_g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'essay','teacher','선분을 따라 잘랐을 때 가(원)와 다(직사각형) 가운데 두 조각이 서로 합동인 것을 고르고, 다른 하나는 왜 합동이 아닌지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C2","difficulty":4,"kind":"essay","stem":"선분을 따라 잘랐을 때 가(원)와 다(직사각형) 가운데 두 조각이 서로 합동인 것을 고르고, 다른 하나는 왜 합동이 아닌지 써 보세요.","answer_guide":{"answer":"다입니다. 직사각형을 대각선으로 자른 두 삼각형은 돌려서 포개면 완전히 겹칩니다. 가는 원의 가운데를 지나지 않게 잘라서 두 조각의 크기가 달라 포개어도 완전히 겹치지 않습니다.","scoring_points":["다를 골랐는가","다의 두 조각이 돌려서 포개면 완전히 겹친다고 썼는가","가의 두 조각은 크기가 달라 겹치지 않는다고 썼는가"]},"explanation":["자른 두 조각을 포개어 완전히 겹치는지 생각해요.","직사각형의 대각선은 두 조각을 똑같게 나눠요.","원은 가운데를 지나게 잘라야 두 조각이 같아져요."],"asset":{"type":"geo","items":[{"w":96.0,"h":96.0,"seg":[[[25.06,15.23],[82.64,68.0]]],"circle":[[[48.0,48.0],40]],"cap":"가"},{"w":96.0,"h":96.0,"poly":[[[28.0,8.0],[68.0,8.0],[88.0,88.0],[8.0,88.0]]],"seg":[[[28.0,8.0],[88.0,88.0]]],"cap":"나"},{"w":76.0,"h":96.0,"poly":[[[8.0,8.0],[68.0,8.0],[68.0,88.0],[8.0,88.0]]],"seg":[[[68.0,8.0],[8.0,88.0]]],"cap":"다"},{"w":96.0,"h":96.0,"poly":[[[8.0,8.0],[8.0,88.0],[88.0,88.0]]],"seg":[[[8.0,48.0],[88.0,88.0]]],"cap":"라"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#1','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'mc','auto','합동인 두 도형을 완전히 겹치게 포개었을 때 겹치는 변을 무엇이라고 하나요?',ARRAY['M5-2-u3-X17','M5-2-u3-X15']::text[],true,'{"seq":1,"concept":"M5-2-u3-C3","difficulty":1,"kind":"mc","stem":"합동인 두 도형을 완전히 겹치게 포개었을 때 겹치는 변을 무엇이라고 하나요?","options":[{"t":"대응변","correct":true},{"t":"대응점","mis":"M5-2-u3-X17"},{"t":"대응각","mis":"M5-2-u3-X17"},{"t":"대칭축","mis":"M5-2-u3-X15"}],"explanation":["겹치는 꼭짓점은 대응점, 겹치는 변은 대응변, 겹치는 각은 대응각이에요.","조각보 무늬처럼 합동인 도형이 여럿 있을 때 쓰는 말이에요.","겹치는 변은 대응변이에요."],"variant_rule":{"alt":[{"stem":"합동인 두 도형을 완전히 겹치게 포개었을 때 겹치는 꼭짓점을 무엇이라고 하나요?","options":[{"t":"대응점","correct":true},{"t":"대응변","mis":"M5-2-u3-X17"},{"t":"대응각","mis":"M5-2-u3-X17"},{"t":"대칭의 중심","mis":"M5-2-u3-X15"}],"explanation":["겹치는 꼭짓점은 대응점이에요.","겹치는 변은 대응변, 겹치는 각은 대응각이에요.","그래서 답은 대응점이에요."]},{"stem":"합동인 두 도형을 완전히 겹치게 포개었을 때 겹치는 각을 무엇이라고 하나요?","options":[{"t":"대응각","correct":true},{"t":"대응점","mis":"M5-2-u3-X17"},{"t":"대응변","mis":"M5-2-u3-X17"},{"t":"대칭축","mis":"M5-2-u3-X15"}],"explanation":["겹치는 각은 대응각이에요.","겹치는 꼭짓점은 대응점, 겹치는 변은 대응변이에요.","그래서 답은 대응각이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#2','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'mc','auto','두 사각형은 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07','M5-2-u3-X17']::text[],true,'{"seq":2,"concept":"M5-2-u3-C3","difficulty":1,"kind":"mc","stem":"두 사각형은 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅇ","correct":true},{"t":"점 ㅁ","mis":"M5-2-u3-X06"},{"t":"점 ㅅ","mis":"M5-2-u3-X07"},{"t":"점 ㄹ","mis":"M5-2-u3-X17"}],"explanation":["오른쪽 사각형은 왼쪽 사각형을 뒤집은 모양이에요.","포개면 점 ㄱ은 점 ㅇ과 겹쳐요 — 이름 차례(ㄱ과 ㅁ)로 짝짓지 않아요.","그래서 점 ㄱ의 대응점은 점 ㅇ이에요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 사각형은 합동이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㅅ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X07"},{"t":"점 ㄹ","mis":"M5-2-u3-X17"}],"explanation":["오른쪽 사각형은 왼쪽 사각형을 뒤집은 모양이에요.","포개면 점 ㄷ은 점 ㅂ과 겹쳐요.","그래서 점 ㄷ의 대응점은 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
