INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#4','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'mc','auto','두 사각형은 합동이에요. 변 ㄱㄴ의 대응변은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07','M5-2-u3-X17']::text[],true,'{"seq":4,"concept":"M5-2-u3-C3","difficulty":1,"kind":"mc","stem":"두 사각형은 합동이에요. 변 ㄱㄴ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅇㅅ","correct":true},{"t":"변 ㅁㅂ","mis":"M5-2-u3-X06"},{"t":"변 ㅅㅂ","mis":"M5-2-u3-X07"},{"t":"변 ㄹㄱ","mis":"M5-2-u3-X17"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄱ과 점 ㅇ, 점 ㄴ과 점 ㅅ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㅇㅅ이에요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 사각형은 합동이에요. 변 ㄷㄹ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅂㅁ","correct":true},{"t":"변 ㅅㅇ","mis":"M5-2-u3-X06"},{"t":"변 ㅁㅇ","mis":"M5-2-u3-X07"},{"t":"변 ㄴㄷ","mis":"M5-2-u3-X17"}],"explanation":["점 ㄷ과 점 ㅂ, 점 ㄹ과 점 ㅁ이 대응점이에요.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄷㄹ의 대응변은 변 ㅂㅁ이에요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#5','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'mc','auto','두 사각형은 합동이에요. 각 ㄱㄴㄷ의 대응각은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":5,"concept":"M5-2-u3-C3","difficulty":2,"kind":"mc","stem":"두 사각형은 합동이에요. 각 ㄱㄴㄷ의 대응각은 어느 것인가요?","options":[{"t":"각 ㅇㅅㅂ","correct":true},{"t":"각 ㅁㅂㅅ","mis":"M5-2-u3-X06"},{"t":"각 ㅅㅂㅁ","mis":"M5-2-u3-X07"},{"t":"각 ㅅㅇㅁ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄱ ↔ 점 ㅇ, 점 ㄴ ↔ 점 ㅅ, 점 ㄷ ↔ 점 ㅂ이에요.","대응각도 대응점의 순서에 맞게 써요 — 가운데 글자가 꼭짓점이에요.","그래서 각 ㄱㄴㄷ의 대응각은 각 ㅇㅅㅂ이에요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 사각형은 합동이에요. 각 ㄹㄱㄴ의 대응각은 어느 것인가요?","options":[{"t":"각 ㅁㅇㅅ","correct":true},{"t":"각 ㅇㅁㅂ","mis":"M5-2-u3-X06"},{"t":"각 ㅇㅅㅂ","mis":"M5-2-u3-X07"},{"t":"각 ㅂㅁㅇ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄹ ↔ 점 ㅁ, 점 ㄱ ↔ 점 ㅇ, 점 ㄴ ↔ 점 ㅅ이에요.","대응점의 순서에 맞게 쓰면 각 ㅁㅇㅅ이에요.","가운데 글자(꼭짓점)가 ㄱ의 대응점 ㅇ이어야 해요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDE