INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#6','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'sa','auto','합동인 두 삼각형을 보고 답하세요. 변 ㄱㄴ의 길이는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"합동인 두 삼각형을 보고 답하세요. 변 ㄱㄴ의 길이는 몇 cm인가요?","answer":["3"],"explanation":["완전히 겹치게 포개었을 때 점 ㄱ은 점 ㅁ과, 점 ㄴ은 점 ㅂ과 겹쳐요.","그래서 변 ㄱㄴ의 대응변은 변 ㅁㅂ이에요.","대응변의 길이는 같으므로 3 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":238.71,"h":196.68,"pts":{"ㄱ":[81.42,16.0,"n"],"ㄴ":[16.0,58.48,"w"],"ㄷ":[185.64,94.54,"e"],"ㅁ":[157.29,180.68,"s"],"ㅂ":[222.71,138.2,"e"],"ㄹ":[53.06,102.14,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[45.5,53.01],"45°"],[[149.24,77.95],"25°"],[[198.71,172.86],"3 cm"],[[95.55,154.19],"5 cm"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄴ","ㄷ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#7','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'sa','auto','합동인 두 삼각형을 보고 답하세요. 각 ㅁㄹㅂ의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"합동인 두 삼각형을 보고 답하세요. 각 ㅁㄹㅂ의 크기는 몇 도인가요?","answer":["25"],"explanation":["완전히 겹치게 포개었을 때 각 ㅁㄹㅂ과 겹치는 각은 각 ㄱㄷㄴ이에요.","대응각의 크기는 같아요.","그래서 각 ㅁㄹㅂ은 25°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":238.71,"h":196.68,"pts":{"ㄱ":[81.42,16.0,"n"],"ㄴ":[16.0,58.48,"w"],"ㄷ":[185.64,94.54,"e"],"ㅁ":[157.29,180.68,"s"],"ㅂ":[222.71,138.2,"e"],"ㄹ":[53.06,102.14,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[45.5,53.01],"45°"],[[149.24,77.95],"25°"],[[198.71,172.86],"3 cm"],[[95.55,154.19],"5 cm"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄴ","ㄷ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#8','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'sa','auto','두 직사각형은 합동이에요. 사각형 ㅁㅂㅅㅇ의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"두 직사각형은 합동이에요. 사각형 ㅁㅂㅅㅇ의 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["변 ㅁㅂ의 대응변은 변 ㄴㄷ이라 길이가 5 cm예요.","직사각형의 넓이는 (가로) × (세로)로 구해요.","3 × 5 = 15(cm²)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":252.0,"h":146.0,"pts":{"ㄱ":[16.0,30.0,"nw"],"ㄴ":[16.0,90.0,"sw"],"ㄷ":[116.0,90.0,"se"],"ㄹ":[116.0,30.0,"ne"],"ㅁ":[176.0,30.0,"nw"],"ㅂ":[176.0,130.0,"sw"],"ㅅ":[236.0,130.0,"se"],"ㅇ":[236.0,30.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[66.0,104.0],"5 cm"],[[206.0,16.0],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#9','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'match','auto','형성 평가 — 합동인 두 삼각형에서 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C3","difficulty":2,"kind":"match","stem":"형성 평가 — 합동인 두 삼각형에서 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.","pairs":[{"l":"점 ㄷ의 대응점","r":"점 ㄹ"},{"l":"변 ㄱㄴ의 대응변","r":"변 ㅁㅂ"},{"l":"각 ㄴㄱㄷ의 대응각","r":"각 ㅂㅁㄹ"}],"mis":"M5-2-u3-X06","explanation":["오른쪽 삼각형은 왼쪽 삼각형을 반 바퀴 돌린 모양이에요.","점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㄹ이에요.","대응변·대응각도 대응점의 순서대로 써요."],"asset":{"type":"geo","items":[{"w":412.0,"h":92.0,"pts":{"ㄱ":[16.0,16.0,"nw"],"ㄴ":[56.0,76.0,"sw"],"ㄷ":[176.0,76.0,"e"],"ㅁ":[396.0,76.0,"se"],"ㅂ":[356.0,16.0,"ne"],"ㄹ":[236.0,16.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_basic#10','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',3,'error','auto','형성 평가 — 두 사각형은 합동이에요. 잘못 설명한 것을 찾아보세요.',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],false,'{"seq":10,"concept":"M5-2-u3-C3","difficulty":3,"kind":"error","stem":"형성 평가 — 두 사각형은 합동이에요. 잘못 설명한 것을 찾아보세요.","options":[{"t":"점 ㄷ의 대응점은 점 ㅅ입니다.","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"변 ㅁㅇ의 길이는 4 cm입니다.","mis":"M5-2-u3-X07"},{"t":"각 ㄹㄷㄴ의 크기는 80°입니다.","mis":"M5-2-u3-X07"}],"explanation":["오른쪽 사각형은 왼쪽을 뒤집은 모양 — 점 ㄱ ↔ 점 ㅇ, 점 ㄴ ↔ 점 ㅅ, 점 ㄷ ↔ 점 ㅂ, 점 ㄹ ↔ 점 ㅁ이에요.","변 ㅁㅇ의 대응변은 변 ㄹㄱ(4 cm), 각 ㄹㄷㄴ의 대응각은 각 ㅁㅂㅅ(80°)이에요.","점 ㄷ의 대응점은 점 ㅂ이므로 「점 ㅅ」이 틀렸어요."],"asset":{"type":"geo","items":[{"w":352.0,"h":124.2,"pts":{"ㄱ":[64.58,36.32,"nw"],"ㄴ":[16.0,94.2,"w"],"ㄷ":[156.0,94.2,"se"],"ㄹ":[143.5,23.3,"ne"],"ㅁ":[208.5,23.3,"nw"],"ㅂ":[196.0,94.2,"sw"],"ㅅ":[336.0,94.2,"e"],"ㅇ":[287.42,36.32,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[101.76,16.0],"4 cm"],[[86.0,108.2],"7 cm"],[[217.45,76.2],"80°"],[[303.37,78.99],"50°"]],"arc":[[[336.0,94.2],[196.0,94.2],[208.5,23.3]],[[287.42,36.32],[336.0,94.2],[196.0,94.2]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#1','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',2,'sa','auto','합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?','{}'::text[],false,'{"seq":1,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?","answer":["5"],"explanation":["점 ㄱ의 대응점은 점 ㅁ, 점 ㄷ의 대응점은 점 ㄹ이에요.","그래서 변 ㄱㄷ의 대응변은 변 ㅁㄹ이에요.","대응변의 길이는 같으므로 5 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":238.71,"h":196.68,"pts":{"ㄱ":[81.42,16.0,"n"],"ㄴ":[16.0,58.48,"w"],"ㄷ":[185.64,94.54,"e"],"ㅁ":[157.29,180.68,"s"],"ㅂ":[222.71,138.2,"e"],"ㄹ":[53.06,102.14,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[45.5,53.01],"45°"],[[149.24,77.95],"25°"],[[198.71,172.86],"3 cm"],[[95.55,154.19],"5 cm"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄴ","ㄷ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#2','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',2,'sa','auto','형성 평가 — 합동인 두 사각형을 보고 ?°에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"형성 평가 — 합동인 두 사각형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["65"],"explanation":["두 사각형은 같은 방향으로 놓여 있어 같은 자리의 각끼리 대응각이에요.","?°의 대응각은 왼쪽 사각형의 65°인 각이에요.","대응각의 크기는 같으므로 65°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":270.0,"h":106.0,"poly":[[[34.0,16.0],[34.0,76.0],[114.0,76.0],[93.44,31.92]],[[174.0,16.0],[174.0,76.0],[254.0,76.0],[233.44,31.92]]],"lab":[[[75.44,53.37],"130°"],[[88.7,59.88],"65°"],[[16.0,46.0],"? cm"],[[228.7,59.88],"?°"],[[156.0,46.0],"3 cm"],[[214.0,90.0],"4 cm"]],"arc":[[[34.0,16.0],[93.44,31.92],[114.0,76.0]],[[34.0,76.0],[114.0,76.0],[93.44,31.92]],[[174.0,76.0],[254.0,76.0],[233.44,31.92]]],"right":[[[34.0,16.0],[34.0,76.0],[114.0,76.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"형성 평가 — 합동인 두 사각형을 보고 ? cm에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["두 사각형은 같은 방향으로 놓여 있어 같은 자리의 변끼리 대응변이에요.","? cm인 변의 대응변은 오른쪽 사각형의 3 cm인 변이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":270.0,"h":106.0,"poly":[[[34.0,16.0],[34.0,76.0],[114.0,76.0],[93.44,31.92]],[[174.0,16.0],[174.0,76.0],[254.0,76.0],[233.44,31.92]]],"lab":[[[75.44,53.37],"130°"],[[88.7,59.88],"65°"],[[16.0,46.0],"? cm"],[[228.7,59.88],"?°"],[[156.0,46.0],"3 cm"],[[214.0,90.0],"4 cm"]],"arc":[[[34.0,16.0],[93.44,31.92],[114.0,76.0]],[[34.0,76.0],[114.0,76.0],[93.44,31.92]],[[174.0,76.0],[254.0,76.0],[233.44,31.92]]],"right":[[[34.0,16.0],[34.0,76.0],[114.0,76.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading