INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#3','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'error','auto','익힘 — 두 삼각형은 합동이에요. 친구들의 말 가운데 잘못 말한 것을 찾아보세요.',ARRAY['M5-2-u3-X07','M5-2-u3-X06']::text[],false,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":3,"kind":"error","stem":"익힘 — 두 삼각형은 합동이에요. 친구들의 말 가운데 잘못 말한 것을 찾아보세요.","options":[{"t":"세리 — 「각 ㄱㄴㄷ은 각 ㅁㅂㄹ과 크기가 같아요.」","correct":true,"mis_target":"M5-2-u3-X07"},{"t":"정희 — 「점 ㄷ의 대응점은 점 ㅂ이에요.」","mis":"M5-2-u3-X06"},{"t":"승준 — 「두 삼각형의 둘레는 같아요.」","mis":"M5-2-u3-X07"}],"explanation":["아래 삼각형은 위 삼각형을 위아래로 뒤집은 모양 — 점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㄹ, 점 ㄷ ↔ 점 ㅂ이에요.","각 ㄱㄴㄷ의 대응각은 각 ㅁㄹㅂ이에요 — 꼭짓점 ㄴ의 짝은 ㄹ이에요.","합동이면 대응변이 모두 같아 둘레도 같아요 — 세리의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":132.0,"h":232.0,"pts":{"ㄱ":[56.0,16.0,"n"],"ㄴ":[16.0,96.0,"sw"],"ㄷ":[116.0,96.0,"se"],"ㄹ":[16.0,136.0,"w"],"ㅁ":[56.0,216.0,"s"],"ㅂ":[116.0,136.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅁ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#4','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'essay','teacher','익힘 — 세리는 「각 ㄱㄴㄷ은 각 ㅁㅂㄹ과 크기가 같아요.」라고 잘못 말했어요. 바른 문장으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u3-C3","difficulty":3,"kind":"essay","stem":"익힘 — 세리는 「각 ㄱㄴㄷ은 각 ㅁㅂㄹ과 크기가 같아요.」라고 잘못 말했어요. 바른 문장으로 고쳐 써 보세요.","answer_guide":{"answer":"각 ㄱㄴㄷ은 각 ㅁㄹㅂ과 크기가 같아요. (또는 각 ㅁㅂㄹ은 각 ㄱㄷㄴ과 크기가 같아요.)","scoring_points":["대응각을 바르게 찾았는가(ㄱㄴㄷ ↔ ㅁㄹㅂ 또는 ㅁㅂㄹ ↔ ㄱㄷㄴ)","대응점의 순서에 맞게 각의 이름을 썼는가","크기가 같다고 썼는가"]},"explanation":["먼저 대응점을 찾아요 — 점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㄹ, 점 ㄷ ↔ 점 ㅂ.","각 ㄱㄴㄷ의 대응각은 꼭짓점이 ㄹ인 각 ㅁㄹㅂ이에요.","대응각을 찾아 바른 문장을 쓰면 모두 정답이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":232.0,"pts":{"ㄱ":[56.0,16.0,"n"],"ㄴ":[16.0,96.0,"sw"],"ㄷ":[116.0,96.0,"se"],"ㄹ":[16.0,136.0,"w"],"ㅁ":[56.0,216.0,"s"],"ㅂ":[116.0,136.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅁ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#5','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'mc','auto','두 사각형은 합동이에요. 대응변을 대응점의 순서에 맞게 바르게 쓴 것은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],false,'{"seq":5,"concept":"M5-2-u3-C3","difficulty":3,"kind":"mc","stem":"두 사각형은 합동이에요. 대응변을 대응점의 순서에 맞게 바르게 쓴 것은 어느 것인가요?","options":[{"t":"변 ㄴㄷ과 변 ㅅㅂ","correct":true},{"t":"변 ㄴㄷ과 변 ㅂㅅ","mis":"M5-2-u3-X06"},{"t":"변 ㄴㄷ과 변 ㅂㅁ","mis":"M5-2-u3-X07"},{"t":"변 ㄴㄷ과 변 ㅇㅅ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄴ의 대응점은 점 ㅅ, 점 ㄷ의 대응점은 점 ㅂ이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㅅㅂ — ㄴ에 ㅅ, ㄷ에 ㅂ을 맞춰 써요.","이름 차례로 짝지은 「ㅂㅅ」은 순서가 거꾸로예요."],"asset":{"type":"geo","items":[{"w":372.0,"h":152.0,"pts":{"ㄱ":[16.0,56.0,"nw"],"ㄴ":[16.0,136.0,"sw"],"ㄷ":[156.0,136.0,"se"],"ㄹ":[116.0,16.0,"ne"],"ㅁ":[256.0,16.0,"nw"],"ㅂ":[216.0,136.0,"sw"],"ㅅ":[356.0,136.0,"se"],"ㅇ":[356.0,56.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#6','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'sa','auto','단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?","answer":["6"],"explanation":["120°인 각은 가장 큰 각이라 각 ㄱㄷㄴ의 대응각은 각 ㄹㅁㅂ이에요 — 점 ㄱ ↔ 점 ㄹ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ.","변 ㄱㄷ의 대응변은 변 ㄹㅁ이에요.","대응변의 길이는 같으므로 6 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":344.0,"h":120.75,"pts":{"ㄱ":[148.0,16.0,"ne"],"ㄴ":[16.0,78.35,"w"],"ㄷ":[112.0,78.35,"s"],"ㄹ":[196.0,42.35,"nw"],"ㅂ":[328.0,104.75,"e"],"ㅁ":[232.0,104.7,"s"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅂ","ㅁ"]],"lab":[[[64.0,90.35],"8 cm"],[[101.0,59.3],"120°"],[[201.88,80.53],"6 cm"],[[267.13,62.7],"12 cm"],[[219.54,64.03],"35°"]],"arc":[[[148.0,16.0],[112.0,78.35],[16.0,78.35]],[[328.0,104.75],[196.0,42.35],[232.0,104.7]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 각 ㄹㅁㅂ의 크기는 몇 도인가요?","answer":["120"],"explanation":["점 ㄱ ↔ 점 ㄹ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ이에요.","각 ㄹㅁㅂ의 대응각은 각 ㄱㄷㄴ이에요.","대응각의 크기는 같으므로 120°예요."],"asset":{"type":"geo","items":[{"w":344.0,"h":120.75,"pts":{"ㄱ":[148.0,16.0,"ne"],"ㄴ":[16.0,78.35,"w"],"ㄷ":[112.0,78.35,"s"],"ㄹ":[196.0,42.35,"nw"],"ㅂ":[328.0,104.75,"e"],"ㅁ":[232.0,104.7,"s"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅂ","ㅁ"]],"lab":[[[64.0,90.35],"8 cm"],[[101.0,59.3],"120°"],[[201.88,80.53],"6 cm"],[[267.13,62.7],"12 cm"],[[219.54,64.03],"35°"]],"arc":[[[148.0,16.0],[112.0,78.35],[16.0,78.35]],[[328.0,104.75],[196.0,42.35],[232.0,104.7]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#7','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'sa','auto','단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄹㅂ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄹㅂ의 길이는 몇 cm인가요?","answer":["14"],"explanation":["삼각형 ㄹㅁㅂ은 삼각형 ㄱㄴㄷ을 반 바퀴 돌린 모양 — 점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㄹ이에요.","변 ㄹㅂ의 대응변은 변 ㄷㄴ이에요.","대응변의 길이는 같으므로 14 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":353.57,"h":141.22,"pts":{"ㄱ":[73.36,16.0,"n"],"ㄴ":[16.0,97.92,"w"],"ㄷ":[156.0,97.92,"e"],"ㅁ":[280.21,125.22,"s"],"ㅂ":[337.57,43.31,"e"],"ㄹ":[197.57,43.31,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[33.21,48.93],"10 cm"],[[86.0,109.92],"14 cm"],[[39.06,85.91],"55°"],[[126.41,85.73],"40°"]],"arc":[[[156.0,97.92],[16.0,97.92],[73.36,16.0]],[[16.0,97.92],[156.0,97.92],[73.36,16.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 각 ㅁㅂㄹ의 크기는 몇 도인가요?","answer":["55"],"explanation":["점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㄹ이에요.","각 ㅁㅂㄹ의 대응각은 각 ㄱㄴㄷ이에요.","대응각의 크기는 같으므로 55°예요."],"asset":{"type":"geo","items":[{"w":353.57,"h":141.22,"pts":{"ㄱ":[73.36,16.0,"n"],"ㄴ":[16.0,97.92,"w"],"ㄷ":[156.0,97.92,"e"],"ㅁ":[280.21,125.22,"s"],"ㅂ":[337.57,43.31,"e"],"ㄹ":[197.57,43.31,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[33.21,48.93],"10 cm"],[[86.0,109.92],"14 cm"],[[39.06,85.91],"55°"],[[126.41,85.73],"40°"]],"arc":[[[156.0,97.92],[16.0,97.92],[73.36,16.0]],[[16.0,97.92],[156.0,97.92],[73.36,16.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_varian