INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#8','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'sa','auto','단원 평가 — 삼각형 ㄱㄴㄷ과 삼각형 ㄷㄹㅁ은 합동이에요. 세 점 ㄴ, ㄷ, ㄹ은 한 직선 위에 있어요. 각 ㄱㄷㅁ의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C3","difficulty":4,"kind":"sa","stem":"단원 평가 — 삼각형 ㄱㄴㄷ과 삼각형 ㄷㄹㅁ은 합동이에요. 세 점 ㄴ, ㄷ, ㄹ은 한 직선 위에 있어요. 각 ㄱㄷㅁ의 크기는 몇 도인가요?","answer":["70"],"explanation":["대응각을 찾으면 각 ㄷㄱㄴ = 각 ㅁㄷㄹ = 80°예요.","삼각형 ㄱㄴㄷ에서 각 ㄱㄷㄴ = 180° − 70° − 80° = 30°예요.","한 직선은 180°이므로 각 ㄱㄷㅁ = 180° − 30° − 80° = 70°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":262.0,"h":144.76,"pts":{"ㄱ":[56.84,71.52,"n"],"ㄴ":[36.0,128.76,"s"],"ㄷ":[156.0,128.76,"s"],"ㄹ":[216.92,128.76,"s"],"ㅁ":[175.88,16.0,"n"]},"seg":[[[16.0,128.76],[246.0,128.76]],[[56.84,71.52],[36.0,128.76]],[[56.84,71.52],[156.0,128.76]],[[175.88,16.0],[156.0,128.76]],[[175.88,16.0],[216.92,128.76]]],"lab":[[[57.3,113.85],"70°"],[[175.92,112.05],"80°"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄹ","ㄷ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#9','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'sa','auto','단원 평가 — 두 삼각형은 합동이에요. 삼각형 ㄹㅁㅂ의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C3","difficulty":4,"kind":"sa","stem":"단원 평가 — 두 삼각형은 합동이에요. 삼각형 ㄹㅁㅂ의 둘레는 몇 cm인가요?","answer":["17"],"explanation":["합동인 두 삼각형은 대응변의 길이가 각각 같아요.","그래서 삼각형 ㄹㅁㅂ의 세 변은 4 cm, 6 cm, 7 cm예요.","둘레는 4 + 6 + 7 = 17(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":172.0,"h":200.44,"pts":{"ㄱ":[16.0,16.0,"nw"],"ㄴ":[57.42,84.44,"s"],"ㄷ":[156.0,16.0,"ne"],"ㅂ":[156.0,116.0,"ne"],"ㅁ":[114.58,184.44,"s"],"ㄹ":[16.0,116.0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅂ","ㅁ","ㄹ"]],"lab":[[[24.73,57.47],"4 cm"],[[114.69,61.72],"6 cm"],[[86.0,104.0],"7 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L03_challenge#10','math',5,2,'u3','L03','tb_g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'essay','teacher','합동인 두 도형의 성질을 대응변과 대응각을 넣어 설명하고, 그 성질을 이용하여 각 ㅁㄹㅂ의 크기를 구하는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C3","difficulty":4,"kind":"essay","stem":"합동인 두 도형의 성질을 대응변과 대응각을 넣어 설명하고, 그 성질을 이용하여 각 ㅁㄹㅂ의 크기를 구하는 방법을 써 보세요.","answer_guide":{"answer":"합동인 두 도형에서 각각의 대응변의 길이와 대응각의 크기는 같습니다. 각 ㅁㄹㅂ과 겹치는 각은 각 ㄱㄷㄴ이므로 두 각은 대응각이고, 각 ㅁㄹㅂ의 크기는 25°입니다.","scoring_points":["대응변의 길이가 같다고 썼는가","대응각의 크기가 같다고 썼는가","각 ㅁㄹㅂ의 대응각(각 ㄱㄷㄴ)을 찾아 25°를 구했는가"]},"explanation":["합동인 두 도형은 대응변의 길이와 대응각의 크기가 각각 같아요.","각 ㅁㄹㅂ과 포개었을 때 겹치는 각을 먼저 찾아요.","그 각이 25°이므로 각 ㅁㄹㅂ도 25°예요."],"asset":{"type":"geo","items":[{"w":238.71,"h":196.68,"pts":{"ㄱ":[81.42,16.0,"n"],"ㄴ":[16.0,58.48,"w"],"ㄷ":[185.64,94.54,"e"],"ㅁ":[157.29,180.68,"s"],"ㅂ":[222.71,138.2,"e"],"ㄹ":[53.06,102.14,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[45.5,53.01],"45°"],[[149.24,77.95],"25°"],[[198.71,172.86],"3 cm"],[[95.55,154.19],"5 cm"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄴ","ㄷ","ㄱ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#1','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#2','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','도형 가~라 가운데 반으로 접었을 때 완전히 겹치는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X08','M5-2-u3-X17']::text[],false,'{"seq":2,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"도형 가~라 가운데 반으로 접었을 때 완전히 겹치는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다, 라","correct":true},{"t":"가, 나, 다, 라","mis":"M5-2-u3-X09"},{"t":"가, 라","mis":"M5-2-u3-X08"},{"t":"나","mis":"M5-2-u3-X17"}],"explanation":["가는 세로로, 다는 비스듬한 직선으로, 라는 가로로 접으면 완전히 겹쳐요.","나(평행사변형)는 반으로 나누는 선은 있어도 어느 직선으로 접어도 겹치지 않아요.","그래서 가, 다, 라예요 — 다처럼 비스듬한 대칭축도 있어요."],"asset":{"type":"geo","items":[{"w":112.0,"h":132.0,"poly":[[[56.0,16.0],[96.0,116.0],[16.0,116.0]]],"cap":"가"},{"w":118.0,"h":122.0,"poly":[[[16.0,16.0],[76.0,16.0],[102.0,106.0],[42.0,106.0]]],"cap":"나"},{"w":132.0,"h":132.0,"poly":[[[16.0,16.0],[16.0,116.0],[116.0,116.0]]],"cap":"다"},{"w":172.0,"h":132.0,"poly":[[[16.0,66.0],[116.0,16.0],[156.0,16.0],[156.0,116.0],[116.0,116.0]]],"cap":"라"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#3','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','데칼코마니 — 종이를 반으로 접어서 한쪽에만 그림을 그린 다음 반으로 다시 접었다 펴면 어떻게 될까요?',ARRAY['M5-2-u3-X01','M5-2-u3-X15','M5-2-u3-X02']::text[],false,'{"seq":3,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"데칼코마니 — 종이를 반으로 접어서 한쪽에만 그림을 그린 다음 반으로 다시 접었다 펴면 어떻게 될까요?","options":[{"t":"접은 선을 기준으로 양쪽이 똑같은 그림이 된다","correct":true},{"t":"양쪽 그림의 크기가 달라진다","mis":"M5-2-u3-X01"},{"t":"그림이 반 바퀴 돌아간 모양이 된다","mis":"M5-2-u3-X15"},{"t":"그림을 그린 쪽에만 그림이 남는다","mis":"M5-2-u3-X02"}],"explanation":["접었다 펴면 물감이 접은 선 건너편에 그대로 찍혀요.","그래서 접은 선을 기준으로 양쪽 모양과 크기가 똑같아요.","데칼코마니로 만든 작품은 선대칭도형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#4','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','형성 평가 — 선대칭도형을 찾아보세요.',ARRAY['M5-2-u3-X02','M5-2-u3-X09']::text[],false,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"형성 평가 — 선대칭도형을 찾아보세요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u3-X02"},{"t":"㉢","mis":"M5-2-u3-X09"},{"t":"㉡과 ㉢","mis":"M5-2-u3-X09"}],"explanation":["㉡(별 모양)은 꼭짓점과 가운데를 지나는 직선으로 접으면 완전히 겹쳐요.","㉠은 세 변의 길이가 모두 달라 어떻게 접어도 겹치지 않아요.","㉢(평행사변형)은 반으로 나눌 수는 있어도 접어서 겹치는 직선이 없어요."],"asset":{"type":"geo","items":[{"w":112.0,"h":116.0,"poly":[[[96.0,16.0],[96.0,100.0],[16.0,100.0]]],"cap":"㉠"},{"w":119.5,"h":115.21,"poly":[[[59.75,16.0],[70.92,46.63],[103.5,47.79],[77.82,67.87],[86.79,99.21],[59.75,81.0],[32.71,99.21],[41.68,67.87],[16.0,47.79],[48.58,46.63]]],"cap":"㉡"},{"w":152.0,"h":112.0,"poly":[[[46.0,16.0],[136.0,16.0],[106.0,96.0],[16.0,96.0]]],"cap":"㉢"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#5','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','모눈 위의 도형 가~마 가운데 선대칭도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X19','M5-2-u3-X02','M5-2-u3-X08']::text[],false,'{"seq":5,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"모눈 위의 도형 가~마 가운데 선대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 라, 마","correct":true},{"t":"가, 나, 라","mis":"M5-2-u3-X19"},{"t":"가, 나, 다, 라, 마","mis":"M5-2-u3-X02"},{"t":"나, 라","mis":"M5-2-u3-X08"}],"explanation":["가는 세로·가로로, 나는 가로로, 라는 네 방향으로, 마(원)는 지름을 따라 접으면 완전히 겹쳐요.","다는 어느 직선으로 접어도 겹치지 않아요.","원처럼 곧은 변이 없어도 접어서 겹치면 선대칭도형이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[60,20],[100,40],[100,80],[60,100],[20,80],[20,40]]],"grid":20,"cap":"가"},{"w":100,"h":120,"poly":[[[40,20],[80,20],[60,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"나"},{"w":100,"h":120,"poly":[[[80,20],[80,100],[20,100],[20,80]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#6','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','모눈 위의 도형 가~마 가운데 대칭축이 2개 이상인 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X19']::text[],false,'{"seq":6,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"모눈 위의 도형 가~마 가운데 대칭축이 2개 이상인 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라, 마","correct":true},{"t":"라","mis":"M5-2-u3-X08"},{"t":"가, 나, 라, 마","mis":"M5-2-u3-X08"},{"t":"가, 라","mis":"M5-2-u3-X19"}],"explanation":["가는 2개, 나는 1개, 라는 4개예요.","마(원)는 대칭축이 셀 수 없이 많아요.","그래서 2개 이상인 도형은 가, 라, 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[60,20],[100,40],[100,80],[60,100],[20,80],[20,40]]],"grid":20,"cap":"가"},{"w":100,"h":120,"poly":[[[40,20],[80,20],[60,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"나"},{"w":100,"h":120,"poly":[[[80,20],[80,100],[20,100],[20,80]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#7','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'sa','auto','모눈 위의 도형 라(정사각형)의 대칭축은 모두 몇 개인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C4","difficulty":2,"kind":"sa","stem":"모눈 위의 도형 라(정사각형)의 대칭축은 모두 몇 개인가요?","answer":["4"],"explanation":["정사각형은 세로 가운데 선과 가로 가운데 선으로 접으면 겹쳐요.","두 대각선으로 접어도 완전히 겹쳐요.","그래서 대칭축은 모두 4개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[60,20],[100,40],[100,80],[60,100],[20,80],[20,40]]],"grid":20,"cap":"가"},{"w":100,"h":120,"poly":[[[40,20],[80,20],[60,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"나"},{"w":100,"h":120,"poly":[[[80,20],[80,100],[20,100],[20,80]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"마"}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 위의 도형 가(육각형)의 대칭축은 모두 몇 개인가요?","answer":["2"],"explanation":["도형 가는 세로 가운데 선으로 접으면 완전히 겹쳐요.","가로 가운데 선으로 접어도 완전히 겹쳐요.","비스듬한 선으로는 겹치지 않으니 대칭축은 2개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[60,20],[100,40],[100,80],[60,100],[20,80],[20,40]]],"grid":20,"cap":"가"},{"w":100,"h":120,"poly":[[[40,20],[80,20],[60,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"나"},{"w":100,"h":120,"poly":[[[80,20],[80,100],[20,100],[20,80]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"마"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#8','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','도형 마(원)에 대칭축을 그어 친구들과 비교해 보았어요. 원의 대칭축은 몇 개인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X19']::text[],false,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"도형 마(원)에 대칭축을 그어 친구들과 비교해 보았어요. 원의 대칭축은 몇 개인가요?","options":[{"t":"셀 수 없이 많다","correct":true},{"t":"1개","mis":"M5-2-u3-X08"},{"t":"2개","mis":"M5-2-u3-X08"},{"t":"없다","mis":"M5-2-u3-X19"}],"explanation":["원은 지름을 따라 접으면 언제나 완전히 겹쳐요.","지름은 어느 방향으로든 그을 수 있어요.","그래서 원의 대칭축은 셀 수 없이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#9','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','익힘 — 픽토그램은 글자를 몰라도 뜻을 알 수 있게 만든 그림 문자예요. ㉠ 지하철역(M 글자와 열차 앞모습), ㉡ 소화기, ㉢ 왼쪽(왼쪽을 가리키는 화살표), ㉣ 화장실(여자와 남자), ㉤ 비상구(문으로 달려 나가는 사람) 가운데 선대칭도형 모양인 픽토그램을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X08']::text[],false,'{"seq":9,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"익힘 — 픽토그램은 글자를 몰라도 뜻을 알 수 있게 만든 그림 문자예요. ㉠ 지하철역(M 글자와 열차 앞모습), ㉡ 소화기, ㉢ 왼쪽(왼쪽을 가리키는 화살표), ㉣ 화장실(여자와 남자), ㉤ 비상구(문으로 달려 나가는 사람) 가운데 선대칭도형 모양인 픽토그램을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉢, ㉣","mis":"M5-2-u3-X02"},{"t":"㉢","mis":"M5-2-u3-X08"},{"t":"㉠, ㉡, ㉢","mis":"M5-2-u3-X02"}],"explanation":["㉠은 세로 가운데 선으로, ㉢은 가로 가운데 선으로 접으면 완전히 겹쳐요.","㉣은 왼쪽 여자와 오른쪽 남자 모양이 달라 겹치지 않아요.","㉡·㉤도 어느 직선으로 접어도 겹치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_basic#10','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',3,'mc','auto','형성 평가 — 선대칭도형에 대칭축을 그었어요. 대칭축을 잘못 그은 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X08','M5-2-u3-X17']::text[],false,'{"seq":10,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"형성 평가 — 선대칭도형에 대칭축을 그었어요. 대칭축을 잘못 그은 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다","correct":true},{"t":"가","mis":"M5-2-u3-X09"},{"t":"다","mis":"M5-2-u3-X08"},{"t":"나","mis":"M5-2-u3-X17"}],"explanation":["가(정오각형)에 그은 선은 꼭짓점과 마주 보는 변의 가운데를 지나지 않아 접으면 어긋나요.","다(직사각형)의 대각선은 넓이를 반으로 나누지만 접으면 꼭짓점이 어긋나요.","나에 그은 세로선만 바르게 그은 대칭축이에요."],"asset":{"type":"geo","items":[{"w":116.0,"h":84.36,"poly":[[[58.0,6.0],[96.04,33.64],[81.51,78.36],[34.49,78.36],[19.96,33.64]]],"seg":[[[6.0,24.0],[110.0,70.0]]],"cap":"가"},{"w":92.0,"h":140.0,"poly":[[[26.0,20.0],[66.0,20.0],[66.0,80.0],[86.0,80.0],[46.0,120.0],[6.0,80.0],[26.0,80.0]]],"seg":[[[46.0,6.0],[46.0,134.0]]],"cap":"나"},{"w":136.0,"h":74.0,"poly":[[[18.0,12.0],[118.0,12.0],[118.0,62.0],[18.0,62.0]]],"seg":[[[6.0,68.0],[130.0,6.0]]],"cap":"다"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#1','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',2,'mc','auto','주변에서 찾은 모양 가운데 선대칭도형 모양이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],false,'{"seq":1,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"주변에서 찾은 모양 가운데 선대칭도형 모양이 아닌 것은 어느 것인가요?","options":[{"t":"알파벳 F","correct":true},{"t":"숫자 8","mis":"M5-2-u3-X17"},{"t":"프랑스 국기","mis":"M5-2-u3-X17"},{"t":"나비","mis":"M5-2-u3-X17"}],"explanation":["숫자 8, 프랑스 국기, 나비는 가운데 직선으로 접으면 완전히 겹쳐요.","알파벳 F는 어느 직선으로 접어도 겹치지 않아요.","물음이 「아닌 것」을 묻는지 꼭 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#2','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',2,'match','auto','익힘 — 알파벳의 모양을 보고 알맞게 선으로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M5-2-u3-C4","difficulty":2,"kind":"match","stem":"익힘 — 알파벳의 모양을 보고 알맞게 선으로 이어 보세요.","pairs":[{"l":"F, J","r":"선대칭도형이 아닌 모양"},{"l":"A, C, U","r":"대칭축이 1개인 선대칭도형"},{"l":"H","r":"대칭축이 2개인 선대칭도형"}],"mis":"M5-2-u3-X08","explanation":["F와 J는 어느 직선으로 접어도 겹치지 않아요.","A와 U는 세로선 하나로, C는 가로선 하나로 접혀요.","H는 세로선과 가로선 2개로 접혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#3','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'sa','auto','형성 평가 — 선대칭도형에 대칭축을 모두 그으면 몇 개인가요?','{}'::text[],false,'{"seq":3,"concept":"M5-2-u3-C4","difficulty":3,"kind":"sa","stem":"형성 평가 — 선대칭도형에 대칭축을 모두 그으면 몇 개인가요?","answer":["2"],"explanation":["위아래 변이 같고 양옆이 안쪽으로 꺾인 모양이에요.","세로 가운데 선, 가로 가운데 선으로 접으면 완전히 겹쳐요.","대각선으로는 겹치지 않으니 대칭축은 2개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":160,"h":120,"poly":[[[20,20],[140,20],[120,60],[140,100],[20,100],[40,60]]],"grid":20}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#4','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'mc','auto','내가 그은 대칭축과 친구가 그은 대칭축이 서로 달랐어요. 알맞은 설명은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X09','M5-2-u3-X15']::text[],false,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"내가 그은 대칭축과 친구가 그은 대칭축이 서로 달랐어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"하나의 도형에 대칭축이 여러 개일 수 있어 둘 다 맞을 수 있다","correct":true},{"t":"대칭축은 하나뿐이라 둘 가운데 하나는 틀렸다","mis":"M5-2-u3-X08"},{"t":"넓이를 똑같이 나누는 선이면 모두 대칭축이다","mis":"M5-2-u3-X09"},{"t":"대칭축은 반 바퀴 돌려 보아야 찾을 수 있다","mis":"M5-2-u3-X15"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","정사각형처럼 그런 직선이 여러 개인 도형도 있어요.","그래서 서로 다르게 그어도 둘 다 맞을 수 있어요 — 접어 보고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#5','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'mc','auto','단원 평가 — 사다리꼴(대칭축 1개), 정사각형, 정삼각형, 원 가운데 대칭축이 가장 많은 선대칭도형은 어느 것인가요?',ARRAY['M5-2-u3-X19','M5-2-u3-X08']::text[],false,'{"seq":5,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"단원 평가 — 사다리꼴(대칭축 1개), 정사각형, 정삼각형, 원 가운데 대칭축이 가장 많은 선대칭도형은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M5-2-u3-X19"},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"사다리꼴","mis":"M5-2-u3-X08"}],"explanation":["정사각형은 4개, 정삼각형은 3개, 사다리꼴은 1개예요.","원은 지름을 따라 접으면 언제나 겹쳐 대칭축이 셀 수 없이 많아요.","그래서 대칭축이 가장 많은 것은 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#6','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'mc','auto','단원 평가 — 알파벳 C, X, F, J, M 가운데 선대칭도형 모양인 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X08','M5-2-u3-X17']::text[],false,'{"seq":6,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"단원 평가 — 알파벳 C, X, F, J, M 가운데 선대칭도형 모양인 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"C, X, M","correct":true},{"t":"C, X, F, M","mis":"M5-2-u3-X02"},{"t":"X","mis":"M5-2-u3-X08"},{"t":"F, J","mis":"M5-2-u3-X17"}],"explanation":["C는 가로선으로, M은 세로선으로, X는 세로선·가로선으로 접으면 완전히 겹쳐요.","F와 J는 어느 직선으로 접어도 겹치지 않아요.","그래서 C, X, M이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#7','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'ox','auto','타원은 곧은 변이 없어서 선대칭도형이 아니에요.',ARRAY['M5-2-u3-X19']::text[],false,'{"seq":7,"concept":"M5-2-u3-C4","difficulty":3,"kind":"ox","stem":"타원은 곧은 변이 없어서 선대칭도형이 아니에요.","answer":"X","reason_options":[{"t":"타원을 가로 가운데 선이나 세로 가운데 선으로 접으면 완전히 겹치므로","correct":true},{"t":"대칭축은 곧은 변이 있어야 그을 수 있으므로","mis":"M5-2-u3-X19"}],"mis":"M5-2-u3-X19","explanation":["곧은 변이 없으면 대칭축이 눈에 잘 띄지 않아요.","그래도 타원을 가로나 세로 가운데로 접어 보면 완전히 겹쳐요.","그래서 타원도 선대칭도형이에요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#8','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'essay','teacher','모눈 위의 도형 가(육각형)와 라(정사각형)의 대칭축은 각각 몇 개인지 쓰고, 대칭축을 찾은 방법을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":4,"kind":"essay","stem":"모눈 위의 도형 가(육각형)와 라(정사각형)의 대칭축은 각각 몇 개인지 쓰고, 대칭축을 찾은 방법을 써 보세요.","answer_guide":{"answer":"가는 2개(세로 가운데 선, 가로 가운데 선), 라는 4개(세로 가운데 선, 가로 가운데 선, 두 대각선)입니다. 도형을 여러 방향으로 접어 보고 완전히 겹치게 하는 직선을 모두 찾았습니다.","scoring_points":["가의 대칭축 2개를 바르게 썼는가","라의 대칭축 4개(대각선 포함)를 바르게 썼는가","접어서 완전히 겹치는 직선을 찾았다고 썼는가"]},"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","정사각형은 대각선으로 접어도 겹쳐요.","여러 방향으로 접어 보아야 빠뜨리지 않아요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[60,20],[100,40],[100,80],[60,100],[20,80],[20,40]]],"grid":20,"cap":"가"},{"w":100,"h":120,"poly":[[[40,20],[80,20],[60,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"나"},{"w":100,"h":120,"poly":[[[80,20],[80,100],[20,100],[20,80]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"circle":[[[60,60],40]],"grid":20,"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#9','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'essay','teacher','형성 평가 — 가(정오각형)와 다(직사각형)에 그은 직선이 대칭축이 아닌 까닭을 쓰고, 대칭축을 바르게 긋는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C4","difficulty":4,"kind":"essay","stem":"형성 평가 — 가(정오각형)와 다(직사각형)에 그은 직선이 대칭축이 아닌 까닭을 쓰고, 대칭축을 바르게 긋는 방법을 써 보세요.","answer_guide":{"answer":"가에 그은 선으로 접으면 양쪽이 완전히 겹치지 않으므로 대칭축이 아닙니다. 한 꼭짓점과 마주 보는 변의 가운데를 잇는 직선을 그어야 합니다. 다의 대각선으로 접으면 꼭짓점이 어긋나므로 대칭축이 아닙니다. 마주 보는 변의 가운데를 잇는 세로선이나 가로선을 그어야 합니다.","scoring_points":["두 선으로 접으면 완전히 겹치지 않는다고 썼는가","정오각형의 대칭축(꼭짓점과 마주 보는 변의 가운데)을 썼는가","직사각형의 대칭축(마주 보는 변의 가운데를 잇는 선)을 썼는가"]},"explanation":["대칭축인지는 그 선으로 접어 완전히 겹치는지로 알아요.","넓이를 반으로 나누는 선이라고 모두 대칭축은 아니에요.","직사각형의 대칭축은 2개, 정오각형의 대칭축은 5개예요."],"asset":{"type":"geo","items":[{"w":116.0,"h":84.36,"poly":[[[58.0,6.0],[96.04,33.64],[81.51,78.36],[34.49,78.36],[19.96,33.64]]],"seg":[[[6.0,24.0],[110.0,70.0]]],"cap":"가"},{"w":92.0,"h":140.0,"poly":[[[26.0,20.0],[66.0,20.0],[66.0,80.0],[86.0,80.0],[46.0,120.0],[6.0,80.0],[26.0,80.0]]],"seg":[[[46.0,6.0],[46.0,134.0]]],"cap":"나"},{"w":136.0,"h":74.0,"poly":[[[18.0,12.0],[118.0,12.0],[118.0,62.0],[18.0,62.0]]],"seg":[[[6.0,68.0],[130.0,6.0]]],"cap":"다"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L04_challenge#10','math',5,2,'u3','L04','tb_g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'sa','auto','익힘 — 알파벳 A, C, F, H, J, U의 대칭축의 수를 모두 더하면 몇 개인가요?','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C4","difficulty":4,"kind":"sa","stem":"익힘 — 알파벳 A, C, F, H, J, U의 대칭축의 수를 모두 더하면 몇 개인가요?","answer":["5"],"explanation":["A, C, U는 대칭축이 1개씩, H는 2개예요.","F와 J는 선대칭도형이 아니라 대칭축이 없어요.","1 + 1 + 2 + 1 = 5(개)예요."],"mis":"M5-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#1','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#2','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'mc','auto','선대칭도형 ㄱㄴㄷㄹㅁㅂ을 대칭축을 따라 접었어요. 점 ㄴ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":2,"concept":"M5-2-u3-C5","difficulty":1,"kind":"mc","stem":"선대칭도형 ㄱㄴㄷㄹㅁㅂ을 대칭축을 따라 접었어요. 점 ㄴ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㅁ","mis":"M5-2-u3-X06"},{"t":"점 ㄷ","mis":"M5-2-u3-X07"},{"t":"점 ㄱ","mis":"M5-2-u3-X06"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄴ은 대칭축 건너편의 점 ㅂ과 겹쳐요.","그래서 점 ㄴ의 대응점은 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":185.6,"h":208.0,"pts":{"ㄱ":[92.8,32.0,"n"],"ㄴ":[12.8,112.0,"w"],"ㄷ":[44.8,176.0,"sw"],"ㄹ":[92.8,160.0,"s"],"ㅁ":[140.8,176.0,"se"],"ㅂ":[172.8,112.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[92.8,12.8],[92.8,195.2]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선대칭도형 ㄱㄴㄷㄹㅁㅂ을 대칭축을 따라 접었어요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X06"},{"t":"점 ㄹ","mis":"M5-2-u3-X07"},{"t":"점 ㄴ","mis":"M5-2-u3-X06"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄷ은 대칭축 건너편의 점 ㅁ과 겹쳐요.","그래서 점 ㄷ의 대응점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":185.6,"h":208.0,"pts":{"ㄱ":[92.8,32.0,"n"],"ㄴ":[12.8,112.0,"w"],"ㄷ":[44.8,176.0,"sw"],"ㄹ":[92.8,160.0,"s"],"ㅁ":[140.8,176.0,"se"],"ㅂ":[172.8,112.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[92.8,12.8],[92.8,195.2]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
