INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#4','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'mc','auto','선대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄴㄷ의 대응변은 어느 것인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X06']::text[],true,'{"seq":4,"concept":"M5-2-u3-C5","difficulty":1,"kind":"mc","stem":"선대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄴㄷ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅂㅁ","correct":true},{"t":"변 ㄷㄹ","mis":"M5-2-u3-X07"},{"t":"변 ㅁㄹ","mis":"M5-2-u3-X07"},{"t":"변 ㄱㅂ","mis":"M5-2-u3-X06"}],"explanation":["점 ㄴ의 대응점은 점 ㅂ, 점 ㄷ의 대응점은 점 ㅁ이에요.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㅂㅁ이에요."],"asset":{"type":"geo","items":[{"w":185.6,"h":208.0,"pts":{"ㄱ":[92.8,32.0,"n"],"ㄴ":[12.8,112.0,"w"],"ㄷ":[44.8,176.0,"sw"],"ㄹ":[92.8,160.0,"s"],"ㅁ":[140.8,176.0,"se"],"ㅂ":[172.8,112.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[92.8,12.8],[92.8,195.2]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄱㄴ의 대응변은 어느 것인가요?","options":[{"t":"변 ㄱㅂ","correct":true},{"t":"변 ㄴㄷ","mis":"M5-2-u3-X07"},{"t":"변 ㅂㅁ","mis":"M5-2-u3-X06"},{"t":"변 ㄹㅁ","mis":"M5-2-u3-X06"}],"explanation":["점 ㄱ은 대칭축 위에 있어 대응점이 그 점 자신이에요.","점 ㄴ의 대응점은 점 ㅂ이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㄱㅂ이에요."],"asset":{"type":"geo","items":[{"w":185.6,"h":208.0,"pts":{"ㄱ":[92.8,32.0,"n"],"ㄴ":[12.8,112.0,"w"],"ㄷ":[44.8,176.0,"sw"],"ㄹ":[92.8,160.0,"s"],"ㅁ":[140.8,176.0,"se"],"ㅂ":[172.8,112.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[92.8,12.8],[92.8,195.2]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
