INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#6','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'sa','auto','대응점끼리 이은 선분 ㄴㅂ이 대칭축과 만나서 이루는 각의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"대응점끼리 이은 선분 ㄴㅂ이 대칭축과 만나서 이루는 각의 크기는 몇 도인가요?","answer":["90"],"explanation":["선분 ㄴㅂ과 대칭축은 점 ㅅ에서 만나요.","모눈에서 보면 선분 ㄴㅂ은 가로, 대칭축은 세로예요.","대칭축은 대응점끼리 이은 선분과 수직으로 만나 90°예요."],"mis":"M5-2-u3-X11","asset":{"type":"geo","items":[{"w":192.0,"h":208.0,"pts":{"ㄱ":[96.0,32.0,"n"],"ㄴ":[16.0,112.0,"w"],"ㄷ":[48.0,176.0,"sw"],"ㄹ":[96.0,160.0,"n"],"ㅁ":[144.0,176.0,"se"],"ㅂ":[176.0,112.0,"e"],"ㅅ":[96.0,112.0,"ne"],"ㅇ":[96.0,176.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[96.0,12.8],[96.0,195.2]]],"dash":[["ㄴ","ㅂ"],["ㄷ","ㅁ"]],"grid":16.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#7','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'mc','auto','선분 ㄴㅅ과 선분 ㅂㅅ의 길이를 비교하면 어떤가요?',ARRAY['M5-2-u3-X10','M5-2-u3-X02','M5-2-u3-X11']::text[],false,'{"seq":7,"concept":"M5-2-u3-C5","difficulty":2,"kind":"mc","stem":"선분 ㄴㅅ과 선분 ㅂㅅ의 길이를 비교하면 어떤가요?","options":[{"t":"두 선분의 길이가 같다","correct":true},{"t":"선분 ㄴㅅ이 선분 ㅂㅅ의 두 배이다","mis":"M5-2-u3-X10"},{"t":"선분 ㅂㅅ이 더 길다","mis":"M5-2-u3-X02"},{"t":"비교할 수 없다","mis":"M5-2-u3-X11"}],"explanation":["점 ㅅ은 대응점 ㄴ과 ㅂ을 이은 선분이 대칭축과 만나는 점이에요.","모눈을 세면 ㄴㅅ과 ㅂㅅ이 모두 5칸이에요.","대칭축은 대응점끼리 이은 선분을 똑같이 둘로 나눠요."],"asset":{"type":"geo","items":[{"w":192.0,"h":208.0,"pts":{"ㄱ":[96.0,32.0,"n"],"ㄴ":[16.0,112.0,"w"],"ㄷ":[48.0,176.0,"sw"],"ㄹ":[96.0,160.0,"n"],"ㅁ":[144.0,176.0,"se"],"ㅂ":[176.0,112.0,"e"],"ㅅ":[96.0,112.0,"ne"],"ㅇ":[96.0,176.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[96.0,12.8],[96.0,195.2]]],"dash":[["ㄴ","ㅂ"],["ㄷ","ㅁ"]],"grid":16.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#8','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'sa','auto','선대칭도형을 보고 답하세요. 변 ㄴㄷ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"선대칭도형을 보고 답하세요. 변 ㄴㄷ의 길이는 몇 cm인가요?","answer":["4"],"explanation":["대칭축을 따라 접으면 점 ㄴ은 점 ㅁ과, 점 ㄷ은 점 ㄹ과 겹쳐요.","변 ㄴㄷ의 대응변은 변 ㅁㄹ이에요.","대응변의 길이는 같으므로 4 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":140.84,"h":233.6,"pts":{"ㄱ":[70.0,34.0,"n"],"ㄴ":[16.0,127.53,"w"],"ㄷ":[40.62,195.19,"sw"],"ㄹ":[99.38,195.19,"se"],"ㅁ":[124.0,127.53,"e"],"ㅂ":[70.0,127.53,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[70.0,16.0],[70.0,217.6]]],"dash":[["ㄴ","ㅁ"]],"lab":[[[109.12,73.76],"6 cm"],[[124.84,166.15],"4 cm"],[[43.0,117.53],"3 cm"],[[61.72,64.91],"30°"],[[57.83,170.62],"110°"]],"arc":[["ㄴ","ㄱ",[70.0,127.53]],["ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선대칭도형을 보고 답하세요. 선분 ㅁㅂ의 길이는 몇 cm인가요?","answer":["3"],"explanation":["대칭축은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","선분 ㅁㅂ은 선분 ㄴㅂ과 길이가 같아요.","그래서 3 cm예요."],"asset":{"type":"geo","items":[{"w":140.84,"h":233.6,"pts":{"ㄱ":[70.0,34.0,"n"],"ㄴ":[16.0,127.53,"w"],"ㄷ":[40.62,195.19,"sw"],"ㄹ":[99.38,195.19,"se"],"ㅁ":[124.0,127.53,"e"],"ㅂ":[70.0,127.53,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[70.0,16.0],[70.0,217.6]]],"dash":[["ㄴ","ㅁ"]],"lab":[[[109.12,73.76],"6 cm"],[[124.84,166.15],"4 cm"],[[43.0,117.53],"3 cm"],[[61.72,64.91],"30°"],[[57.83,170.62],"110°"]],"arc":[["ㄴ","ㄱ",[70.0,127.53]],["ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"선대칭도형을 보고 답하세요. 각 ㄷㄹㅁ의 크기는 몇 도인가요?","answer":["110"],"explanation":["각 ㄷㄹㅁ의 대응각은 각 ㄹㄷㄴ이에요.","대응각의 크기는 같아요.","그래서 110°예요."],"asset":{"type":"geo","items":[{"w":140.84,"h":233.6,"pts":{"ㄱ":[70.0,34.0,"n"],"ㄴ":[16.0,127.53,"w"],"ㄷ":[40.62,195.19,"sw"],"ㄹ":[99.38,195.19,"se"],"ㅁ":[124.0,127.53,"e"],"ㅂ":[70.0,127.53,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[70.0,16.0],[70.0,217.6]]],"dash":[["ㄴ","ㅁ"]],"lab":[[[109.12,73.76],"6 cm"],[[124.84,166.15],"4 cm"],[[43.0,117.53],"3 cm"],[[61.72,64.91],"30°"],[[57.83,170.62],"110°"]],"arc":[["ㄴ","ㄱ",[70.0,127.53]],["ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"선대칭도형을 보고 답하세요. 각 ㅁㅂㄱ의 크기는 몇 도인가요?","answer":["90"],"explanation":["선분 ㄴㅁ은 대응점끼리 이은 선분이에요.","대칭축은 대응점끼리 이은 선분과 수직으로 만나요.","그래서 각 ㅁㅂㄱ은 90°예요."],"asset":{"type":"geo","items":[{"w":140.84,"h":233.6,"pts":{"ㄱ":[70.0,34.0,"n"],"ㄴ":[16.0,127.53,"w"],"ㄷ":[40.62,195.19,"sw"],"ㄹ":[99.38,195.19,"se"],"ㅁ":[124.0,127.53,"e"],"ㅂ":[70.0,127.53,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[70.0,16.0],[70.0,217.6]]],"dash":[["ㄴ","ㅁ"]],"lab":[[[109.12,73.76],"6 cm"],[[124.84,166.15],"4 cm"],[[43.0,117.53],"3 cm"],[[61.72,64.91],"30°"],[[57.83,170.62],"110°"]],"arc":[["ㄴ","ㄱ",[70.0,127.53]],["ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#9','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'mc','auto','선대칭도형 ㄱㄴㄷㄹㅁ에서 점 ㅁ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X06','M5-2-u3-X11']::text[],false,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":2,"kind":"mc","stem":"선대칭도형 ㄱㄴㄷㄹㅁ에서 점 ㅁ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X07"},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㄱ","mis":"M5-2-u3-X11"}],"explanation":["대칭축은 점 ㄱ을 지나요.","대칭축을 따라 접으면 점 ㅁ과 겹치는 꼭짓점은 점 ㄴ이에요.","그래서 점 ㅁ의 대응점은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":140.84,"h":233.6,"pts":{"ㄱ":[70.0,34.0,"n"],"ㄴ":[16.0,127.53,"w"],"ㄷ":[40.62,195.19,"sw"],"ㄹ":[99.38,195.19,"se"],"ㅁ":[124.0,127.53,"e"],"ㅂ":[70.0,127.53,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[70.0,16.0],[70.0,217.6]]],"dash":[["ㄴ","ㅁ"]],"lab":[[[109.12,73.76],"6 cm"],[[124.84,166.15],"4 cm"],[[43.0,117.53],"3 cm"],[[61.72,64.91],"30°"],[[57.83,170.62],"110°"]],"arc":[["ㄴ","ㄱ",[70.0,127.53]],["ㄴ","ㄷ","ㄹ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_basic#10','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',3,'mc','auto','선대칭도형에서 대칭축과 대응점끼리 이은 선분 사이의 관계로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X11']::text[],false,'{"seq":10,"concept":"M5-2-u3-C5","difficulty":3,"kind":"mc","stem":"선대칭도형에서 대칭축과 대응점끼리 이은 선분 사이의 관계로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭축은 대응점끼리 이은 선분과 수직으로 만나고, 그 선분을 똑같이 둘로 나눈다","correct":true},{"t":"대응점끼리 이은 선분은 모두 한 점에서 만난다","mis":"M5-2-u3-X15"},{"t":"대칭축은 그 선분과 수직으로 만나지만 길이는 나누지 않는다","mis":"M5-2-u3-X11"},{"t":"대칭축과 그 선분은 만나지 않는다","mis":"M5-2-u3-X11"}],"explanation":["선분 ㄴㅂ, 선분 ㄷㅁ과 대칭축이 이루는 각은 모두 90°였어요.","선분 ㄴㅅ = 선분 ㅂㅅ, 선분 ㄷㅇ = 선분 ㅁㅇ이었어요.","그래서 대칭축은 대응점끼리 이은 선분과 수직으로 만나고 똑같이 둘로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#1','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',2,'sa','auto','익힘 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 대칭축 한쪽에 그린 반쪽의 변의 길이가 2 cm, 4 cm, 3 cm일 때 완성한 선대칭도형의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":1,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"익힘 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 대칭축 한쪽에 그린 반쪽의 변의 길이가 2 cm, 4 cm, 3 cm일 때 완성한 선대칭도형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["선대칭도형은 대응변의 길이가 같아요.","반대쪽에도 2 cm, 4 cm, 3 cm인 변이 생겨요.","둘레는 (2 + 4 + 3) × 2 = 18(cm)예요."],"mis":"M5-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#2','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',2,'sa','auto','형성 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"형성 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["대칭축은 가로 직선이에요.","? cm인 변을 대칭축을 따라 접으면 6 cm인 변과 겹쳐요.","대응변의 길이는 같으므로 6 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":204.0,"h":192.0,"poly":[[[40.0,96.0],[80.0,16.0],[160.0,96.0],[80.0,176.0]]],"seg":[[[16.0,96.0],[188.0,96.0]]],"lab":[[[84.16,41.66],"70°"],[[129.9,46.1],"? cm"],[[119.35,79.16],"48°"],[[47.48,142.26],"5 cm"],[[129.9,145.9],"6 cm"],[[84.49,148.36],"?°"]],"arc":[[[40.0,96.0],[80.0,16.0],[160.0,96.0]],[[80.0,16.0],[160.0,96.0],[40.0,96.0]],[[40.0,96.0],[80.0,176.0],[160.0,96.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"형성 평가 — 선대칭도형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["70"],"explanation":["대칭축은 가로 직선이에요.","?°인 각을 접으면 70°인 각과 겹쳐요.","대응각의 크기는 같으므로 70°예요 — 48°는 다른 각이에요."],"asset":{"type":"geo","items":[{"w":204.0,"h":192.0,"poly":[[[40.0,96.0],[80.0,16.0],[160.0,96.0],[80.0,176.0]]],"seg":[[[16.0,96.0],[188.0,96.0]]],"lab":[[[84.16,41.66],"70°"],[[129.9,46.1],"? cm"],[[119.35,79.16],"48°"],[[47.48,142.26],"5 cm"],[[129.9,145.9],"6 cm"],[[84.49,148.36],"?°"]],"arc":[[[40.0,96.0],[80.0,16.0],[160.0,96.0]],[[80.0,16.0],[160.0,96.0],[40.0,96.0]],[[40.0,96.0],[80.0,176.0],[160.0,96.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=