INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#3','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'match','auto','형성 평가 — 선대칭도형에서 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M5-2-u3-C5","difficulty":3,"kind":"match","stem":"형성 평가 — 선대칭도형에서 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.","pairs":[{"l":"점 ㄴ의 대응점","r":"점 ㅂ"},{"l":"변 ㄷㄹ의 대응변","r":"변 ㅁㄹ"},{"l":"각 ㄱㄴㄷ의 대응각","r":"각 ㄱㅂㅁ"}],"mis":"M5-2-u3-X06","explanation":["대칭축은 점 ㄱ과 점 ㄹ을 지나요.","점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ이고 점 ㄱ·ㄹ은 대응점이 그 점 자신이에요.","대응변·대응각도 대응점의 순서대로 써요."],"asset":{"type":"geo","items":[{"w":160,"h":160,"pts":{"ㄱ":[80,40,"ne"],"ㄴ":[40,60,"nw"],"ㄷ":[20,120,"sw"],"ㄹ":[80,100,"n"],"ㅁ":[140,120,"se"],"ㅂ":[120,60,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[80,24.0],[80,136.0]]],"grid":20}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
