INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#5','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'sa','auto','단원 평가 — 선대칭도형에서 선분 ㄹㅂ의 길이는 몇 cm인가요?','{}'::text[],false,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"단원 평가 — 선대칭도형에서 선분 ㄹㅂ의 길이는 몇 cm인가요?","answer":["24"],"explanation":["점 ㄹ과 점 ㅂ은 대응점이고, 선분 ㄹㅂ은 대칭축과 점 ㅈ에서 만나요.","대칭축은 대응점끼리 이은 선분을 똑같이 둘로 나눠 선분 ㄹㅈ = 선분 ㅈㅂ = 12 cm예요.","선분 ㄹㅂ은 12 × 2 = 24(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":232.0,"h":192.0,"pts":{"ㄱ":[116.0,36.0,"ne"],"ㄴ":[46.0,76.0,"w"],"ㄷ":[66.0,106.0,"w"],"ㄹ":[16.0,156.0,"sw"],"ㅁ":[116.0,136.0,"n"],"ㅂ":[216.0,156.0,"se"],"ㅅ":[166.0,106.0,"e"],"ㅇ":[186.0,76.0,"e"],"ㅈ":[116.0,156.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[[[116.0,16.0],[116.0,176.0]]],"dash":[["ㄹ","ㅂ"]],"lab":[[[166.0,168.0],"12 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#6','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'sa','auto','형성 평가 — 선대칭도형에서 대칭축과 오른쪽 위 변이 이루는 각이 48°예요. 대칭축과 오른쪽 아래 변이 이루는 각은 몇 도인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"형성 평가 — 선대칭도형에서 대칭축과 오른쪽 위 변이 이루는 각이 48°예요. 대칭축과 오른쪽 아래 변이 이루는 각은 몇 도인가요?","answer":["48"],"explanation":["대칭축을 따라 접으면 오른쪽 위 변과 오른쪽 아래 변이 겹쳐요.","그래서 두 변이 대칭축과 이루는 각도 꼭 맞게 겹쳐요.","크기가 같으므로 48°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":204.0,"h":192.0,"poly":[[[40.0,96.0],[80.0,16.0],[160.0,96.0],[80.0,176.0]]],"seg":[[[16.0,96.0],[188.0,96.0]]],"lab":[[[84.16,41.66],"70°"],[[129.9,46.1],"? cm"],[[119.35,79.16],"48°"],[[47.48,142.26],"5 cm"],[[129.9,145.9],"6 cm"],[[84.49,148.36],"?°"]],"arc":[[[40.0,96.0],[80.0,16.0],[160.0,96.0]],[[80.0,16.0],[160.0,96.0],[40.0,96.0]],[[40.0,96.0],[80.0,176.0],[160.0,96.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#7','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'error','auto','단원 평가 — 선대칭도형을 보고 잘못 설명한 것을 찾아보세요.',ARRAY['M5-2-u3-X07','M5-2-u3-X06','M5-2-u3-X11']::text[],false,'{"seq":7,"concept":"M5-2-u3-C5","difficulty":3,"kind":"error","stem":"단원 평가 — 선대칭도형을 보고 잘못 설명한 것을 찾아보세요.","options":[{"t":"변 ㄱㄴ과 변 ㅁㅂ은 길이가 같습니다.","correct":true,"mis_target":"M5-2-u3-X07"},{"t":"점 ㄱ의 대응점은 점 ㅅ입니다.","mis":"M5-2-u3-X06"},{"t":"각 ㄱㅇㄹ의 크기는 90°입니다.","mis":"M5-2-u3-X11"}],"explanation":["대칭축은 점 ㅇ과 점 ㄹ을 지나요 — 점 ㄱ ↔ 점 ㅅ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ.","변 ㄱㄴ의 대응변은 변 ㅅㅂ이라 변 ㅁㅂ과 같다고 할 수 없어요.","대칭축은 대응점끼리 이은 선분 ㄱㅅ과 수직이라 각 ㄱㅇㄹ은 90°가 맞아요."],"asset":{"type":"geo","items":[{"w":192.0,"h":152.0,"pts":{"ㄱ":[16.0,36.0,"nw"],"ㄴ":[36.0,72.0,"w"],"ㄷ":[16.0,116.0,"sw"],"ㄹ":[96.0,96.0,"se"],"ㅁ":[176.0,116.0,"se"],"ㅂ":[156.0,72.0,"e"],"ㅅ":[176.0,36.0,"ne"],"ㅇ":[96.0,36.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[[[96.0,16.0],[96.0,136.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#8','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'sa','auto','단원 평가 — 선대칭도형에서 각 ㄴㄷㅂ의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C5","difficulty":4,"kind":"sa","stem":"단원 평가 — 선대칭도형에서 각 ㄴㄷㅂ의 크기는 몇 도인가요?","answer":["90"],"explanation":["직선 ㅂㄷ이 대칭축이고, 점 ㄴ과 점 ㄹ은 대응점이에요.","대칭축은 대응점끼리 이은 선분 ㄴㄹ과 수직으로 만나요.","그래서 각 ㄴㄷㅂ은 90°예요 — 70°와 95°는 쓰지 않아도 돼요."],"mis":"M5-2-u3-X11","asset":{"type":"geo","items":[{"w":192.0,"h":164.0,"pts":{"ㄱ":[48.0,36.0,"nw"],"ㄴ":[16.0,126.0,"sw"],"ㄷ":[96.0,126.0,"se"],"ㄹ":[176.0,126.0,"se"],"ㅁ":[144.0,36.0,"ne"],"ㅂ":[96.0,52.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[96.0,16.0],[96.0,148.0]]],"lab":[[[37.24,111.01],"70°"],[[132.6,59.37],"95°"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄹ","ㅁ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#9','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'sa','auto','단원 평가 — 선대칭도형인 사각형 ㄱㄴㄷㄹ의 둘레가 34 cm일 때 선분 ㄴㅂ의 길이는 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":4,"kind":"sa","stem":"단원 평가 — 선대칭도형인 사각형 ㄱㄴㄷㄹ의 둘레가 34 cm일 때 선분 ㄴㅂ의 길이는 몇 cm인가요?","answer":["7"],"explanation":["대응변이라 변 ㄱㄴ = 변 ㄹㄷ = 6 cm, 선분 ㄹㅁ = 선분 ㄱㅁ = 4 cm예요.","변 ㄴㄷ = 34 − 4 − 4 − 6 − 6 = 14(cm)예요.","대칭축이 변 ㄴㄷ을 똑같이 둘로 나누므로 선분 ㄴㅂ = 14 ÷ 2 = 7(cm)예요."],"mis":"M5-2-u3-X21","asset":{"type":"geo","items":[{"w":200.0,"h":122.35,"pts":{"ㄱ":[52.0,30.0,"nw"],"ㄴ":[16.0,92.35,"w"],"ㄷ":[184.0,92.35,"e"],"ㄹ":[148.0,30.0,"ne"],"ㅁ":[100.0,30.0,"ne"],"ㅂ":[100.0,92.35,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[100.0,16.0],[100.0,106.35]]],"lab":[[[76.0,16.0],"4 cm"],[[178.12,54.18],"6 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L05_challenge#10','math',5,2,'u3','L05','tb_g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'essay','teacher','선대칭도형의 성질 두 가지를 쓰고, 그 성질을 이용하여 선분 ㄷㅇ과 선분 ㅁㅇ의 길이를 비교해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C5","difficulty":4,"kind":"essay","stem":"선대칭도형의 성질 두 가지를 쓰고, 그 성질을 이용하여 선분 ㄷㅇ과 선분 ㅁㅇ의 길이를 비교해 보세요.","answer_guide":{"answer":"선대칭도형에서 대응변의 길이와 대응각의 크기는 각각 같습니다. 대칭축은 대응점끼리 이은 선분과 수직으로 만나고, 그 선분을 똑같이 둘로 나눕니다. 점 ㄷ과 점 ㅁ은 대응점이므로 선분 ㄷㅇ과 선분 ㅁㅇ의 길이는 같습니다.","scoring_points":["대응변의 길이·대응각의 크기가 같다고 썼는가","대칭축이 대응점끼리 이은 선분과 수직으로 만나고 똑같이 둘로 나눈다고 썼는가","선분 ㄷㅇ과 선분 ㅁㅇ이 같다고 썼는가"]},"explanation":["선대칭도형의 성질은 접어 보아 찾았어요.","대응점끼리 이은 선분은 대칭축이 수직으로 똑같이 나눠요.","그래서 선분 ㄷㅇ = 선분 ㅁㅇ이에요."],"asset":{"type":"geo","items":[{"w":192.0,"h":208.0,"pts":{"ㄱ":[96.0,32.0,"n"],"ㄴ":[16.0,112.0,"w"],"ㄷ":[48.0,176.0,"sw"],"ㄹ":[96.0,160.0,"n"],"ㅁ":[144.0,176.0,"se"],"ㅂ":[176.0,112.0,"e"],"ㅅ":[96.0,112.0,"ne"],"ㅇ":[96.0,176.0,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[96.0,12.8],[96.0,195.2]]],"dash":[["ㄴ","ㅂ"],["ㄷ","ㅁ"]],"grid":16.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#1','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려면 어떻게 그려야 할까요?',ARRAY['M5-2-u3-X12','M5-2-u3-X15','M5-2-u3-X10']::text[],false,'{"seq":1,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려면 어떻게 그려야 할까요?","options":[{"t":"선대칭도형의 성질을 이용하여 대응점을 찾아 선으로 잇는다","correct":true},{"t":"대칭축 위의 점을 반대쪽으로 옮겨 찍는다","mis":"M5-2-u3-X12"},{"t":"반쪽 도형을 반 바퀴 돌려 붙인다","mis":"M5-2-u3-X15"},{"t":"변의 길이를 두 배로 늘려 그린다","mis":"M5-2-u3-X10"}],"explanation":["대칭축과 대응점끼리 이은 선분 사이의 관계를 이용해요.","점 ㄱ, ㄴ, ㄷ의 대응점을 먼저 찾아 표시해요.","점들을 곧게 이으면 선대칭도형이 완성돼요."],"asset":{"type":"geo","items":[{"w":204.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#2','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X10']::text[],true,'{"seq":2,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅅ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X12"},{"t":"점 ㅇ","mis":"M5-2-u3-X12"},{"t":"점 ㅈ","mis":"M5-2-u3-X10"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 6칸 떨어져 있어요.","대응점은 대칭축과 수직인 방향(가로)으로 반대쪽 6칸 — 높이는 그대로예요.","그래서 점 ㅅ이에요."],"asset":{"type":"geo","items":[{"w":408.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"],"ㅂ":[306.0,51.0,"e"],"ㅅ":[289.0,51.0,"n"],"ㅇ":[289.0,68.0,"s"],"ㅈ":[391.0,51.0,"n"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄴ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㅅ","mis":"M5-2-u3-X10"},{"t":"점 ㅇ","mis":"M5-2-u3-X12"},{"t":"점 ㅈ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄴ은 대칭축에서 왼쪽으로 6칸 떨어져 있어요.","대응점은 대칭축과 수직인 방향(가로)으로 반대쪽 6칸 — 높이는 그대로예요.","그래서 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":408.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"],"ㅂ":[289.0,153.0,"n"],"ㅅ":[391.0,153.0,"n"],"ㅇ":[306.0,153.0,"e"],"ㅈ":[289.0,170.0,"s"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false}},{"stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄷ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅈ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X12"},{"t":"점 ㅅ","mis":"M5-2-u3-X12"},{"t":"점 ㅇ","mis":"M5-2-u3-X10"}],"explanation":["점 ㄷ은 대칭축에서 왼쪽으로 10칸 떨어져 있어요.","대응점은 대칭축과 수직인 방향(가로)으로 반대쪽 10칸 — 높이는 그대로예요.","그래서 점 ㅈ이에요."],"asset":{"type":"geo","items":[{"w":544.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"],"ㅂ":[357.0,306.0,"s"],"ㅅ":[374.0,289.0,"e"],"ㅇ":[527.0,289.0,"n"],"ㅈ":[357.0,289.0,"n"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#3','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','선대칭도형을 그릴 때 대칭축 위에 있는 꼭짓점의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X11','M5-2-u3-X06']::text[],false,'{"seq":3,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"선대칭도형을 그릴 때 대칭축 위에 있는 꼭짓점의 대응점은 어느 것인가요?","options":[{"t":"그 점 자신","correct":true},{"t":"대칭축 반대쪽으로 같은 거리만큼 간 점","mis":"M5-2-u3-X12"},{"t":"대응점이 없다","mis":"M5-2-u3-X11"},{"t":"가장 멀리 있는 꼭짓점","mis":"M5-2-u3-X06"}],"explanation":["대칭축을 따라 접어도 대칭축 위의 점은 움직이지 않아요.","그래서 대칭축 위에 있는 꼭짓점은 대응점이 그 점과 같아요.","그 점은 옮기지 않고 그대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#4','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','완성한 도형이 선대칭도형인지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X09','M5-2-u3-X02']::text[],false,'{"seq":4,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"완성한 도형이 선대칭도형인지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"투명 종이에 본뜬 다음 대칭축을 따라 접어 완전히 겹치는지 본다","correct":true},{"t":"본뜬 종이를 반 바퀴 돌려 겹치는지 본다","mis":"M5-2-u3-X15"},{"t":"넓이가 반으로 나뉘는지 본다","mis":"M5-2-u3-X09"},{"t":"양쪽에 같은 색을 칠해 본다","mis":"M5-2-u3-X02"}],"explanation":["선대칭도형은 대칭축을 따라 접었을 때 완전히 겹치는 도형이에요.","투명 종이에 내가 그린 도형을 본떠 접어 보면 확인할 수 있어요.","반 바퀴 돌리는 것은 점대칭도형을 확인하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#5','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'sa','auto','직선 ㄹㅁ이 대칭축이에요. 점 ㄷ의 대응점은 대칭축에서 오른쪽으로 몇 칸 떨어진 곳에 찍어야 하나요?','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C6","difficulty":2,"kind":"sa","stem":"직선 ㄹㅁ이 대칭축이에요. 점 ㄷ의 대응점은 대칭축에서 오른쪽으로 몇 칸 떨어진 곳에 찍어야 하나요?","answer":["10"],"explanation":["점 ㄷ은 대칭축에서 왼쪽으로 10칸 떨어져 있어요.","대칭축은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","그래서 대응점은 오른쪽으로 10칸 떨어진 곳이에요."],"mis":"M5-2-u3-X12","asset":{"type":"geo","items":[{"w":204.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 ㄹㅁ이 대칭축이에요. 점 ㄱ의 대응점은 대칭축에서 오른쪽으로 몇 칸 떨어진 곳에 찍어야 하나요?","answer":["6"],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 6칸 떨어져 있어요.","대칭축은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","그래서 대응점은 오른쪽으로 6칸 떨어진 곳이에요."],"asset":{"type":"geo","items":[{"w":204.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#6','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'mc','auto','선대칭도형을 그리는 차례로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X15','M5-2-u3-X11']::text[],false,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"선대칭도형을 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭축에 수선을 긋는다 → 같은 거리에 대응점을 찍는다 → 점을 차례로 곧게 잇는다","correct":true},{"t":"점을 차례로 잇는다 → 대응점을 찍는다 → 수선을 긋는다","mis":"M5-2-u3-X12"},{"t":"대칭축에 점을 찍는다 → 반 바퀴 돌린다 → 점을 잇는다","mis":"M5-2-u3-X15"},{"t":"대응점을 대칭축 위에 찍는다 → 점을 잇는다 → 접어 본다","mis":"M5-2-u3-X11"}],"explanation":["점 ㄱ, ㄴ, ㄷ에서 각각 대칭축에 수선을 그어요.","각 점에서 대칭축까지의 거리와 같도록 반대쪽에 대응점을 찍어요.","점들을 차례로 곧게 이어 완성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#7','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'mc','auto','직선 ㄱㄴ(가로)을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 가장 위에 있는 꼭짓점의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X10']::text[],false,'{"seq":7,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"직선 ㄱㄴ(가로)을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 가장 위에 있는 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㅁ","mis":"M5-2-u3-X10"},{"t":"점 ㅂ","mis":"M5-2-u3-X12"}],"explanation":["가장 위의 꼭짓점은 대칭축에서 위로 5칸 떨어져 있어요.","대칭축이 가로이면 대응점은 세로 방향(수직)으로 아래쪽 5칸 — 가로 자리는 그대로예요.","그래서 대칭축 아래 5칸, 같은 세로줄의 점이에요."],"asset":{"type":"geo","items":[{"w":306.0,"h":306.0,"pts":{"ㄱ":[27.0,108.0,"w"],"ㄴ":[279.0,108.0,"e"],"ㄷ":[162.0,198.0,"e"],"ㄹ":[144.0,198.0,"w"],"ㅁ":[144.0,288.0,"w"],"ㅂ":[144.0,216.0,"s"]},"seg":[[[27.0,108.0],[279.0,108.0]],[[54.0,108.0],[144.0,18.0]],[[144.0,18.0],[180.0,90.0]],[[180.0,90.0],[252.0,54.0]],[[252.0,54.0],[234.0,108.0]]],"grid":18.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#8','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'mc','auto','형성 평가 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하면 어떤 사각형이 되나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X12']::text[],false,'{"seq":8,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"형성 평가 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하면 어떤 사각형이 되나요?","options":[{"t":"사다리꼴","correct":true},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"직사각형","mis":"M5-2-u3-X12"},{"t":"삼각형","mis":"M5-2-u3-X12"}],"explanation":["왼쪽 반쪽의 위 꼭짓점은 대칭축에서 2칸, 아래 꼭짓점은 3칸 떨어져 있어요.","반대쪽에도 2칸, 3칸 떨어진 곳에 대응점을 찍어 이으면 위 변은 4칸, 아래 변은 6칸이에요.","위·아래 변만 평행한 사각형 — 사다리꼴이에요."],"asset":{"type":"geo","items":[{"w":100,"h":180,"pts":{"ㄱ":[80,36.0,"n"],"ㄴ":[80,144.0,"s"]},"seg":[[[80,36.0],[80,144.0]],[[40,60],[80,60]],[[40,60],[20,120]],[[20,120],[80,120]]],"grid":20}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#9','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'ox','auto','선대칭도형을 그릴 때 대응점은 대칭축과 수직인 방향으로, 대칭축까지와 같은 거리만큼 반대쪽에 찍어요.',ARRAY['M5-2-u3-X10']::text[],false,'{"seq":9,"concept":"M5-2-u3-C6","difficulty":2,"kind":"ox","stem":"선대칭도형을 그릴 때 대응점은 대칭축과 수직인 방향으로, 대칭축까지와 같은 거리만큼 반대쪽에 찍어요.","answer":"O","reason_options":[{"t":"대칭축은 대응점끼리 이은 선분과 수직으로 만나고 그 선분을 똑같이 둘로 나누므로","correct":true},{"t":"대응점은 대칭축까지 거리의 두 배만큼 반대쪽에 찍으므로","mis":"M5-2-u3-X10"}],"mis":"M5-2-u3-X10","explanation":["대칭축은 대응점끼리 이은 선분과 수직으로 만나요.","또 그 선분을 똑같이 둘로 나눠요.","그래서 수직 방향으로 같은 거리만큼 반대쪽에 찍어요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_basic#10','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',3,'mc','auto','익힘 — 예지는 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형 모양의 나뭇잎을 그리려고 해요. 바르게 그리려면 무엇을 지켜야 할까요?',ARRAY['M5-2-u3-X01','M5-2-u3-X12','M5-2-u3-X15']::text[],false,'{"seq":10,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"익힘 — 예지는 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형 모양의 나뭇잎을 그리려고 해요. 바르게 그리려면 무엇을 지켜야 할까요?","options":[{"t":"대칭축 양쪽의 대응점이 대칭축과 수직인 선 위에서 같은 거리에 있게 그린다","correct":true},{"t":"대칭축 한쪽 잎만 더 크게 그린다","mis":"M5-2-u3-X01"},{"t":"대칭축 위의 점을 모두 옆으로 옮긴다","mis":"M5-2-u3-X12"},{"t":"나뭇잎 반쪽을 반 바퀴 돌린 모양으로 그린다","mis":"M5-2-u3-X15"}],"explanation":["나뭇잎이 선대칭도형 모양이려면 대칭축으로 접었을 때 완전히 겹쳐야 해요.","그러려면 대응점이 대칭축과 수직인 선 위에서 같은 거리에 있어야 해요.","선대칭도형 모양이면 어떤 나뭇잎이든 정답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#1','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',2,'sa','auto','직선 ㄱㄴ(가로)이 대칭축이에요. 가장 위의 꼭짓점은 대칭축에서 위로 5칸 떨어져 있어요. 그 대응점은 대칭축에서 아래로 몇 칸 떨어진 곳에 찍어야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C6","difficulty":2,"kind":"sa","stem":"직선 ㄱㄴ(가로)이 대칭축이에요. 가장 위의 꼭짓점은 대칭축에서 위로 5칸 떨어져 있어요. 그 대응점은 대칭축에서 아래로 몇 칸 떨어진 곳에 찍어야 하나요?","answer":["5"],"explanation":["대칭축이 가로이면 대응점은 세로(수직) 방향으로 찾아요.","대칭축까지의 거리와 대응점까지의 거리는 같아요.","그래서 아래로 5칸이에요."],"mis":"M5-2-u3-X12","asset":{"type":"geo","items":[{"w":306.0,"h":126.0,"pts":{"ㄱ":[27.0,108.0,"w"],"ㄴ":[279.0,108.0,"e"]},"seg":[[[27.0,108.0],[279.0,108.0]],[[54.0,108.0],[144.0,18.0]],[[144.0,18.0],[180.0,90.0]],[[180.0,90.0],[252.0,54.0]],[[252.0,54.0],[234.0,108.0]]],"grid":18.0}],"tag":false},"variant_rule":{"alt":[{"stem":"직선 ㄱㄴ(가로)이 대칭축이에요. 오른쪽 위로 뾰족한 꼭짓점은 대칭축에서 위로 3칸 떨어져 있어요. 그 대응점은 대칭축에서 아래로 몇 칸 떨어진 곳에 찍어야 하나요?","answer":["3"],"explanation":["대칭축이 가로이면 대응점은 세로(수직) 방향으로 찾아요.","대칭축까지의 거리와 대응점까지의 거리는 같아요.","그래서 아래로 3칸이에요."],"asset":{"type":"geo","items":[{"w":306.0,"h":126.0,"pts":{"ㄱ":[27.0,108.0,"w"],"ㄴ":[279.0,108.0,"e"]},"seg":[[[27.0,108.0],[279.0,108.0]],[[54.0,108.0],[144.0,18.0]],[[144.0,18.0],[180.0,90.0]],[[180.0,90.0],[252.0,54.0]],[[252.0,54.0],[234.0,108.0]]],"grid":18.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#2','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',2,'mc','auto','함께하는 수학 — 「똑똑! 수학 탐험대」에서 선대칭도형을 선택하고 두 점을 선택하여 선분을 그렸어요. 이때 함께 나타나는 것은 무엇인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X01']::text[],false,'{"seq":2,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"함께하는 수학 — 「똑똑! 수학 탐험대」에서 선대칭도형을 선택하고 두 점을 선택하여 선분을 그렸어요. 이때 함께 나타나는 것은 무엇인가요?","options":[{"t":"대칭축 건너편의 대응점과 대응변","correct":true},{"t":"대칭의 중심","mis":"M5-2-u3-X15"},{"t":"반 바퀴 돌린 선분","mis":"M5-2-u3-X15"},{"t":"같은 선분을 옆으로 민 선분","mis":"M5-2-u3-X01"}],"explanation":["선대칭도형 도구는 대칭축을 기준으로 그려요.","선분을 그리면 대칭축 건너편에 대응점이 나타나고 대응변이 함께 그려져요.","이전에 그린 선분과 이어지도록 점을 선택해 도형을 완성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#3','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'mc','auto','함께하는 수학 — 선대칭도형을 그릴 때 선대칭도형의 어떤 성질을 이용하나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X09','M5-2-u3-X11']::text[],false,'{"seq":3,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"함께하는 수학 — 선대칭도형을 그릴 때 선대칭도형의 어떤 성질을 이용하나요?","options":[{"t":"대칭축은 대응점끼리 이은 선분과 수직으로 만나고 그 선분을 똑같이 둘로 나눈다","correct":true},{"t":"대응점끼리 이은 선분은 모두 대칭의 중심에서 만난다","mis":"M5-2-u3-X15"},{"t":"대칭축은 도형의 넓이를 반으로 나누는 선이다","mis":"M5-2-u3-X09"},{"t":"대칭축과 대응점끼리 이은 선분은 비스듬히 만난다","mis":"M5-2-u3-X11"}],"explanation":["대응점을 찾으려면 대칭축과 대응점끼리 이은 선분의 관계를 알아야 해요.","수직으로 만나고, 똑같이 둘로 나눠요.","대칭의 중심은 점대칭도형에서 쓰는 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#4','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'mc','auto','함께하는 수학 — 손가락 모양을 선택하여 선대칭도형의 꼭짓점을 움직여 보았어요. 어떻게 되나요?',ARRAY['M5-2-u3-X07','M5-2-u3-X11','M5-2-u3-X15']::text[],false,'{"seq":4,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"함께하는 수학 — 손가락 모양을 선택하여 선대칭도형의 꼭짓점을 움직여 보았어요. 어떻게 되나요?","options":[{"t":"대응점이 함께 움직여 대응변의 길이와 대응각의 크기가 계속 같다","correct":true},{"t":"움직인 꼭짓점만 바뀌어 선대칭도형이 아니게 된다","mis":"M5-2-u3-X07"},{"t":"대칭축이 사라진다","mis":"M5-2-u3-X11"},{"t":"도형이 반 바퀴 돈다","mis":"M5-2-u3-X15"}],"explanation":["꼭짓점을 움직이면 그 대응점도 대칭축 건너편에서 함께 움직여요.","그래서 언제나 선대칭도형이에요.","대응변의 길이와 대응각의 크기가 각각 같다는 성질을 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#5','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'mc','auto','함께하는 수학 — 대칭축 단추를 눌러 대칭축을 0°, 45°, 90°로 바꿀 수 있어요. 대칭축이 45°로 비스듬할 때 대응점은 어떻게 찾나요?',ARRAY['M5-2-u3-X12','M5-2-u3-X11']::text[],false,'{"seq":5,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"함께하는 수학 — 대칭축 단추를 눌러 대칭축을 0°, 45°, 90°로 바꿀 수 있어요. 대칭축이 45°로 비스듬할 때 대응점은 어떻게 찾나요?","options":[{"t":"비스듬한 대칭축과 수직인 방향으로 같은 거리만큼 반대쪽에서 찾는다","correct":true},{"t":"가로 방향으로만 같은 칸 수만큼 간다","mis":"M5-2-u3-X12"},{"t":"세로 방향으로만 같은 칸 수만큼 간다","mis":"M5-2-u3-X12"},{"t":"대칭축 위에 찍는다","mis":"M5-2-u3-X11"}],"explanation":["대칭축이 비스듬해도 성질은 같아요.","대응점끼리 이은 선분은 대칭축과 수직으로 만나고 똑같이 둘로 나뉘어요.","가로나 세로로만 세면 수직이 아니라 자리가 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#6','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'sa','auto','대칭수 만들기 — 두 자리 수 46을 골랐어요. 46 + 64 = 110이고 110은 대칭수가 아니라서 110 + 11을 했어요. 이렇게 만든 대칭수는 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":3,"kind":"sa","stem":"대칭수 만들기 — 두 자리 수 46을 골랐어요. 46 + 64 = 110이고 110은 대칭수가 아니라서 110 + 11을 했어요. 이렇게 만든 대칭수는 얼마인가요?","answer":["121"],"explanation":["대칭수는 앞에서부터 읽어도, 거꾸로 읽어도 같은 수예요.","110의 숫자를 거꾸로 쓰면(0은 비우고) 11이에요.","110 + 11 = 121 — 121은 거꾸로 읽어도 121이라 대칭수예요."],"variant_rule":{"alt":[{"stem":"대칭수 만들기 — 두 자리 수 14를 골랐어요. 14의 십의 자리 숫자와 일의 자리 숫자를 바꾸어 쓴 수를 더하면 어떤 대칭수가 되나요?","answer":["55"],"explanation":["14의 두 숫자를 바꾸어 쓰면 41이에요.","14 + 41 = 55예요.","55는 거꾸로 읽어도 55라 대칭수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#7','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'mc','auto','대응점을 찾아 도형을 완성했는데 완성한 도형이 선대칭도형이 아니었어요. 무엇을 해 보아야 할까요?',ARRAY['M5-2-u3-X02','M5-2-u3-X09','M5-2-u3-X15']::text[],false,'{"seq":7,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"대응점을 찾아 도형을 완성했는데 완성한 도형이 선대칭도형이 아니었어요. 무엇을 해 보아야 할까요?","options":[{"t":"완성한 도형을 본떠 대칭축으로 접어 보거나 대응변과 대응각을 비교해 본다","correct":true},{"t":"대칭축을 지우고 다시 아무렇게나 그린다","mis":"M5-2-u3-X02"},{"t":"넓이를 구해 반으로 나뉘는지 본다","mis":"M5-2-u3-X09"},{"t":"완성한 도형을 반 바퀴 돌려 본다","mis":"M5-2-u3-X15"}],"explanation":["어느 대응점이 어긋났는지 찾아야 해요.","본떠 접어 보면 겹치지 않는 곳이 보여요.","대응변의 길이와 대응각의 크기를 비교해 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#8','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'essay','teacher','선대칭도형을 그리는 방법을 대칭축과 대응점끼리 이은 선분 사이의 관계를 넣어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C6","difficulty":4,"kind":"essay","stem":"선대칭도형을 그리는 방법을 대칭축과 대응점끼리 이은 선분 사이의 관계를 넣어 설명해 보세요.","answer_guide":{"answer":"선대칭도형에서 대칭축은 대응점끼리 이은 선분과 수직으로 만나고 대응점끼리 이은 선분을 똑같이 둘로 나눈다는 성질을 이용합니다. 각 꼭짓점에서 대칭축에 수선을 긋고, 대칭축까지의 거리와 같도록 반대쪽에 대응점을 표시한 다음 점을 차례로 이어 선대칭도형을 그립니다.","scoring_points":["대칭축이 대응점끼리 이은 선분과 수직으로 만난다고 썼는가","같은 거리(똑같이 둘로 나눔)에 대응점을 찍는다고 썼는가","점을 차례로 이어 완성한다고 썼는가"]},"explanation":["대응점을 찾는 것이 먼저예요.","수선을 긋고 같은 거리만큼 반대쪽에 찍어요.","대칭축 위의 점은 그대로 두고 차례로 이어요."],"asset":{"type":"geo","items":[{"w":204.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#9','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'essay','teacher','점판에 나만의 선대칭도형을 그렸어요. 그린 도형이 선대칭도형인지 확인하는 방법을 두 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C6","difficulty":4,"kind":"essay","stem":"점판에 나만의 선대칭도형을 그렸어요. 그린 도형이 선대칭도형인지 확인하는 방법을 두 가지 써 보세요.","answer_guide":{"answer":"① 투명 종이에 그린 도형을 본뜬 다음 대칭축을 따라 접어 완전히 겹치는지 확인합니다. ② 대응변의 길이와 대응각의 크기가 각각 같은지, 대응점끼리 이은 선분이 대칭축과 수직으로 만나고 똑같이 둘로 나뉘는지 확인합니다.","scoring_points":["본떠 접어 보는 방법을 썼는가","대응변·대응각을 비교하는 방법을 썼는가","대칭축과 대응점끼리 이은 선분의 관계로 확인하는 방법을 썼는가(둘 가운데 하나 대신 가능)"]},"explanation":["선대칭도형은 접었을 때 완전히 겹쳐요.","성질(대응변·대응각이 같음)로도 확인할 수 있어요.","두 가지 방법을 쓰면 더 확실해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L06_challenge#10','math',5,2,'u3','L06','tb_g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'sa','auto','직선 ㄱㄴ(가로)을 대칭축으로 하는 선대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C6","difficulty":4,"kind":"sa","stem":"직선 ㄱㄴ(가로)을 대칭축으로 하는 선대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?","answer":["8"],"explanation":["그린 반쪽의 꼭짓점은 5개인데, 그 가운데 2개는 대칭축 위에 있어요.","대칭축 위의 2개는 대응점이 그 점 자신이고, 나머지 3개는 대칭축 아래에 대응점이 하나씩 생겨요.","그래서 2 + 3 + 3 = 8(개)예요."],"mis":"M5-2-u3-X12","asset":{"type":"geo","items":[{"w":306.0,"h":126.0,"pts":{"ㄱ":[27.0,108.0,"w"],"ㄴ":[279.0,108.0,"e"]},"seg":[[[27.0,108.0],[279.0,108.0]],[[54.0,108.0],[144.0,18.0]],[[144.0,18.0],[180.0,90.0]],[[180.0,90.0],[252.0,54.0]],[[252.0,54.0],[234.0,108.0]]],"grid":18.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#1','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#2','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','준비물을 위 도형에 겹쳐 놓고 점 ㄱ을 누름 못으로 고정한 다음 180° 돌려 보았어요. 어떻게 되나요?',ARRAY['M5-2-u3-X01','M5-2-u3-X14','M5-2-u3-X15']::text[],false,'{"seq":2,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"준비물을 위 도형에 겹쳐 놓고 점 ㄱ을 누름 못으로 고정한 다음 180° 돌려 보았어요. 어떻게 되나요?","options":[{"t":"돌리기 전과 완전히 겹친다","correct":true},{"t":"도형의 크기가 작아진다","mis":"M5-2-u3-X01"},{"t":"180°가 아니라 90°만 돌려야 겹친다","mis":"M5-2-u3-X14"},{"t":"도형이 뒤집혀 겹치지 않는다","mis":"M5-2-u3-X15"}],"explanation":["0°부터 180°까지 천천히 돌려 보면 180°에서 돌리기 전과 완전히 겹쳐요.","그래서 이 도형은 점대칭도형이에요.","점 ㄱ이 대칭의 중심이에요."],"asset":{"type":"geo","items":[{"w":172.0,"h":122.0,"pts":{"ㄱ":[86.0,61.0,"s"]},"poly":[[[16.0,16.0],[116.0,16.0],[116.0,56.0],[156.0,106.0],[56.0,106.0],[56.0,66.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#3','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','팽이에 그린 무늬는 똑바로 봐도, 돌려서 봐도 모양이 같아요. 이런 무늬의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X14','M5-2-u3-X09']::text[],false,'{"seq":3,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"팽이에 그린 무늬는 똑바로 봐도, 돌려서 봐도 모양이 같아요. 이런 무늬의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 점을 중심으로 180° 돌렸을 때 돌리기 전과 완전히 겹친다","correct":true},{"t":"한 직선을 따라 접으면 완전히 겹친다","mis":"M5-2-u3-X15"},{"t":"가운데에 점만 있으면 된다","mis":"M5-2-u3-X14"},{"t":"넓이를 반으로 나누는 선이 있다","mis":"M5-2-u3-X09"}],"explanation":["팽이가 돌아가듯 무늬를 돌려 보아요.","180° 돌렸을 때 돌리기 전과 완전히 겹치면 점대칭도형이에요.","가운데에 점이 있다는 것만으로는 점대칭도형이라고 할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#4','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'blank','auto','형성 평가 — 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#5','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'mc','auto','모눈 위의 도형 가~마 가운데 점대칭도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X14','M5-2-u3-X17']::text[],false,'{"seq":5,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"모눈 위의 도형 가~마 가운데 점대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다, 마","correct":true},{"t":"가, 다","mis":"M5-2-u3-X15"},{"t":"가, 나, 다, 마","mis":"M5-2-u3-X14"},{"t":"나, 라","mis":"M5-2-u3-X17"}],"explanation":["가(정사각형), 다(육각형), 마(평행사변형)는 가운데 점을 중심으로 180° 돌리면 완전히 겹쳐요.","나(삼각형)와 라(사다리꼴)는 180° 돌리면 모양이 거꾸로 되어 겹치지 않아요.","평행사변형처럼 대칭축이 없어도 점대칭도형일 수 있어요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"가"},{"w":120,"h":120,"poly":[[[60,20],[100,100],[20,100]]],"grid":20,"cap":"나"},{"w":120,"h":120,"poly":[[[40,20],[80,20],[100,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,40],[100,20],[100,100],[20,80]]],"grid":20,"cap":"라"},{"w":120,"h":120,"poly":[[[40,20],[100,20],[80,100],[20,100]]],"grid":20,"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#6','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'mc','auto','형성 평가 — 점대칭도형을 찾아보세요.',ARRAY['M5-2-u3-X15','M5-2-u3-X02']::text[],false,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"형성 평가 — 점대칭도형을 찾아보세요.","options":[{"t":"㉢","correct":true},{"t":"㉡","mis":"M5-2-u3-X15"},{"t":"㉣","mis":"M5-2-u3-X15"},{"t":"㉠","mis":"M5-2-u3-X02"}],"explanation":["㉢(육각형)은 가운데 점을 중심으로 180° 돌리면 완전히 겹쳐요.","㉡과 ㉣은 접으면 겹치는 선대칭도형이지만 180° 돌리면 겹치지 않아요.","㉠도 180° 돌리면 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[40,100]]],"grid":20,"cap":"㉠"},{"w":120,"h":120,"poly":[[[20,40],[60,20],[100,40],[60,100]]],"grid":20,"cap":"㉡"},{"w":120,"h":120,"poly":[[[40,20],[80,20],[100,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"㉢"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[60,100]]],"grid":20,"cap":"㉣"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#7','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'sa','auto','익힘 — 자음자 ㄴ, ㄷ, ㄹ, ㅂ, ㅅ, ㅇ 가운데 점대칭도형 모양은 모두 몇 개인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"익힘 — 자음자 ㄴ, ㄷ, ㄹ, ㅂ, ㅅ, ㅇ 가운데 점대칭도형 모양은 모두 몇 개인가요?","answer":["2"],"explanation":["자음자를 한 점을 중심으로 180° 돌려 보아요.","ㄹ과 ㅇ은 돌리기 전과 완전히 겹쳐요.","점대칭도형 모양은 2개예요."],"mis":"M5-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#8','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'sa','auto','익힘 — 호수가 컴퓨터에서 본 숫자 0, 1, 3, 8(디지털 숫자) 가운데 점대칭도형 모양인 숫자를 한 번씩만 써서 가장 큰 세 자리 수를 만들면 얼마인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"익힘 — 호수가 컴퓨터에서 본 숫자 0, 1, 3, 8(디지털 숫자) 가운데 점대칭도형 모양인 숫자를 한 번씩만 써서 가장 큰 세 자리 수를 만들면 얼마인가요?","answer":["810"],"explanation":["디지털 숫자 0, 1, 8은 180° 돌려도 모양이 같아요.","3은 180° 돌리면 모양이 달라져요.","0, 1, 8로 만든 가장 큰 세 자리 수는 810이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#9','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'ox','auto','점대칭도형인지 알아볼 때 시계 방향으로 돌리든 시계 반대 방향으로 돌리든 결과는 같아요.',ARRAY['M5-2-u3-X14']::text[],false,'{"seq":9,"concept":"M5-2-u3-C7","difficulty":2,"kind":"ox","stem":"점대칭도형인지 알아볼 때 시계 방향으로 돌리든 시계 반대 방향으로 돌리든 결과는 같아요.","answer":"O","reason_options":[{"t":"180°만큼 돌리면 어느 방향으로 돌려도 같은 자리에 오므로","correct":true},{"t":"점대칭도형은 시계 방향으로만 돌려 보아야 하므로","mis":"M5-2-u3-X14"}],"mis":"M5-2-u3-X14","explanation":["180°는 반 바퀴예요.","시계 방향으로 반 바퀴, 반대 방향으로 반 바퀴 돌린 모양은 같아요.","그래서 어느 쪽으로 돌려도 상관없어요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_basic#10','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',3,'ox','auto','가운데에 점이 있는 도형은 모두 점대칭도형이에요.',ARRAY['M5-2-u3-X14']::text[],false,'{"seq":10,"concept":"M5-2-u3-C7","difficulty":3,"kind":"ox","stem":"가운데에 점이 있는 도형은 모두 점대칭도형이에요.","answer":"X","reason_options":[{"t":"그 점을 중심으로 180° 돌렸을 때 완전히 겹쳐야 점대칭도형이므로","correct":true},{"t":"대칭의 중심이 있으면 점대칭도형이므로","mis":"M5-2-u3-X14"}],"mis":"M5-2-u3-X14","explanation":["점대칭도형은 180° 돌렸을 때 돌리기 전과 완전히 겹치는 도형이에요.","가운데에 점을 찍은 삼각형은 180° 돌리면 겹치지 않아요.","점이 있는 것만 보고 판단하면 안 돼요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#1','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',2,'mc','auto','주변에서 점대칭도형 모양을 찾았어요. 점대칭도형 모양이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],false,'{"seq":1,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"주변에서 점대칭도형 모양을 찾았어요. 점대칭도형 모양이 아닌 것은 어느 것인가요?","options":[{"t":"자음자 ㄷ","correct":true},{"t":"바람개비","mis":"M5-2-u3-X17"},{"t":"숫자 8","mis":"M5-2-u3-X17"},{"t":"자음자 ㄹ","mis":"M5-2-u3-X17"}],"explanation":["바람개비, 숫자 8, 자음자 ㄹ은 180° 돌리면 완전히 겹쳐요.","자음자 ㄷ은 180° 돌리면 열린 쪽이 반대로 가서 겹치지 않아요.","물음이 「아닌 것」을 묻는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#2','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',2,'blank','auto','빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#3','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','정사각형은 90°만큼 돌려도 처음과 겹쳐요. 정사각형에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X14','M5-2-u3-X20','M5-2-u3-X15']::text[],false,'{"seq":3,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"정사각형은 90°만큼 돌려도 처음과 겹쳐요. 정사각형에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"180° 돌려도 완전히 겹치므로 점대칭도형이다","correct":true},{"t":"90°에서 겹치므로 점대칭도형이 아니다","mis":"M5-2-u3-X14"},{"t":"선대칭도형이라서 점대칭도형일 수 없다","mis":"M5-2-u3-X20"},{"t":"대칭의 중심이 4개이다","mis":"M5-2-u3-X15"}],"explanation":["더 작은 각도만큼 돌려서 겹치는 도형도 180° 돌려서 겹치면 점대칭도형이에요.","정사각형은 선대칭도형이면서 점대칭도형이에요.","대칭의 중심은 오직 한 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#4','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','타원에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X19','M5-2-u3-X20']::text[],false,'{"seq":4,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"타원에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 점을 중심으로 180° 돌리면 완전히 겹치므로 점대칭도형이다","correct":true},{"t":"곧은 변이 없어서 점대칭도형이 아니다","mis":"M5-2-u3-X19"},{"t":"선대칭도형이므로 점대칭도형이 아니다","mis":"M5-2-u3-X20"},{"t":"곡선이라 대칭의 중심을 정할 수 없다","mis":"M5-2-u3-X19"}],"explanation":["타원은 곧은 변이 없어 대칭의 중심이 눈에 잘 띄지 않아요.","그래도 가운데 점을 중심으로 180° 돌려 보면 완전히 겹쳐요.","타원은 선대칭도형이면서 점대칭도형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#5','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'sa','auto','단원 평가 — 자음자 ㄹ, ㅂ, ㄷ, ㅅ, ㅇ, ㅁ 가운데 선대칭도형이면서 점대칭도형인 것은 모두 몇 개인가요?','{}'::text[],false,'{"seq":5,"concept":"M5-2-u3-C7","difficulty":3,"kind":"sa","stem":"단원 평가 — 자음자 ㄹ, ㅂ, ㄷ, ㅅ, ㅇ, ㅁ 가운데 선대칭도형이면서 점대칭도형인 것은 모두 몇 개인가요?","answer":["2"],"explanation":["ㅇ과 ㅁ은 접어도 겹치고 180° 돌려도 겹쳐요.","ㄹ은 점대칭도형만, ㅂ·ㄷ·ㅅ은 선대칭도형만이에요.","둘 다인 것은 ㅇ, ㅁ — 2개예요."],"mis":"M5-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#6','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','정삼각형은 120°, 240° 돌렸을 때 돌리기 전과 겹쳐요(회전 대칭). 정삼각형은 점대칭도형인가요?',ARRAY['M5-2-u3-X14','M5-2-u3-X15']::text[],false,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"정삼각형은 120°, 240° 돌렸을 때 돌리기 전과 겹쳐요(회전 대칭). 정삼각형은 점대칭도형인가요?","options":[{"t":"아니다 — 180° 돌리면 완전히 겹치지 않는다","correct":true},{"t":"그렇다 — 돌려서 겹치는 각도가 있으므로","mis":"M5-2-u3-X14"},{"t":"그렇다 — 가운데에 점을 찍을 수 있으므로","mis":"M5-2-u3-X14"},{"t":"그렇다 — 선대칭도형이므로","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형은 180° 돌렸을 때 완전히 겹쳐야 해요.","정삼각형을 180° 돌리면 꼭짓점이 아래를 향해 겹치지 않아요.","120°에서 겹쳐도 점대칭도형은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#7','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','단원 평가 — 정사각형, 평행사변형, 이등변삼각형 가운데 점대칭도형이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u3-X17','M5-2-u3-X15','M5-2-u3-X14']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"단원 평가 — 정사각형, 평행사변형, 이등변삼각형 가운데 점대칭도형이 아닌 것은 어느 것인가요?","options":[{"t":"이등변삼각형","correct":true},{"t":"정사각형","mis":"M5-2-u3-X17"},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"셋 다 점대칭도형이다","mis":"M5-2-u3-X14"}],"explanation":["정사각형과 평행사변형은 가운데 점을 중심으로 180° 돌리면 겹쳐요.","이등변삼각형은 180° 돌리면 꼭짓점이 반대쪽을 향해 겹치지 않아요.","그래서 점대칭도형이 아닌 것은 이등변삼각형이에요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 정삼각형, 정사각형, 사다리꼴 가운데 점대칭도형인 것은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X14"},{"t":"사다리꼴","mis":"M5-2-u3-X15"},{"t":"셋 다 점대칭도형이다","mis":"M5-2-u3-X14"}],"explanation":["정사각형은 가운데 점을 중심으로 180° 돌리면 완전히 겹쳐요.","정삼각형과 사다리꼴은 180° 돌리면 겹치지 않아요.","그래서 점대칭도형은 정사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#8','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'essay','teacher','모눈 위의 도형 나(삼각형)가 점대칭도형이 아닌 까닭을 「180°」를 넣어 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C7","difficulty":4,"kind":"essay","stem":"모눈 위의 도형 나(삼각형)가 점대칭도형이 아닌 까닭을 「180°」를 넣어 써 보세요.","answer_guide":{"answer":"삼각형 나는 어떤 점을 중심으로 180° 돌려도 돌리기 전과 완전히 겹치지 않기 때문입니다. 180° 돌리면 위쪽 꼭짓점이 아래쪽으로 가서 모양이 달라집니다.","scoring_points":["180° 돌린다고 썼는가","돌리기 전과 완전히 겹치지 않는다고 썼는가","꼭짓점의 방향이 바뀐다는 등 까닭을 덧붙였는가"]},"explanation":["점대칭도형은 180° 돌렸을 때 돌리기 전과 완전히 겹쳐야 해요.","삼각형은 180° 돌리면 꼭짓점이 아래로 가요.","그래서 점대칭도형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"가"},{"w":120,"h":120,"poly":[[[60,20],[100,100],[20,100]]],"grid":20,"cap":"나"},{"w":120,"h":120,"poly":[[[40,20],[80,20],[100,60],[80,100],[40,100],[20,60]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[20,40],[100,20],[100,100],[20,80]]],"grid":20,"cap":"라"},{"w":120,"h":120,"poly":[[[40,20],[100,20],[80,100],[20,100]]],"grid":20,"cap":"마"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#9','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'essay','teacher','점대칭도형을 찾기 어려워하는 친구에게 도형을 45°, 90°, 135°, 180°로 나누어 돌려 보여 주려고 해요. 어떤 각도에서 무엇을 확인해야 하는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C7","difficulty":4,"kind":"essay","stem":"점대칭도형을 찾기 어려워하는 친구에게 도형을 45°, 90°, 135°, 180°로 나누어 돌려 보여 주려고 해요. 어떤 각도에서 무엇을 확인해야 하는지 써 보세요.","answer_guide":{"answer":"180° 돌렸을 때 돌리기 전과 완전히 겹치는지 확인해야 합니다. 45°, 90°, 135°에서 겹치는지는 점대칭도형을 정하는 데 쓰지 않고, 180°에서 완전히 겹치면 점대칭도형입니다.","scoring_points":["180°에서 확인한다고 썼는가","돌리기 전과 완전히 겹치는지 본다고 썼는가","다른 각도에서 겹치는지로 정하지 않는다고 썼는가"]},"explanation":["도형을 천천히 돌리면 겹치는 순간을 볼 수 있어요.","점대칭도형은 180°에서 겹치는지로 정해요.","더 작은 각도에서 겹쳐도 180°에서 겹쳐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L07_challenge#10','math',5,2,'u3','L07','tb_g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'sa','auto','익힘 — 호수가 본 숫자 0, 1, 3, 8(디지털 숫자) 가운데 점대칭도형 모양인 숫자를 한 번씩만 써서 가장 작은 세 자리 수를 만들면 얼마인가요?','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C7","difficulty":4,"kind":"sa","stem":"익힘 — 호수가 본 숫자 0, 1, 3, 8(디지털 숫자) 가운데 점대칭도형 모양인 숫자를 한 번씩만 써서 가장 작은 세 자리 수를 만들면 얼마인가요?","answer":["108"],"explanation":["점대칭도형 모양인 숫자는 0, 1, 8이에요.","세 자리 수의 맨 앞에는 0이 올 수 없어요.","가장 작은 수는 108이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
