INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#2','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'mc','auto','점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 점 ㅇ이 대칭의 중심이에요. 점 ㄷ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X15']::text[],true,'{"seq":2,"concept":"M5-2-u3-C8","difficulty":1,"kind":"mc","stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 점 ㅇ이 대칭의 중심이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㅁ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X06"}],"explanation":["대응점은 대칭의 중심을 중심으로 180° 돌렸을 때 겹치는 점이에요.","점 ㄷ을 점 ㅇ을 중심으로 180° 돌리면 점 ㅂ과 겹쳐요.","그래서 점 ㄷ의 대응점은 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 점 ㅇ이 대칭의 중심이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X06"},{"t":"점 ㄴ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ을 점 ㅇ을 중심으로 180° 돌려 보아요.","점 ㄹ과 겹쳐요.","그래서 점 ㄱ의 대응점은 점 ㄹ이에요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
