INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#4','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'mc','auto','점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄱㄴ의 대응변은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X15','M5-2-u3-X07']::text[],true,'{"seq":4,"concept":"M5-2-u3-C8","difficulty":1,"kind":"mc","stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄱㄴ의 대응변은 어느 것인가요?","options":[{"t":"변 ㄹㅁ","correct":true},{"t":"변 ㅁㅂ","mis":"M5-2-u3-X06"},{"t":"변 ㄱㅂ","mis":"M5-2-u3-X15"},{"t":"변 ㄷㄹ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄱ의 대응점은 점 ㄹ, 점 ㄴ의 대응점은 점 ㅁ이에요.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㄹㅁ이에요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 변 ㄷㄹ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅂㄱ","correct":true},{"t":"변 ㄹㅁ","mis":"M5-2-u3-X07"},{"t":"변 ㄱㄴ","mis":"M5-2-u3-X06"},{"t":"변 ㅁㅂ","mis":"M5-2-u3-X15"}],"explanation":["점 ㄷ의 대응점은 점 ㅂ, 점 ㄹ의 대응점은 점 ㄱ이에요.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄷㄹ의 대응변은 변 ㅂㄱ이에요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#5','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 각 ㄱㄴㄷ의 대응각은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X07']::text[],true,'{"seq":5,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 각 ㄱㄴㄷ의 대응각은 어느 것인가요?","options":[{"t":"각 ㄹㅁㅂ","correct":true},{"t":"각 ㄱㅂㅁ","mis":"M5-2-u3-X15"},{"t":"각 ㄴㄷㄹ","mis":"M5-2-u3-X07"},{"t":"각 ㅁㅂㄱ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄱ ↔ 점 ㄹ, 점 ㄴ ↔ 점 ㅁ, 점 ㄷ ↔ 점 ㅂ이에요.","대응점의 순서에 맞게 쓰면 각 ㄹㅁㅂ이에요.","대응각의 크기는 같아요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 각 ㄷㄹㅁ의 대응각은 어느 것인가요?","options":[{"t":"각 ㅂㄱㄴ","correct":true},{"t":"각 ㄴㄷㄹ","mis":"M5-2-u3-X07"},{"t":"각 ㄱㄴㄷ","mis":"M5-2-u3-X06"},{"t":"각 ㅁㅂㄱ","mis":"M5-2-u3-X07"}],"explanation":["점 ㄷ ↔ 점 ㅂ, 점 ㄹ ↔ 점 ㄱ, 점 ㅁ ↔ 점 ㄴ이에요.","대응점의 순서에 맞게 쓰면 각 ㅂㄱㄴ이에요.","대응각의 크기는 같아요."],"asset":{"type":"geo","items":[{"w":153.6,"h":185.6,"pts":{"ㄱ":[76.8,12.8,"n"],"ㄴ":[12.8,92.8,"w"],"ㄷ":[12.8,172.8,"sw"],"ㄹ":[76.8,172.8,"s"],"ㅁ":[140.8,92.8,"e"],"ㅂ":[140.8,12.8,"ne"],"ㅇ":[76.8,92.8,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#6','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','점대칭도형에서 대응점끼리 잇는 선분을 모두 그었어요. 선분들은 어떤 점에서 만나나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X06']::text[],false,'{"seq":6,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"점대칭도형에서 대응점끼리 잇는 선분을 모두 그었어요. 선분들은 어떤 점에서 만나나요?","options":[{"t":"대칭의 중심인 점 ㅇ","correct":true},{"t":"만나지 않는다","mis":"M5-2-u3-X15"},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"선분마다 다른 점","mis":"M5-2-u3-X15"}],"explanation":["선분 ㄱㄹ, 선분 ㄴㅁ, 선분 ㄷㅂ을 그어 보아요.","세 선분은 모두 점 ㅇ을 지나요.","대응점끼리 이은 선분은 대칭의 중심에서 만나요."],"asset":{"type":"geo","items":[{"w":160.0,"h":192.0,"pts":{"ㄱ":[80.0,16.0,"n"],"ㄴ":[16.0,96.0,"w"],"ㄷ":[16.0,176.0,"sw"],"ㄹ":[80.0,176.0,"s"],"ㅁ":[144.0,96.0,"e"],"ㅂ":[144.0,16.0,"ne"],"ㅇ":[80.0,96.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"],["ㄴ","ㅁ"],["ㄷ","ㅂ"]],"grid":16.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#7','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','선분 ㄱㅇ과 선분 ㄹㅇ의 길이를 비교하면 어떤가요?',ARRAY['M5-2-u3-X10','M5-2-u3-X02','M5-2-u3-X15']::text[],false,'{"seq":7,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"선분 ㄱㅇ과 선분 ㄹㅇ의 길이를 비교하면 어떤가요?","options":[{"t":"두 선분의 길이가 같다","correct":true},{"t":"선분 ㄱㅇ이 선분 ㄹㅇ의 두 배이다","mis":"M5-2-u3-X10"},{"t":"선분 ㄹㅇ이 더 길다","mis":"M5-2-u3-X02"},{"t":"비교할 수 없다","mis":"M5-2-u3-X15"}],"explanation":["점 ㄱ과 점 ㄹ은 대응점이에요.","모눈을 세면 두 선분 모두 점 ㅇ에서 5칸이에요.","대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요."],"asset":{"type":"geo","items":[{"w":160.0,"h":192.0,"pts":{"ㄱ":[80.0,16.0,"n"],"ㄴ":[16.0,96.0,"w"],"ㄷ":[16.0,176.0,"sw"],"ㄹ":[80.0,176.0,"s"],"ㅁ":[144.0,96.0,"e"],"ㅂ":[144.0,16.0,"ne"],"ㅇ":[80.0,96.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"],["ㄴ","ㅁ"],["ㄷ","ㅂ"]],"grid":16.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#8','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'sa','auto','점대칭도형을 보고 답하세요. 변 ㄷㄹ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":2,"kind":"sa","stem":"점대칭도형을 보고 답하세요. 변 ㄷㄹ의 길이는 몇 cm인가요?","answer":["4"],"explanation":["점 ㅇ을 중심으로 180° 돌리면 점 ㄷ은 점 ㅂ과, 점 ㄹ은 점 ㄱ과 겹쳐요.","변 ㄷㄹ의 대응변은 변 ㅂㄱ이에요.","대응변의 길이는 같으므로 4 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":240.0,"h":322.8,"pts":{"ㄱ":[180.0,24.0,"ne"],"ㄴ":[24.0,181.2,"w"],"ㄷ":[84.0,181.2,"sw"],"ㄹ":[60.0,298.8,"sw"],"ㅁ":[216.0,141.6,"e"],"ㅂ":[156.0,141.6,"ne"],"ㅇ":[120.0,161.4,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"]],"lab":[[[117.0,92.7],"10 cm"],[[195.0,82.8],"4 cm"],[[186.0,123.6],"2 cm"],[[171.69,160.05],"40°"]],"arc":[["ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점대칭도형을 보고 답하세요. 각 ㄱㄴㄷ의 크기는 몇 도인가요?","answer":["40"],"explanation":["각 ㄱㄴㄷ의 대응각은 각 ㄹㅁㅂ이에요.","대응각의 크기는 같아요.","그래서 40°예요."],"asset":{"type":"geo","items":[{"w":240.0,"h":322.8,"pts":{"ㄱ":[180.0,24.0,"ne"],"ㄴ":[24.0,181.2,"w"],"ㄷ":[84.0,181.2,"sw"],"ㄹ":[60.0,298.8,"sw"],"ㅁ":[216.0,141.6,"e"],"ㅂ":[156.0,141.6,"ne"],"ㅇ":[120.0,161.4,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"]],"lab":[[[117.0,92.7],"10 cm"],[[195.0,82.8],"4 cm"],[[186.0,123.6],"2 cm"],[[171.69,160.05],"40°"]],"arc":[["ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"점대칭도형을 보고 답하세요. 선분 ㄱㅇ의 길이는 몇 cm인가요?","answer":["5"],"explanation":["대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","선분 ㄱㄹ은 10 cm예요.","선분 ㄱㅇ은 10 ÷ 2 = 5(cm)예요."],"asset":{"type":"geo","items":[{"w":240.0,"h":322.8,"pts":{"ㄱ":[180.0,24.0,"ne"],"ㄴ":[24.0,181.2,"w"],"ㄷ":[84.0,181.2,"sw"],"ㄹ":[60.0,298.8,"sw"],"ㅁ":[216.0,141.6,"e"],"ㅂ":[156.0,141.6,"ne"],"ㅇ":[120.0,161.4,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"]],"lab":[[[117.0,92.7],"10 cm"],[[195.0,82.8],"4 cm"],[[186.0,123.6],"2 cm"],[[171.69,160.05],"40°"]],"arc":[["ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#9','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','번개 모양 점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 점 ㄴ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X13']::text[],false,'{"seq":9,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"번개 모양 점대칭도형 ㄱㄴㄷㄹㅁㅂ에서 점 ㄴ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["대칭의 중심 ㅇ을 중심으로 180° 돌려 보아요.","왼쪽 끝의 점 ㄴ은 오른쪽 끝의 점 ㅁ과 겹쳐요.","그래서 점 ㄴ의 대응점은 점 ㅁ이에요 — 이름이 이웃한 점이 아니에요."],"asset":{"type":"geo","items":[{"w":240.0,"h":322.8,"pts":{"ㄱ":[180.0,24.0,"ne"],"ㄴ":[24.0,181.2,"w"],"ㄷ":[84.0,181.2,"sw"],"ㄹ":[60.0,298.8,"sw"],"ㅁ":[216.0,141.6,"e"],"ㅂ":[156.0,141.6,"ne"],"ㅇ":[120.0,161.4,"s"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄹ"]],"lab":[[[117.0,92.7],"10 cm"],[[195.0,82.8],"4 cm"],[[186.0,123.6],"2 cm"],[[171.69,160.05],"40°"]],"arc":[["ㄹ","ㅁ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_basic#10','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',3,'mc','auto','점대칭도형에서 대칭의 중심과 대응점끼리 이은 선분 사이의 관계로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X10']::text[],false,'{"seq":10,"concept":"M5-2-u3-C8","difficulty":3,"kind":"mc","stem":"점대칭도형에서 대칭의 중심과 대응점끼리 이은 선분 사이의 관계로 알맞은 것은 어느 것인가요?","options":[{"t":"대응점끼리 이은 선분은 대칭의 중심에서 만나고, 대칭의 중심은 그 선분을 똑같이 둘로 나눈다","correct":true},{"t":"대칭의 중심은 대응점끼리 이은 선분과 언제나 수직으로 만난다","mis":"M5-2-u3-X15"},{"t":"대응점끼리 이은 선분은 대칭의 중심을 지나지 않는다","mis":"M5-2-u3-X15"},{"t":"대칭의 중심에서 두 대응점까지의 거리는 서로 다르다","mis":"M5-2-u3-X10"}],"explanation":["선분 ㄱㄹ, ㄴㅁ, ㄷㅂ은 모두 점 ㅇ에서 만났어요.","선분 ㄱㅇ = 선분 ㄹㅇ처럼 점 ㅇ이 선분을 똑같이 나눴어요.","선대칭도형의 대칭축과 달리 수직으로 만나는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
