INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#3','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'match','auto','단원 평가 — 점대칭도형을 보고 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M5-2-u3-C8","difficulty":3,"kind":"match","stem":"단원 평가 — 점대칭도형을 보고 대응점, 대응변, 대응각을 찾아 선으로 이어 보세요.","pairs":[{"l":"점 ㄷ의 대응점","r":"점 ㅅ"},{"l":"변 ㄹㅁ의 대응변","r":"변 ㅇㄱ"},{"l":"각 ㄱㄴㄷ의 대응각","r":"각 ㅁㅂㅅ"}],"mis":"M5-2-u3-X06","explanation":["180° 돌리면 점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅅ, 점 ㄹ ↔ 점 ㅇ이에요.","대응변은 대응점끼리 이은 변이에요.","대응각도 대응점의 순서대로 써요."],"asset":{"type":"geo","items":[{"w":185.6,"h":135.2,"pts":{"ㄱ":[64.0,16.0,"nw"],"ㄴ":[16.0,48.4,"w"],"ㄷ":[24.4,102.4,"sw"],"ㄹ":[82.0,90.4,"s"],"ㅁ":[121.6,119.2,"se"],"ㅂ":[169.6,86.8,"e"],"ㅅ":[161.2,32.8,"ne"],"ㅇ":[103.6,44.8,"n"]," ":[92.8,67.6,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#4','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'sa','auto','단원 평가 — 점대칭도형에서 선분 ㄴㅁ의 길이는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"단원 평가 — 점대칭도형에서 선분 ㄴㅁ의 길이는 몇 cm인가요?","answer":["12"],"explanation":["점 ㄴ과 점 ㅁ은 대응점이고, 선분 ㄴㅁ은 대칭의 중심을 지나요.","대칭의 중심은 선분 ㄴㅁ을 똑같이 둘로 나누어 한쪽이 6 cm예요.","선분 ㄴㅁ은 6 × 2 = 12(cm)예요 — 5 cm는 다른 선분이에요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":192.0,"h":152.0,"pts":{"ㄱ":[66.0,16.0,"nw"],"ㄴ":[16.0,76.0,"w"],"ㄷ":[76.0,136.0,"s"],"ㄹ":[126.0,136.0,"se"],"ㅁ":[176.0,76.0,"e"],"ㅂ":[116.0,16.0,"n"]," ":[96.0,76.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄴ","ㅁ"],["ㄱ","ㄹ"],["ㄷ","ㅂ"]],"lab":[[[56.0,86.0],"6 cm"],[[118.0,50.0],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#5','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'sa','auto','익힘 — 점대칭도형을 보고 각 ㄴㅁㅂ의 크기는 몇 도인지 구해 보세요.','{}'::text[],false,'{"seq":5,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"익힘 — 점대칭도형을 보고 각 ㄴㅁㅂ의 크기는 몇 도인지 구해 보세요.","answer":["35"],"explanation":["대응각이라 각 ㅂㄱㄴ = 각 ㄷㄹㅁ = 90°예요.","사각형 ㄱㄴㅁㅂ의 네 각의 크기의 합은 360°예요.","각 ㄴㅁㅂ = 360° − 160° − 90° − 75° = 35°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":172.0,"h":147.92,"pts":{"ㄱ":[31.52,16.0,"nw"],"ㄴ":[16.0,73.96,"w"],"ㄷ":[72.82,113.78,"s"],"ㄹ":[140.48,131.92,"se"],"ㅁ":[156.0,73.96,"e"],"ㅂ":[99.18,34.14,"n"]," ":[86.0,73.96,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄴ","ㅁ"]],"lab":[[[90.72,52.26],"160°"],[[128.48,111.14],"90°"],[[41.39,54.48],"75°"]],"arc":[["ㄱ","ㅂ","ㅁ"],["ㄷ","ㄹ","ㅁ"],["ㄱ","ㄴ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#6','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'sa','auto','단원 평가 — 점대칭도형(평행사변형 ㄱㄴㄷㄹ)에서 각 ㄴㄷㄹ의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"단원 평가 — 점대칭도형(평행사변형 ㄱㄴㄷㄹ)에서 각 ㄴㄷㄹ의 크기는 몇 도인가요?","answer":["65"],"explanation":["대응각이라 각 ㄹㄱㄴ = 각 ㄴㄷㄹ, 각 ㄷㄹㄱ = 각 ㄱㄴㄷ = 115°예요.","사각형의 네 각의 크기의 합은 360°예요.","각 ㄴㄷㄹ = (360° − 115° − 115°) ÷ 2 = 65°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":179.0,"h":90.0,"pts":{"ㄱ":[16.0,16.0,"w"],"ㄴ":[43.0,74.0,"sw"],"ㄷ":[163.0,74.0,"e"],"ㄹ":[136.0,16.0,"ne"]," ":[89.5,45.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[55.9,53.76],"115°"]],"arc":[["ㄱ","ㄴ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#7','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'error','auto','단원 평가 — 점대칭도형에 대해 잘못 설명한 것을 찾아보세요.',ARRAY['M5-2-u3-X15','M5-2-u3-X10']::text[],false,'{"seq":7,"concept":"M5-2-u3-C8","difficulty":3,"kind":"error","stem":"단원 평가 — 점대칭도형에 대해 잘못 설명한 것을 찾아보세요.","options":[{"t":"대칭의 중심은 여러 개 있을 수 있습니다.","correct":true,"mis_target":"M5-2-u3-X15"},{"t":"각각의 대응점에서 대칭의 중심까지의 거리는 서로 같습니다.","mis":"M5-2-u3-X10"},{"t":"대응점끼리 이은 선분은 대칭의 중심을 지납니다.","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형에서 대칭의 중심은 오직 한 개예요.","대칭축이 여러 개일 수 있는 선대칭도형과 헷갈리면 안 돼요.","나머지 두 설명은 점대칭도형의 성질 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#8','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'essay','teacher','익힘 — 점대칭도형을 보고 각 ㄴㅁㅂ의 크기를 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":4,"kind":"essay","stem":"익힘 — 점대칭도형을 보고 각 ㄴㅁㅂ의 크기를 구하는 과정을 써 보세요.","answer_guide":{"answer":"점대칭도형에서 각 ㅂㄱㄴ의 크기는 대응각인 각 ㄷㄹㅁ의 크기와 같으므로 90°입니다. 사각형의 네 각의 크기의 합은 360°이므로 각 ㄴㅁㅂ의 크기는 360° − 160° − 90° − 75° = 35°입니다.","scoring_points":["각 ㅂㄱㄴ = 각 ㄷㄹㅁ = 90°(대응각)를 썼는가","사각형의 네 각의 크기의 합이 360°임을 썼는가","35°를 바르게 구했는가"]},"explanation":["먼저 모르는 각의 대응각을 찾아요.","사각형 ㄱㄴㅁㅂ의 네 각을 더하면 360°예요.","360° − 160° − 90° − 75° = 35°예요."],"asset":{"type":"geo","items":[{"w":172.0,"h":147.92,"pts":{"ㄱ":[31.52,16.0,"nw"],"ㄴ":[16.0,73.96,"w"],"ㄷ":[72.82,113.78,"s"],"ㄹ":[140.48,131.92,"se"],"ㅁ":[156.0,73.96,"e"],"ㅂ":[99.18,34.14,"n"]," ":[86.0,73.96,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄴ","ㅁ"]],"lab":[[[90.72,52.26],"160°"],[[128.48,111.14],"90°"],[[41.39,54.48],"75°"]],"arc":[["ㄱ","ㅂ","ㅁ"],["ㄷ","ㄹ","ㅁ"],["ㄱ","ㄴ","ㅁ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#9','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'sa','auto','단원 평가 — 점대칭도형(평행사변형)에서 선분 ㄴㄹ과 선분 ㄱㄷ의 길이의 차는 몇 cm인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C8","difficulty":4,"kind":"sa","stem":"단원 평가 — 점대칭도형(평행사변형)에서 선분 ㄴㄹ과 선분 ㄱㄷ의 길이의 차는 몇 cm인가요?","answer":["4"],"explanation":["대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","선분 ㄱㄷ = 6 + 6 = 12(cm), 선분 ㄴㄹ = 8 + 8 = 16(cm)예요.","두 선분의 길이의 차는 16 − 12 = 4(cm)예요 — 10 cm는 쓰지 않아요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":161.4,"h":140.0,"pts":{"ㄱ":[43.4,16.0,"nw"],"ㄴ":[16.0,110.0,"sw"],"ㄷ":[118.0,110.0,"se"],"ㄹ":[145.4,16.0,"ne"]," ":[80.7,63.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"dash":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"lab":[[[72.7,31.0],"6 cm"],[[118.7,53.0],"8 cm"],[[67.0,124.0],"10 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L08_challenge#10','math',5,2,'u3','L08','tb_g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'sa','auto','단원 평가 — 점대칭도형에서 각 ㄴㄱㅂ의 크기는 몇 도인가요?','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C8","difficulty":4,"kind":"sa","stem":"단원 평가 — 점대칭도형에서 각 ㄴㄱㅂ의 크기는 몇 도인가요?","answer":["125"],"explanation":["대응각이라 각 ㄱㄴㄷ = 각 ㄹㅁㅂ = 120°예요.","선분 ㄷㅂ이 도형을 둘로 나누어 사각형 ㄱㄴㄷㅂ이 생겨요.","각 ㄴㄱㅂ = 360° − 120° − 75° − 40° = 125°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":160.0,"h":138.4,"pts":{"ㄱ":[80.64,16.0,"n"],"ㄴ":[26.35,30.56,"nw"],"ㄷ":[16.0,69.2,"w"],"ㄹ":[79.36,122.4,"s"],"ㅁ":[133.65,107.84,"se"],"ㅂ":[144.0,69.2,"e"]," ":[80.0,69.2,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄷ","ㅂ"]],"lab":[[[113.93,58.25],"40°"],[[116.68,90.87],"120°"],[[39.8,50.94],"75°"]],"arc":[["ㄱ","ㅂ","ㄷ"],["ㄹ","ㅁ","ㅂ"],["ㄴ","ㄷ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#1','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려면 어떻게 그려야 할까요?',ARRAY['M5-2-u3-X15','M5-2-u3-X01','M5-2-u3-X13']::text[],false,'{"seq":1,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려면 어떻게 그려야 할까요?","options":[{"t":"점대칭도형의 성질을 이용하여 대응점을 찾아 선으로 잇는다","correct":true},{"t":"점 ㅇ을 지나는 대칭축을 긋고 접는다","mis":"M5-2-u3-X15"},{"t":"반쪽 도형을 그대로 옆으로 민다","mis":"M5-2-u3-X01"},{"t":"점 ㅇ까지만 선을 긋는다","mis":"M5-2-u3-X13"}],"explanation":["대칭의 중심과 대응점끼리 이은 선분 사이의 관계를 이용해요.","점 ㄱ, ㄴ, ㄷ의 대응점을 먼저 찾아 표시해요.","점들을 곧게 이으면 점대칭도형이 완성돼요."],"asset":{"type":"geo","items":[{"w":135.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#2','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":2,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅂ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽으로 5칸, 아래로 5칸 가요.","점 ㅇ을 지나 같은 만큼(오른쪽으로 5칸, 아래로 5칸) 한 번 더 가면 대응점이에요.","그래서 점 ㅁ이에요 — 가로나 세로 한쪽만 거꾸로 간 자리는 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":210.0,"h":180.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"],"ㄹ":[195.0,15.0,"e"],"ㅁ":[195.0,165.0,"nw"],"ㅂ":[45.0,165.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 점 ㄷ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㅁ","mis":"M5-2-u3-X15"},{"t":"점 ㅂ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄷ에서 점 ㅇ까지 오른쪽으로 7칸, 위로 4칸 가요.","점 ㅇ을 지나 같은 만큼(오른쪽으로 7칸, 위로 4칸) 한 번 더 가면 대응점이에요.","그래서 점 ㄹ이에요 — 가로나 세로 한쪽만 거꾸로 간 자리는 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":240.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"],"ㄹ":[225.0,30.0,"nw"],"ㅁ":[15.0,30.0,"w"],"ㅂ":[225.0,150.0,"e"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, dif