INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#3','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','점대칭도형에서 대칭의 중심을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X14','M5-2-u3-X15']::text[],false,'{"seq":3,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"점대칭도형에서 대칭의 중심을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대응점끼리 잇는 선분을 두 개 이상 그어 만나는 점을 찾는다","correct":true},{"t":"도형의 가장 위에 있는 꼭짓점을 찾는다","mis":"M5-2-u3-X14"},{"t":"대칭축 두 개를 그어 만나는 점을 찾는다","mis":"M5-2-u3-X15"},{"t":"도형의 가운데쯤에 눈으로 점을 찍는다","mis":"M5-2-u3-X14"}],"explanation":["점대칭도형에서 대응점끼리 이은 선분은 대칭의 중심에서 만나요.","그래서 대응점끼리 잇는 선분을 그으면 만나는 점이 대칭의 중심이에요.","눈대중으로 찍으면 정확하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#4','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','완성한 도형이 점대칭도형인지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X14','M5-2-u3-X09']::text[],false,'{"seq":4,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"완성한 도형이 점대칭도형인지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"투명 종이에 본뜬 다음 점 ㅇ을 중심으로 180° 돌려 완전히 겹치는지 본다","correct":true},{"t":"본뜬 종이를 대칭축을 따라 접어 본다","mis":"M5-2-u3-X15"},{"t":"본뜬 종이를 90°만 돌려 본다","mis":"M5-2-u3-X14"},{"t":"넓이가 반으로 나뉘는지 본다","mis":"M5-2-u3-X09"}],"explanation":["점대칭도형은 180° 돌렸을 때 돌리기 전과 완전히 겹치는 도형이에요.","투명 종이에 본떠 점 ㅇ을 누르고 돌려 보면 확인할 수 있어요.","접어 보는 것은 선대칭도형을 확인하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#5','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'sa','auto','점 ㄷ에서 대칭의 중심 ㅇ까지 가려면 오른쪽으로 7칸, 위로 4칸 가요. 점 ㄷ의 대응점은 점 ㅇ에서 오른쪽으로 몇 칸 더 간 곳에 있나요?','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C9","difficulty":2,"kind":"sa","stem":"점 ㄷ에서 대칭의 중심 ㅇ까지 가려면 오른쪽으로 7칸, 위로 4칸 가요. 점 ㄷ의 대응점은 점 ㅇ에서 오른쪽으로 몇 칸 더 간 곳에 있나요?","answer":["7"],"explanation":["대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","그래서 점 ㅇ을 지나 같은 만큼 한 번 더 가요.","오른쪽으로 7칸 더 가요(위로도 4칸 더)."],"mis":"M5-2-u3-X13","asset":{"type":"geo","items":[{"w":135.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㄷ에서 대칭의 중심 ㅇ까지 가려면 오른쪽으로 7칸, 위로 4칸 가요. 점 ㄷ의 대응점은 점 ㅇ에서 위로 몇 칸 더 간 곳에 있나요?","answer":["4"],"explanation":["대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","그래서 점 ㅇ을 지나 같은 만큼 한 번 더 가요.","위로 4칸 더 가요(오른쪽으로도 7칸 더)."],"asset":{"type":"geo","items":[{"w":135.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#6','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'mc','auto','점대칭도형을 그리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13','M5-2-u3-X10']::text[],false,'{"seq":6,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"점대칭도형을 그리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭의 중심에서 대응점까지의 거리가 같다는 성질로 대응점을 표시하고 점을 차례로 잇는다","correct":true},{"t":"대칭축과 수직인 방향으로 같은 거리에 대응점을 찍는다","mis":"M5-2-u3-X15"},{"t":"대칭의 중심에 대응점을 찍는다","mis":"M5-2-u3-X13"},{"t":"대칭의 중심까지 거리의 반만큼 간 곳에 찍는다","mis":"M5-2-u3-X10"}],"explanation":["각 꼭짓점에서 점 ㅇ을 지나는 직선을 그어요.","점 ㅇ까지의 거리와 같도록 반대쪽에 대응점을 찍어요.","점을 차례로 이어 점대칭도형을 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#7','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'sa','auto','형성 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-2-u3-C9","difficulty":2,"kind":"sa","stem":"형성 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?","answer":["6"],"explanation":["그린 반쪽에는 꼭짓점이 4개 있어요.","양 끝 두 점은 서로의 대응점이고, 나머지 두 꼭짓점은 점 ㅇ을 지나 반대쪽에 대응점이 하나씩 생겨요.","그래서 4 + 2 = 6(개)예요."],"mis":"M5-2-u3-X13","asset":{"type":"geo","items":[{"w":100,"h":140,"pts":{"ㅇ":[80,80,"e"]},"seg":[[[80,40],[20,20]],[[20,20],[20,120]],[[20,120],[80,120]]],"grid":20}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#8','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'mc','auto','형성 평가 — 점대칭도형에서 대칭의 중심은 어느 점인가요?',ARRAY['M5-2-u3-X14']::text[],false,'{"seq":8,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"형성 평가 — 점대칭도형에서 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄷ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["마주 보는 꼭짓점끼리 선분을 그어 보아요.","세 선분이 모두 점 ㄱ에서 만나요.","그래서 대칭의 중심은 점 ㄱ이에요 — 가운데쯤 보인다고 고르지 않아요."],"asset":{"type":"geo","items":[{"w":312.0,"h":208.0,"pts":{"ㄴ":[130.0,104.0,"w"],"ㄷ":[156.0,72.8,"n"],"ㄱ":[156.0,104.0,"e"],"ㄹ":[197.6,127.4,"e"]},"poly":[[[78.0,52.0],[156.0,26.0],[286.0,52.0],[234.0,156.0],[156.0,182.0],[26.0,156.0]]],"grid":26.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#9','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'ox','auto','점대칭도형을 그릴 때 대응점은 대칭의 중심까지만 가서 찍어요.',ARRAY['M5-2-u3-X13']::text[],false,'{"seq":9,"concept":"M5-2-u3-C9","difficulty":2,"kind":"ox","stem":"점대칭도형을 그릴 때 대응점은 대칭의 중심까지만 가서 찍어요.","answer":"X","reason_options":[{"t":"대칭의 중심을 지나 같은 거리만큼 더 간 곳에 찍어야 하므로","correct":true},{"t":"대칭의 중심이 곧 대응점이므로","mis":"M5-2-u3-X13"}],"mis":"M5-2-u3-X13","explanation":["대칭의 중심은 대응점끼리 이은 선분의 가운데에 있어요.","중심까지만 가면 대응점의 반밖에 못 가요.","중심을 지나 같은 만큼 더 가야 해요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_basic#10','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',3,'mc','auto','단원 평가 — 점대칭도형에서 대칭의 중심을 찾아 기호를 고르세요.',ARRAY['M5-2-u3-X14']::text[],false,'{"seq":10,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"단원 평가 — 점대칭도형에서 대칭의 중심을 찾아 기호를 고르세요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u3-X14"},{"t":"㉡","mis":"M5-2-u3-X14"},{"t":"㉣","mis":"M5-2-u3-X14"}],"explanation":["대응점끼리 잇는 선분을 그어 보아요.","선분들은 모두 ㉢에서 만나요.","㉠과 ㉡은 꼭짓점, ㉣은 가운데쯤 보이는 점일 뿐이에요."],"asset":{"type":"geo","items":[{"w":200,"h":120,"pts":{"㉠":[20,20,"nw"],"㉡":[60,60,"w"],"㉢":[100,60,"n"],"㉣":[140,78.0,"e"]},"poly":[[[20,20],[140,20],[140,60],[180,100],[60,100],[60,60]]],"grid":20}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#1','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',2,'mc','auto','함께하는 수학 — 「똑똑! 수학 탐험대」에서 점대칭도형을 선택하고 두 점을 선택하여 선분을 그렸어요. 이때 함께 그려지는 것은 무엇인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13','M5-2-u3-X01']::text[],false,'{"seq":1,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"함께하는 수학 — 「똑똑! 수학 탐험대」에서 점대칭도형을 선택하고 두 점을 선택하여 선분을 그렸어요. 이때 함께 그려지는 것은 무엇인가요?","options":[{"t":"대칭의 중심을 지나 반대쪽에 나타나는 대응점과 대응변","correct":true},{"t":"대칭축 건너편의 대응점과 대응변","mis":"M5-2-u3-X15"},{"t":"대칭의 중심까지 이어진 선분","mis":"M5-2-u3-X13"},{"t":"같은 선분을 옆으로 민 선분","mis":"M5-2-u3-X01"}],"explanation":["점대칭도형 도구는 대칭의 중심을 기준으로 그려요.","선분을 그리면 중심을 지나 반대쪽에 대응점이 나타나고 대응변이 함께 그려져요.","이전 선분과 이어지도록 점을 선택해 완성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#2','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',2,'mc','auto','함께하는 수학 — 점대칭도형을 그릴 때 점대칭도형의 어떤 성질을 이용하나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X07']::text[],false,'{"seq":2,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"함께하는 수학 — 점대칭도형을 그릴 때 점대칭도형의 어떤 성질을 이용하나요?","options":[{"t":"대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눈다","correct":true},{"t":"대칭축은 대응점끼리 이은 선분과 수직으로 만난다","mis":"M5-2-u3-X15"},{"t":"대응변의 길이는 서로 다르다","mis":"M5-2-u3-X07"},{"t":"대칭의 중심은 대응점끼리 이은 선분과 수직으로 만난다","mis":"M5-2-u3-X15"}],"explanation":["대응점을 찾으려면 대칭의 중심과 대응점의 관계를 써요.","대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나눠요.","수직으로 만난다는 것은 선대칭도형의 대칭축 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#3','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'mc','auto','텔레파시 놀이 — 도형이 반만 그려진 카드를 뽑아 선대칭도형과 점대칭도형 가운데 하나를 골라 나머지 반을 그려요. 친구와 같은 모양이 되려면 어떻게 해야 하나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X20','M5-2-u3-X03']::text[],false,'{"seq":3,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"텔레파시 놀이 — 도형이 반만 그려진 카드를 뽑아 선대칭도형과 점대칭도형 가운데 하나를 골라 나머지 반을 그려요. 친구와 같은 모양이 되려면 어떻게 해야 하나요?","options":[{"t":"같은 종류를 골라 대칭축이나 대칭의 중심을 기준으로 바르게 그려야 한다","correct":true},{"t":"어느 종류를 골라도 언제나 같은 모양이 된다","mis":"M5-2-u3-X15"},{"t":"반만 그려진 카드는 점대칭도형으로만 완성할 수 있다","mis":"M5-2-u3-X20"},{"t":"나머지 반은 크기를 다르게 그려도 된다","mis":"M5-2-u3-X03"}],"explanation":["같은 반쪽이라도 선대칭으로 완성할 때와 점대칭으로 완성할 때 모양이 달라요.","선대칭은 대칭축으로 접은 자리, 점대칭은 중심을 지나 180° 돌린 자리에 그려요.","같은 종류를 골라 바르게 그려야 같은 모양이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#4','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'sa','auto','점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-2-u3-C9","difficulty":3,"kind":"sa","stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?","answer":["8"],"explanation":["그린 반쪽의 꼭짓점은 점 ㅇ과 같은 세로줄의 두 점과 ㄱ, ㄴ, ㄷ이에요.","세로줄의 두 점은 서로의 대응점이고, ㄱ·ㄴ·ㄷ은 반대쪽에 대응점이 하나씩 생겨요.","그래서 2 + 3 + 3 = 8(개)예요."],"mis":"M5-2-u3-X13","asset":{"type":"geo","items":[{"w":135.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#5','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'mc','auto','점대칭도형에서 대응점끼리 이은 선분 두 개가 한 점에서 만났어요. 대응점끼리 이은 선분을 하나 더 그으면 어떻게 되나요?',ARRAY['M5-2-u3-X15']::text[],false,'{"seq":5,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"점대칭도형에서 대응점끼리 이은 선분 두 개가 한 점에서 만났어요. 대응점끼리 이은 선분을 하나 더 그으면 어떻게 되나요?","options":[{"t":"앞의 두 선분이 만난 점을 지난다","correct":true},{"t":"다른 점에서 만난다","mis":"M5-2-u3-X15"},{"t":"대칭의 중심을 지나지 않는다","mis":"M5-2-u3-X15"},{"t":"앞의 두 선분과 수직으로 만난다","mis":"M5-2-u3-X15"}],"explanation":["대응점끼리 이은 선분은 모두 대칭의 중심에서 만나요.","두 선분이 만난 점이 대칭의 중심이에요.","그래서 세 번째 선분도 그 점을 지나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#6','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'mc','auto','익힘 — 연서는 마을을 상징하는 그림을 점대칭도형 모양으로 디자인했어요. 이 그림의 대칭의 중심에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X14']::text[],false,'{"seq":6,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"익힘 — 연서는 마을을 상징하는 그림을 점대칭도형 모양으로 디자인했어요. 이 그림의 대칭의 중심에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림에서 대응점끼리 이은 선분들이 모두 만나는 한 점이다","correct":true},{"t":"그림에 그은 대칭축 위의 아무 점이다","mis":"M5-2-u3-X15"},{"t":"그림에서 가장 큰 무늬의 가운데 점이다","mis":"M5-2-u3-X14"},{"t":"그림마다 대칭의 중심이 여러 개 있다","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형에서 대응점끼리 이은 선분은 대칭의 중심에서 만나요.","대응점끼리 잇는 선분을 그어 만나는 점을 찾아 표시해요.","대칭의 중심은 오직 한 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#7','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'sa','auto','단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 완성한 점대칭도형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-2-u3-C9","difficulty":3,"kind":"sa","stem":"단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 완성한 점대칭도형의 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["점 ㅇ은 점선(빗변)의 가운데예요 — 반 바퀴 돌린 삼각형이 반대쪽에 생겨요.","완성한 도형은 가로 4 cm, 세로 3 cm인 직사각형이에요.","넓이는 4 × 3 = 12(cm²)예요."],"mis":"M5-2-u3-X13","asset":{"type":"geo","items":[{"w":130.0,"h":106.0,"pts":{"ㅇ":[74.0,46.0,"se"]},"seg":[[[34.0,16.0],[34.0,76.0]],[[34.0,76.0],[114.0,76.0]]],"dash":[[[34.0,16.0],[114.0,76.0]]],"lab":[[[16.0,46.0],"3 cm"],[[74.0,90.0],"4 cm"]],"right":[[[34.0,16.0],[34.0,76.0],[114.0,76.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#8','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',4,'essay','teacher','점대칭도형을 그리는 방법을 대칭의 중심과 대응점 사이의 관계를 넣어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C9","difficulty":4,"kind":"essay","stem":"점대칭도형을 그리는 방법을 대칭의 중심과 대응점 사이의 관계를 넣어 설명해 보세요.","answer_guide":{"answer":"각 꼭짓점에서 대칭의 중심 ㅇ을 지나는 직선을 긋고, 대칭의 중심에서 대응점까지의 거리가 같다는 성질을 이용하여 반대쪽에 대응점을 표시한 다음 점을 차례로 이어 점대칭도형을 그립니다.","scoring_points":["대칭의 중심을 지나는 직선을 긋는다고 썼는가","대칭의 중심에서 대응점까지의 거리가 같다고 썼는가","점을 차례로 이어 완성한다고 썼는가"]},"explanation":["대응점을 찾는 것이 먼저예요.","중심을 지나 같은 거리만큼 더 가서 찍어요.","차례로 이어 완성하고 돌려서 확인해요."],"asset":{"type":"geo","items":[{"w":135.0,"h":165.0,"pts":{"ㅇ":[120.0,90.0,"ne"],"ㄱ":[45.0,15.0,"w"],"ㄴ":[45.0,90.0,"w"],"ㄷ":[15.0,150.0,"w"]},"seg":[[[120.0,30.0],[45.0,15.0]],[[45.0,15.0],[45.0,90.0]],[[45.0,90.0],[15.0,150.0]],[[15.0,150.0],[120.0,150.0]]],"grid":15.0}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#9','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',4,'essay','teacher','대응점을 찾아 도형을 완성했는데 완성한 도형이 점대칭도형이 아니었어요. 무엇을 확인하고 어떻게 고칠지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C9","difficulty":4,"kind":"essay","stem":"대응점을 찾아 도형을 완성했는데 완성한 도형이 점대칭도형이 아니었어요. 무엇을 확인하고 어떻게 고칠지 써 보세요.","answer_guide":{"answer":"완성한 도형을 본떠 대칭의 중심을 중심으로 180° 돌려 보거나 대응변의 길이와 대응각의 크기를 비교하여 어긋난 대응점을 찾습니다. 그 점에서 대칭의 중심까지의 거리만큼 중심을 지나 반대쪽으로 다시 가서 대응점을 바르게 찍고 이어 고칩니다.","scoring_points":["180° 돌려 보거나 대응변·대응각을 비교한다고 썼는가","어긋난 대응점을 찾는다고 썼는가","중심을 지나 같은 거리에 다시 찍어 고친다고 썼는가"]},"explanation":["점대칭도형은 180° 돌렸을 때 완전히 겹쳐야 해요.","겹치지 않는 곳의 대응점이 잘못 찍힌 거예요.","중심을 지나 같은 거리에 다시 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L09_challenge#10','math',5,2,'u3','L09','tb_g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C8',4,'sa','auto','단원 평가 — 점대칭도형이에요. 이 도형의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C8","difficulty":4,"kind":"sa","stem":"단원 평가 — 점대칭도형이에요. 이 도형의 둘레는 몇 cm인가요?","answer":["38"],"explanation":["점대칭도형은 대응변의 길이가 같아요.","그림에 있는 7 cm, 7 cm, 5 cm인 변마다 길이가 같은 대응변이 하나씩 더 있어요.","둘레는 (7 + 7 + 5) × 2 = 38(cm)예요."],"mis":"M5-2-u3-X21","asset":{"type":"geo","items":[{"w":156.0,"h":129.2,"pts":{" ":[78.0,64.6,"n"]},"poly":[[[16.0,52.6],[51.0,113.2],[71.0,67.6],[140.0,76.6],[105.0,16.0],[85.0,61.6]]],"lab":[[[51.79,47.18],"7 cm"],[[21.38,89.9],"7 cm"],[[48.18,84.78],"5 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#1','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'mc','auto','기부 천사 할머니의 땅을 나누려고 해요. 땅을 나누는 조건을 바르게 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X05','M5-2-u3-X16']::text[],false,'{"seq":1,"concept":"M5-2-u3-C10","difficulty":1,"kind":"mc","stem":"기부 천사 할머니의 땅을 나누려고 해요. 땅을 나누는 조건을 바르게 고른 것은 어느 것인가요?","options":[{"t":"합동인 도형 4개로 나누고, 4개의 도형에 사과나무가 한 그루씩 들어가게 한다","correct":true},{"t":"넓이가 같은 도형 4개로 나눈다","mis":"M5-2-u3-X05"},{"t":"사과나무가 들어가게만 나눈다","mis":"M5-2-u3-X16"},{"t":"합동인 도형 4개로만 나눈다","mis":"M5-2-u3-X16"}],"explanation":["조건 ① 땅을 합동인 도형 4개로 나눠요.","조건 ② 4개의 합동인 도형에 사과나무가 한 그루씩 들어가요.","두 조건을 모두 지켜야 해요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#2','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'sa','auto','땅은 모양과 크기가 같은 정사각형 12개가 붙어 있는 모양이에요. 합동인 도형 4개로 나누려면 정사각형 몇 개가 붙어 있는 모양으로 나누어야 할까요?','{}'::text[],false,'{"seq":2,"concept":"M5-2-u3-C10","difficulty":1,"kind":"sa","stem":"땅은 모양과 크기가 같은 정사각형 12개가 붙어 있는 모양이에요. 합동인 도형 4개로 나누려면 정사각형 몇 개가 붙어 있는 모양으로 나누어야 할까요?","answer":["3"],"explanation":["합동인 도형은 크기가 같아 정사각형의 개수도 같아요.","정사각형 12개를 4개의 도형에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"mis":"M5-2-u3-X16","asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#3','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'mc','auto','문제를 어떻게 해결할 수 있을지 생각해 보았어요. 알맞은 계획은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":3,"concept":"M5-2-u3-C10","difficulty":1,"kind":"mc","stem":"문제를 어떻게 해결할 수 있을지 생각해 보았어요. 알맞은 계획은 어느 것인가요?","options":[{"t":"사과나무의 위치와 정사각형의 개수를 생각하여 모양과 크기가 같은 4개의 도형으로 나눈다","correct":true},{"t":"사과나무의 위치만 생각하여 나눈다","mis":"M5-2-u3-X16"},{"t":"정사각형의 개수만 생각하여 나눈다","mis":"M5-2-u3-X16"},{"t":"넓이만 같으면 모양은 달라도 되게 나눈다","mis":"M5-2-u3-X05"}],"explanation":["나무가 한 그루씩 들어가야 하니 사과나무의 위치를 봐요.","합동이려면 정사각형의 개수와 모양이 같아야 해요.","두 가지를 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#4','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'mc','auto','땅을 바르게 나누었는지 확인할 때 살펴볼 것을 바르게 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":4,"concept":"M5-2-u3-C10","difficulty":1,"kind":"mc","stem":"땅을 바르게 나누었는지 확인할 때 살펴볼 것을 바르게 고른 것은 어느 것인가요?","options":[{"t":"4개의 도형이 서로 합동인지와 사과나무가 한 그루씩 들어 있는지","correct":true},{"t":"도형이 4개인지만","mis":"M5-2-u3-X16"},{"t":"사과나무가 한 그루씩 들어 있는지만","mis":"M5-2-u3-X16"},{"t":"도형들의 넓이가 같은지만","mis":"M5-2-u3-X05"}],"explanation":["4개의 도형을 포개어 보면 합동인지 알 수 있어요.","도형마다 사과나무가 한 그루씩인지 세어 봐요.","두 가지가 모두 맞아야 바르게 나눈 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#5','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'mc','auto','땅을 세 가지로 나누어 보았어요. 조건에 맞게 나눈 것은 어느 것인가요?',ARRAY['M5-2-u3-X05','M5-2-u3-X16']::text[],false,'{"seq":5,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"땅을 세 가지로 나누어 보았어요. 조건에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u3-X05"},{"t":"다","mis":"M5-2-u3-X16"},{"t":"없다","mis":"M5-2-u3-X16"}],"explanation":["가는 ㄱ자 모양 4개로 서로 합동이고, 사과나무가 한 그루씩 들어 있어요.","나는 사과나무는 한 그루씩이지만 ㄱ자 모양과 일자 모양이 섞여 서로 합동이 아니에요.","다는 모양도 섞였고 사과나무가 두 그루 든 도형과 없는 도형이 있어요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[78.2,112.2],[78.2,146.2],[10.2,146.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[112.2,78.2],[112.2,112.2],[44.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]],"cap":"가"},{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[112.2,112.2],[112.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,112.2],[44.2,112.2]],[[78.2,78.2],[146.2,78.2],[146.2,146.2],[112.2,146.2],[112.2,112.2],[78.2,112.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]],"cap":"나"},{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,78.2],[44.2,78.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,146.2],[10.2,146.2]],[[44.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]],"cap":"다"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#6','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙어 있는 모양인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙어 있는 모양인가요?","answer":["3"],"explanation":["합동인 도형은 크기가 같아 정삼각형의 개수도 같아요.","정삼각형 12개를 4개의 도형에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"mis":"M5-2-u3-X16","asset":{"type":"geo","items":[{"w":240.8,"h":113.79,"poly":[[[36.4,56.9],[92.4,56.9],[64.4,8.4]],[[92.4,56.9],[148.4,56.9],[120.4,8.4]],[[148.4,56.9],[204.4,56.9],[176.4,8.4]],[[64.4,8.4],[120.4,8.4],[92.4,56.9]],[[120.4,8.4],[176.4,8.4],[148.4,56.9]],[[8.4,105.39],[64.4,105.39],[36.4,56.9]],[[64.4,105.39],[120.4,105.39],[92.4,56.9]],[[120.4,105.39],[176.4,105.39],[148.4,56.9]],[[176.4,105.39],[232.4,105.39],[204.4,56.9]],[[36.4,56.9],[92.4,56.9],[64.4,105.39]],[[92.4,56.9],[148.4,56.9],[120.4,105.39]],[[148.4,56.9],[204.4,56.9],[176.4,105.39]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#7','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'mc','auto','땅을 그림처럼 나누었어요. 바르게 나누지 못한 까닭은 무엇인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":7,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"땅을 그림처럼 나누었어요. 바르게 나누지 못한 까닭은 무엇인가요?","options":[{"t":"4개의 도형이 서로 합동이 아니다","correct":true},{"t":"사과나무가 한 그루씩 들어 있지 않다","mis":"M5-2-u3-X16"},{"t":"도형이 4개가 아니다","mis":"M5-2-u3-X16"},{"t":"도형마다 정사각형의 개수가 다르다","mis":"M5-2-u3-X05"}],"explanation":["도형마다 사과나무는 한 그루씩 들어 있어요.","도형마다 정사각형도 3개씩이에요.","그런데 ㄱ자 모양과 일자 모양이 섞여 포개어도 완전히 겹치지 않아 합동이 아니에요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[112.2,112.2],[112.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,112.2],[44.2,112.2]],[[78.2,78.2],[146.2,78.2],[146.2,146.2],[112.2,146.2],[112.2,112.2],[78.2,112.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#8','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'mc','auto','땅을 그림처럼 나누었어요. 조건에 맞지 않는 점을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],false,'{"seq":8,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"땅을 그림처럼 나누었어요. 조건에 맞지 않는 점을 바르게 말한 것은 어느 것인가요?","options":[{"t":"4개의 도형이 서로 합동이 아니고, 사과나무가 한 그루씩 들어가지 않은 도형도 있다","correct":true},{"t":"4개의 도형이 서로 합동이 아니라는 것만 어긋났다","mis":"M5-2-u3-X16"},{"t":"사과나무가 한 그루씩이 아니라는 것만 어긋났다","mis":"M5-2-u3-X16"},{"t":"조건에 모두 맞는다","mis":"M5-2-u3-X02"}],"explanation":["도형마다 정사각형은 3개씩이지만 ㄱ자 모양과 일자 모양이 섞여 서로 합동이 아니에요.","사과나무가 두 그루 든 도형과 한 그루도 없는 도형도 있어요.","두 조건이 모두 어긋났어요 — 조건은 하나씩 모두 확인해요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,78.2],[44.2,78.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,146.2],[10.2,146.2]],[[44.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#9','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'ox','auto','땅을 넓이가 같은 도형 4개로 나누면 언제나 합동인 도형 4개로 나눈 거예요.',ARRAY['M5-2-u3-X05']::text[],false,'{"seq":9,"concept":"M5-2-u3-C10","difficulty":2,"kind":"ox","stem":"땅을 넓이가 같은 도형 4개로 나누면 언제나 합동인 도형 4개로 나눈 거예요.","answer":"X","reason_options":[{"t":"넓이가 같아도 모양이 다르면 포개어 완전히 겹치지 않으므로","correct":true},{"t":"넓이가 같으면 크기가 같은 것이므로","mis":"M5-2-u3-X05"}],"mis":"M5-2-u3-X05","explanation":["정사각형 3개로 된 ㄱ자 모양과 일자 모양은 넓이가 같아요.","하지만 포개어도 완전히 겹치지 않아요.","그래서 넓이가 같다고 합동인 것은 아니에요 — 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_basic#10','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',3,'sa','auto','정사각형 3개가 붙어 있는 모양은 모두 몇 가지인가요? (돌리거나 뒤집어서 완전히 겹치는 모양은 한 가지로 봐요.)','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C10","difficulty":3,"kind":"sa","stem":"정사각형 3개가 붙어 있는 모양은 모두 몇 가지인가요? (돌리거나 뒤집어서 완전히 겹치는 모양은 한 가지로 봐요.)","answer":["2"],"explanation":["정사각형 3개를 한 줄로 붙이면 일자 모양이에요.","꺾어서 붙이면 ㄱ자 모양이에요.","돌리거나 뒤집어 겹치는 것을 한 가지로 보면 2가지예요."],"mis":"M5-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#1','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',2,'mc','auto','땅을 합동인 도형 4개로 나눌 때 한 도형이 정사각형 몇 개인지 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X16']::text[],false,'{"seq":1,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"땅을 합동인 도형 4개로 나눌 때 한 도형이 정사각형 몇 개인지 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"12 ÷ 4 = 3","correct":true},{"t":"12 − 4 = 8","mis":"M5-2-u3-X16"},{"t":"12 × 4 = 48","mis":"M5-2-u3-X16"},{"t":"12 + 4 = 16","mis":"M5-2-u3-X16"}],"explanation":["정사각형 12개를 4개의 도형에 똑같이 나누어요.","똑같이 나누는 것은 나눗셈이에요.","12 ÷ 4 = 3 — 정사각형 3개씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#2','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',2,'mc','auto','문제를 어떻게 해결했는지 설명한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":2,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"문제를 어떻게 해결했는지 설명한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"사과나무의 위치와 정사각형의 개수를 생각하여 정사각형 3개가 붙은 합동인 도형 4개로 나누었다","correct":true},{"t":"사과나무 4그루를 먼저 빼고 남은 정사각형 8개를 나누었다","mis":"M5-2-u3-X16"},{"t":"넓이가 같도록 아무렇게나 4조각으로 나누었다","mis":"M5-2-u3-X05"},{"t":"정사각형 4개가 붙은 도형 3개로 나누었다","mis":"M5-2-u3-X16"}],"explanation":["12 ÷ 4 = 3이라 정사각형 3개가 붙은 도형으로 나눠요.","사과나무가 한 그루씩 들어가게 위치를 생각해요.","친구의 설명을 잘 듣고 궁금한 점을 질문해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#3','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'mc','auto','조건에 맞게 땅을 나누었을 때 4개의 도형은 모두 어떤 모양인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":3,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"조건에 맞게 땅을 나누었을 때 4개의 도형은 모두 어떤 모양인가요?","options":[{"t":"정사각형 3개가 붙은 ㄱ자 모양","correct":true},{"t":"정사각형 3개가 붙은 일자 모양","mis":"M5-2-u3-X16"},{"t":"ㄱ자 모양 2개와 일자 모양 2개","mis":"M5-2-u3-X05"},{"t":"정사각형 4개가 붙은 모양","mis":"M5-2-u3-X16"}],"explanation":["합동이려면 4개의 도형이 모두 같은 모양이어야 해요.","일자 모양 4개로는 이 땅을 나눌 수 없어요.","사과나무 조건까지 맞는 나눔은 ㄱ자 모양 4개로 나눈 것 하나뿐이에요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#4','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'ox','auto','이 땅은 정사각형 3개가 한 줄로 붙은 일자 모양 4개로도 나눌 수 있어요.',ARRAY['M5-2-u3-X16']::text[],false,'{"seq":4,"concept":"M5-2-u3-C10","difficulty":3,"kind":"ox","stem":"이 땅은 정사각형 3개가 한 줄로 붙은 일자 모양 4개로도 나눌 수 있어요.","answer":"X","reason_options":[{"t":"어떻게 해도 일자 모양 4개로는 땅을 남김없이 나눌 수 없으므로","correct":true},{"t":"정사각형이 12개이므로 3개씩 한 줄로 나누면 되므로","mis":"M5-2-u3-X16"}],"mis":"M5-2-u3-X16","explanation":["왼쪽 위 두 줄은 가로로 2칸뿐이라 세로로만 일자 모양을 놓을 수 있어요.","세로로 놓으면 아래쪽에 남는 칸이 일자 모양으로 채워지지 않아요.","그래서 일자 모양 4개로는 나눌 수 없어요 — 틀린 말이에요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#5','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'mc','auto','정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누었어요. 나눈 도형 하나는 어떤 모양인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],false,'{"seq":5,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누었어요. 나눈 도형 하나는 어떤 모양인가요?","options":[{"t":"정삼각형 3개가 붙은 사다리꼴 모양","correct":true},{"t":"정삼각형 4개가 붙은 평행사변형 모양","mis":"M5-2-u3-X16"},{"t":"정삼각형 2개가 붙은 마름모 모양","mis":"M5-2-u3-X16"},{"t":"정삼각형 3개가 붙은 큰 정삼각형 모양","mis":"M5-2-u3-X02"}],"explanation":["12 ÷ 4 = 3이라 한 도형은 정삼각형 3개예요.","정삼각형 3개를 붙이면 사다리꼴 모양이 돼요.","4개의 도형이 모두 이 모양이라 서로 합동이에요."],"asset":{"type":"geo","items":[{"w":240.8,"h":113.79,"poly":[[[8.4,105.39],[64.4,105.39],[92.4,56.9],[64.4,8.4],[36.4,56.9]],[[64.4,8.4],[120.4,8.4],[176.4,8.4],[148.4,56.9],[92.4,56.9]],[[148.4,56.9],[176.4,8.4],[204.4,56.9],[232.4,105.39],[176.4,105.39]],[[64.4,105.39],[120.4,105.39],[176.4,105.39],[148.4,56.9],[92.4,56.9]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#6','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'sa','auto','조건에 맞게 나눈 도형 하나(정사각형 3개가 붙은 ㄱ자 모양)의 둘레에는 정사각형의 한 변이 몇 번 들어가나요?','{}'::text[],false,'{"seq":6,"concept":"M5-2-u3-C10","difficulty":3,"kind":"sa","stem":"조건에 맞게 나눈 도형 하나(정사각형 3개가 붙은 ㄱ자 모양)의 둘레에는 정사각형의 한 변이 몇 번 들어가나요?","answer":["8"],"explanation":["ㄱ자 모양의 바깥 둘레를 따라가며 정사각형의 변을 세어요.","긴 쪽 두 변은 2번씩, 나머지 네 변은 1번씩이에요.","2 + 2 + 1 + 1 + 1 + 1 = 8(번)이에요."],"mis":"M5-2-u3-X16","asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[78.2,112.2],[78.2,146.2],[10.2,146.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[112.2,78.2],[112.2,112.2],[44.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#7','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'mc','auto','땅을 정사각형 3개씩 4조각으로 남김없이 나누는 방법은 모두 7가지예요. 그 가운데 4조각이 서로 합동인 나눔은 몇 가지인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":7,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"땅을 정사각형 3개씩 4조각으로 남김없이 나누는 방법은 모두 7가지예요. 그 가운데 4조각이 서로 합동인 나눔은 몇 가지인가요?","options":[{"t":"1가지","correct":true},{"t":"2가지","mis":"M5-2-u3-X16"},{"t":"4가지","mis":"M5-2-u3-X16"},{"t":"7가지","mis":"M5-2-u3-X05"}],"explanation":["정사각형 3개씩 나누어도 ㄱ자 모양과 일자 모양이 섞이면 서로 합동이 아니에요.","7가지 가운데 4조각이 모두 같은 모양(ㄱ자)인 것은 교과서의 나눔 1가지뿐이에요.","그 나눔은 사과나무도 한 그루씩 들어가 조건에 꼭 맞아요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#8','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'essay','teacher','땅을 조건에 맞게 나누는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u3-C10","difficulty":4,"kind":"essay","stem":"땅을 조건에 맞게 나누는 방법을 설명해 보세요.","answer_guide":{"answer":"땅은 정사각형 12개가 붙어 있는 모양이므로 12 ÷ 4 = 3으로 정사각형 3개가 붙어 있는 모양으로 나눕니다. 사과나무의 위치를 생각하여 사과나무가 한 그루씩 들어가도록 ㄱ자 모양의 합동인 도형 4개로 나누었습니다.","scoring_points":["12 ÷ 4 = 3으로 정사각형 3개씩임을 썼는가","사과나무가 한 그루씩 들어가게 했다고 썼는가","4개의 도형이 서로 합동(ㄱ자 모양)이라고 썼는가"]},"explanation":["먼저 한 도형의 크기(정사각형 수)를 정해요.","사과나무의 위치를 보고 모양을 정해요.","마지막에 두 조건을 다시 확인해요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[78.2,112.2],[78.2,146.2],[10.2,146.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[112.2,78.2],[112.2,112.2],[44.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#9','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'essay','teacher','모양과 크기가 같은 정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누는 방법을 쓰고, 바르게 나누었는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u3-C10","difficulty":4,"kind":"essay","stem":"모양과 크기가 같은 정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누는 방법을 쓰고, 바르게 나누었는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"12 ÷ 4 = 3이므로 정삼각형 3개가 붙어 있는 모양(사다리꼴)으로 나눕니다. 나눈 4개의 도형을 포개어 보아 완전히 겹치면 서로 합동이므로 바르게 나눈 것입니다.","scoring_points":["12 ÷ 4 = 3으로 정삼각형 3개씩임을 썼는가","4개로 나눈 방법(정삼각형 3개가 붙은 모양)을 썼는가","포개어 합동인지 확인한다고 썼는가"]},"explanation":["정사각형 땅과 같은 방법으로 생각해요.","정삼각형 3개가 붙은 모양은 사다리꼴 모양이에요.","포개어 완전히 겹치는지 확인해요."],"asset":{"type":"geo","items":[{"w":240.8,"h":113.79,"poly":[[[36.4,56.9],[92.4,56.9],[64.4,8.4]],[[92.4,56.9],[148.4,56.9],[120.4,8.4]],[[148.4,56.9],[204.4,56.9],[176.4,8.4]],[[64.4,8.4],[120.4,8.4],[92.4,56.9]],[[120.4,8.4],[176.4,8.4],[148.4,56.9]],[[8.4,105.39],[64.4,105.39],[36.4,56.9]],[[64.4,105.39],[120.4,105.39],[92.4,56.9]],[[120.4,105.39],[176.4,105.39],[148.4,56.9]],[[176.4,105.39],[232.4,105.39],[204.4,56.9]],[[36.4,56.9],[92.4,56.9],[64.4,105.39]],[[92.4,56.9],[148.4,56.9],[120.4,105.39]],[[148.4,56.9],[204.4,56.9],[176.4,105.39]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_L10_challenge#10','math',5,2,'u3','L10','tb_g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'mc','auto','친구가 「땅을 정사각형 3개씩 4조각으로 나누었으니 바르게 나눈 거야.」라고 설명했어요. 친구에게 꼭 물어보아야 할 질문은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X16','M5-2-u3-X05']::text[],false,'{"seq":10,"concept":"M5-2-u3-C10","difficulty":4,"kind":"mc","stem":"친구가 「땅을 정사각형 3개씩 4조각으로 나누었으니 바르게 나눈 거야.」라고 설명했어요. 친구에게 꼭 물어보아야 할 질문은 어느 것인가요?","options":[{"t":"4개의 도형이 포개어 완전히 겹치고, 도형마다 사과나무가 한 그루씩 들어 있나요?","correct":true},{"t":"4조각의 색을 모두 다르게 칠했나요?","mis":"M5-2-u3-X02"},{"t":"정사각형의 넓이를 cm²로 재었나요?","mis":"M5-2-u3-X16"},{"t":"4조각의 넓이가 같나요?","mis":"M5-2-u3-X05"}],"explanation":["정사각형 3개씩이라고 해도 모양이 다르면 합동이 아니에요.","사과나무 조건도 확인해야 해요.","그래서 「합동인지」와 「사과나무가 한 그루씩인지」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_a#1','math',5,2,'u3','','tb_g5_2_math_u3_review_a','unit_review','M5-2-u3-C2',1,'mc','auto','문제로 마무리 — 서로 합동인 도형을 모두 찾아 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M5-2-u3-X04','M5-2-u3-X03']::text[],true,'{"seq":1,"concept":"M5-2-u3-C2","difficulty":1,"kind":"mc","stem":"문제로 마무리 — 서로 합동인 도형을 모두 찾아 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가와 다, 나와 마","correct":true},{"t":"가와 다","mis":"M5-2-u3-X04"},{"t":"나와 마","mis":"M5-2-u3-X04"},{"t":"가와 다, 나와 마, 다와 바","mis":"M5-2-u3-X03"}],"explanation":["가와 다는 돌려서, 나와 마는 뒤집어서 포개면 완전히 겹쳐요.","바는 정사각형이라 직사각형 가·다와 모양이 달라요.","그래서 가와 다, 나와 마예요."],"asset":{"type":"geo","items":[{"w":80,"h":120,"poly":[[[20,20],[60,20],[60,100],[20,100]]],"grid":20,"cap":"가"},{"w":120,"h":120,"poly":[[[20,20],[20,100],[100,100]]],"grid":20,"cap":"나"},{"w":120,"h":80,"poly":[[[20,20],[100,20],[100,60],[20,60]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[60,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[20,100]]],"grid":20,"cap":"마"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"바"}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 서로 합동인 도형을 모두 찾아 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가와 사, 다와 마","correct":true},{"t":"다와 마","mis":"M5-2-u3-X04"},{"t":"가와 사, 다와 마, 마와 아","mis":"M5-2-u3-X03"},{"t":"나와 바, 다와 마","mis":"M5-2-u3-X03"}],"explanation":["가와 사는 뒤집어서 포개면 완전히 겹쳐요.","다와 마는 반지름이 같은 원이라 겹쳐요 — 아는 더 작은 원이에요.","나와 바는 둘 다 직사각형이지만 크기가 달라요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,60],[80,20],[80,60]]],"grid":20,"cap":"가"},{"w":60,"h":100,"poly":[[[20,20],[50.0,20],[50.0,80],[20,80]]],"grid":20,"cap":"나"},{"w":100,"h":100,"circle":[[[50.0,50.0],30.0]],"grid":20,"cap":"다"},{"w":100,"h":100,"poly":[[[20,20],[80,20],[50.0,72.0]]],"grid":20,"cap":"라"},{"w":100,"h":100,"circle":[[[50.0,50.0],30.0]],"grid":20,"cap":"마"},{"w":60,"h":80,"poly":[[[20,20],[50.0,20],[50.0,64.0],[20,64.0]]],"grid":20,"cap":"바"},{"w":100,"h":80,"poly":[[[20,20],[20,60],[80,60]]],"grid":20,"cap":"사"},{"w":80,"h":80,"circle":[[[42.0,42.0],22.0]],"grid":20,"cap":"아"}],"tag":false}},{"stem":"단원 평가 — 도형 가와 합동인 도형을 찾아보세요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u3-X03"},{"t":"㉢","mis":"M5-2-u3-X02"},{"t":"없어요","mis":"M5-2-u3-X04"}],"explanation":["㉡은 도형 가를 돌려 세운 모양이라 포개면 완전히 겹쳐요.","㉠은 정사각형, ㉢은 한쪽이 비스듬한 사각형이라 겹치지 않아요.","돌려서 겹쳐도 합동이에요."],"asset":{"type":"geo","items":[{"w":76.0,"h":56.0,"poly":[[[8.0,8.0],[68.0,8.0],[68.0,48.0],[8.0,48.0]]],"cap":"도형 가"},{"w":56.0,"h":56.0,"poly":[[[8.0,8.0],[48.0,8.0],[48.0,48.0],[8.0,48.0]]],"cap":"㉠"},{"w":56.0,"h":76.0,"poly":[[[8.0,8.0],[48.0,8.0],[48.0,68.0],[8.0,68.0]]],"cap":"㉡"},{"w":76.0,"h":56.0,"poly":[[[8.0,8.0],[48.0,8.0],[68.0,48.0],[8.0,48.0]]],"cap":"㉢"}],"tag":false}},{"stem":"단원 평가 — 나머지 셋과 합동이 아닌 도형은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M5-2-u3-X17"},{"t":"나","mis":"M5-2-u3-X04"},{"t":"라","mis":"M5-2-u3-X04"}],"explanation":["가, 나, 라는 뒤집거나 돌리면 서로 완전히 겹쳐요.","다는 모양도 크기도 달라 겹치지 않아요.","물음이 「합동이 아닌」 도형을 묻는 것을 확인해요."],"asset":{"type":"geo","items":[{"w":80.0,"h":56.0,"poly":[[[8.0,8.0],[8.0,48.0],[72.0,48.0]]],"cap":"가"},{"w":80.0,"h":56.0,"poly":[[[72.0,8.0],[72.0,48.0],[8.0,48.0]]],"cap":"나"},{"w":68.0,"h":48.0,"poly":[[[8.0,40.0],[60.0,40.0],[34.0,8.0]]],"cap":"다"},{"w":56.0,"h":80.0,"poly":[[[8.0,8.0],[48.0,8.0],[8.0,72.0]]],"cap":"라"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
