 대응변은 오른쪽 도형의 왼쪽 변이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":309.6,"h":139.2,"poly":[[[38.4,33.6],[134.4,33.6],[134.4,105.6],[58.68,85.32],[38.4,105.6]],[[194.4,105.6],[290.4,105.6],[290.4,33.6],[214.68,53.88],[194.4,33.6]]],"lab":[[[86.4,19.2],"? cm"],[[19.2,69.6],"? cm"],[[47.58,83.43],"45°"],[[115.41,80.85],"75°"],[[175.2,69.6],"3 cm"],[[242.4,120.0],"4 cm"],[[271.41,58.35],"?°"]],"arc":[[[38.4,33.6],[38.4,105.6],[58.68,85.32]],[[58.68,85.32],[134.4,105.6],[134.4,33.6]],[[214.68,53.88],[290.4,33.6],[290.4,105.6]]]}],"tag":false}},{"stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?","answer":["6"],"explanation":["120°인 각끼리 대응각이라 점 ㄷ ↔ 점 ㅁ이에요.","변 ㄱㄷ의 대응변은 변 ㄹㅁ이에요.","대응변의 길이는 같으므로 6 cm예요."],"asset":{"type":"geo","items":[{"w":344.0,"h":120.75,"pts":{"ㄱ":[148.0,16.0,"ne"],"ㄴ":[16.0,78.35,"w"],"ㄷ":[112.0,78.35,"s"],"ㄹ":[196.0,42.35,"nw"],"ㅂ":[328.0,104.75,"e"],"ㅁ":[232.0,104.7,"s"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅂ","ㅁ"]],"lab":[[[64.0,90.35],"8 cm"],[[101.0,59.3],"120°"],[[201.88,80.53],"6 cm"],[[267.13,62.7],"12 cm"],[[219.54,64.03],"35°"]],"arc":[[[148.0,16.0],[112.0,78.35],[16.0,78.35]],[[328.0,104.75],[196.0,42.35],[232.0,104.7]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
