],[48.0,28.0],[88.0,8.0],[88.0,68.0],[48.0,48.0],[8.0,68.0]]],"cap":"라"},{"w":96.0,"h":64.0,"poly":[[[28.0,8.0],[68.0,8.0],[88.0,56.0],[8.0,56.0]]],"cap":"마"},{"w":76.0,"h":80.0,"poly":[[[28.0,8.0],[68.0,8.0],[68.0,48.0],[48.0,48.0],[48.0,72.0],[8.0,72.0],[8.0,32.0],[28.0,32.0]]],"cap":"바"}],"tag":false}},{"stem":"주변에서 찾은 모양 가운데 점대칭도형 모양을 모두 고른 것은 어느 것인가요? (네잎클로버, 숫자 8, 자음자 ㄷ, 알파벳 F)","options":[{"t":"네잎클로버, 숫자 8","correct":true},{"t":"네잎클로버, 숫자 8, 자음자 ㄷ","mis":"M5-2-u3-X15"},{"t":"숫자 8","mis":"M5-2-u3-X19"},{"t":"자음자 ㄷ, 알파벳 F","mis":"M5-2-u3-X17"}],"explanation":["네잎클로버와 숫자 8은 180° 돌리면 겹쳐요.","자음자 ㄷ은 접으면 겹치지만 180° 돌리면 겹치지 않아요.","알파벳 F는 접어도 돌려도 겹치지 않아요."],"asset":null},{"stem":"단원 평가 — 정삼각형, 정사각형, 사다리꼴 가운데 점대칭도형을 찾아보세요.","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X14"},{"t":"사다리꼴","mis":"M5-2-u3-X15"},{"t":"셋 다","mis":"M5-2-u3-X14"}],"explanation":["정사각형은 가운데 점을 중심으로 180° 돌리면 겹쳐요.","정삼각형은 120°에서 겹쳐도 180°에서는 겹치지 않아요.","사다리꼴은 접으면 겹치지만 돌리면 겹치지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_a#7','math',5,2,'u3','','tb_g5_2_math_u3_review_a','unit_review','M5-2-u3-C7',1,'mc','auto','문제로 마무리 — 점대칭도형의 대칭의 중심은 어느 점인가요?',ARRAY['M5-2-u3-X14']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"문제로 마무리 — 점대칭도형의 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄷ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["대응점끼리 잇는 선분을 그어 보아요.","선분들이 모두 점 ㄱ에서 만나요.","그래서 대칭의 중심은 점 ㄱ이에요."],"asset":{"type":"geo","items":[{"w":156.0,"h":156.0,"pts":{"ㄴ":[78.0,46.8,"e"],"ㄱ":[78.0,78.0,"e"],"ㄷ":[57.2,101.4,"w"],"ㄹ":[98.8,109.2,"e"]},"poly":[[[26.0,26.0],[52.0,26.0],[104.0,78.0],[104.0,26.0],[130.0,26.0],[130.0,130.0],[104.0,130.0],[52.0,78.0],[52.0,130.0],[26.0,130.0]]],"grid":26.0}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 점대칭도형의 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X14"},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["마주 보는 꼭짓점끼리 선분을 그어 보아요.","네 선분이 모두 점 ㄷ에서 만나요.","그래서 대칭의 중심은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":162.0,"h":126.0,"pts":{"ㄱ":[63.0,63.0,"w"],"ㄴ":[81.0,45.0,"n"],"ㄷ":[81.0,63.0,"e"],"ㄹ":[99.0,77.4,"e"]},"poly":[[[9.0,9.0],[63.0,27.0],[81.0,9.0],[153.0,16.2],[153.0,117.0],[99.0,99.0],[81.0,117.0],[9.0,109.8]]]}],"tag":false}},{"stem":"단원 평가 — 점대칭도형에서 대칭의 중심을 찾아 기호를 고르세요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u3-X14"},{"t":"㉡","mis":"M5-2-u3-X14"},{"t":"㉣","mis":"M5-2-u3-X14"}],"explanation":["대응점끼리 잇는 선분을 그어 보아요.","선분들이 모두 ㉢에서 만나요.","꼭짓점이나 가운데쯤 보이는 점을 고르지 않아요."],"asset":{"type":"geo","items":[{"w":200,"h":120,"pts":{"㉠":[20,20,"nw"],"㉡":[60,60,"w"],"㉢":[100,60,"n"],"㉣":[140,78.0,"e"]},"poly":[[[20,20],[140,20],[140,60],[180,100],[60,100],[6