INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_a#8','math',5,2,'u3','','tb_g5_2_math_u3_review_a','unit_review','M5-2-u3-C4',1,'sa','auto','문제로 마무리 — 화살 모양 선대칭도형에 대칭축을 그으면 모두 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"문제로 마무리 — 화살 모양 선대칭도형에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["화살 모양은 가로 가운데 직선으로 접으면 완전히 겹쳐요.","세로로 접으면 겹치지 않아요.","그래서 대칭축은 1개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":176.0,"h":176.0,"poly":[[[22.0,44.0],[66.0,66.0],[66.0,22.0],[110.0,22.0],[154.0,88.0],[110.0,154.0],[66.0,154.0],[66.0,110.0],[22.0,132.0]]],"grid":22.0}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 정사각형의 대칭축은 모두 몇 개인가요?","answer":["4"],"explanation":["정사각형은 세로·가로 가운데 선으로 접으면 겹쳐요.","두 대각선으로 접어도 겹쳐요.","그래서 대칭축은 4개예요."],"asset":null},{"stem":"단원 평가 — 선대칭도형(이등변삼각형)에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["이 삼각형은 두 변의 길이가 같아요.","뾰족한 꼭짓점과 마주 보는 변의 가운데를 잇는 직선으로 접으면 겹쳐요.","대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":100,"h":100,"poly":[[[20,20],[80,50.0],[20,80]]],"grid":20}],"tag":false}},{"stem":"단원 평가 — 정삼각형의 대칭축은 모두 몇 개인가요?","answer":["3"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","각 꼭짓점과 마주 보는 변의 가운데를 잇는 직선 3개로 접혀요.","그래서 대칭축은 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_a#9','math',5,2,'u3','','tb_g5_2_math_u3_review_a','unit_review','M5-2-u3-C5',2,'sa','auto','단원 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"단원 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["왼쪽 아래 변(? cm)을 대칭축으로 접으면 오른쪽 아래 변과 겹쳐요.","대응변의 길이는 같아요.","그래서 5 cm예요 — 8 cm는 위쪽 변이에요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.96],"? cm"],[[168.37,71.7],"?°"]],"arc":[[[116.0,58.0],[16.0,40.0],[56.0,88.0]],[[16.0,40.0],[56.0,88.0],[176.0,88.0]],[[216.0,40.0],[176.0,88.0],[56.0,88.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 선대칭도형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["130"],"explanation":["?°인 각을 대칭축으로 접으면 130°인 각과 겹쳐요.","대응각의 크기는 같아요.","그래서 130°예요 — 40°는 다른 각이에요."],"asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.96],"? cm"],[[168.37,71.7],"?°"]],"arc":[[[116.0,58.0],[16.0,40.0],[56.0,88.0]],[[16.0,40.0],[56.0,88.0],[176.0,88.0]],[[216.0,40.0],[176.0,88.0],[56.0,88.0]]]}],"tag":false}},{"stem":"단원 평가 — 선대칭도형에서 선분 ㄹㅂ의 길이는 몇 cm인가요?","answer":["24"],"explanation":["점 ㄹ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄹㅂ을 똑같이 둘로 나누어 선분 ㅈㅂ = 12 cm예요.","선분 ㄹㅂ = 12 × 2 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":232.0,"h":192.0,"pts":{"ㄱ":[116.0,36.0,"ne"],"ㄴ":[46.0,76.0,"w"],"ㄷ":[66.0,106.0,"w"],"ㄹ":[16.0,156.0,"sw"],"ㅁ":[