INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#4','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C3',1,'sa','auto','문제로 마무리 — 합동인 두 도형을 보고 왼쪽 도형의 위쪽 변(? cm)의 길이를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"문제로 마무리 — 합동인 두 도형을 보고 왼쪽 도형의 위쪽 변(? cm)의 길이를 쓰세요.","answer":["4"],"explanation":["오른쪽 도형은 왼쪽 도형을 위아래로 뒤집은 모양이에요.","왼쪽 도형의 위쪽 변의 대응변은 오른쪽 도형의 아래쪽 변이에요.","대응변의 길이는 같으므로 4 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":309.6,"h":139.2,"poly":[[[38.4,33.6],[134.4,33.6],[134.4,105.6],[58.68,85.32],[38.4,105.6]],[[194.4,105.6],[290.4,105.6],[290.4,33.6],[214.68,53.88],[194.4,33.6]]],"lab":[[[86.4,19.2],"? cm"],[[19.2,69.6],"? cm"],[[47.58,83.43],"45°"],[[115.41,80.85],"75°"],[[175.2,69.6],"3 cm"],[[242.4,120.0],"4 cm"],[[271.41,58.35],"?°"]],"arc":[[[38.4,33.6],[38.4,105.6],[58.68,85.32]],[[58.68,85.32],[134.4,105.6],[134.4,33.6]],[[214.68,53.88],[290.4,33.6],[290.4,105.6]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 — 합동인 두 도형을 보고 왼쪽 도형의 왼쪽 변(? cm)의 길이를 쓰세요.","answer":["3"],"explanation":["위아래로 뒤집어도 왼쪽 변은 왼쪽에 있어요.","왼쪽 도형의 왼쪽 변의 대응변은 오른쪽 도형의 왼쪽 변이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":309.6,"h":139.2,"poly":[[[38.4,33.6],[134.4,33.6],[134.4,105.6],[58.68,85.32],[38.4,105.6]],[[194.4,105.6],[290.4,105.6],[290.4,33.6],[214.68,53.88],[194.4,33.6]]],"lab":[[[86.4,19.2],"? cm"],[[19.2,69.6],"? cm"],[[47.58,83.43],"45°"],[[115.41,80.85],"75°"],[[175.2,69.6],"3 cm"],[[242.4,120.0],"4 cm"],[[271.41,58.35],"?°"]],"arc":[[[38.4,33.6],[38.4,105.6],[58.68,85.32]],[[58.68,85.32],[134.4,105.6],[134.4,33.6]],[[214.68,53.88],[290.4,33.6],[290.4,105.6]]]}],"tag":false}},{"stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄱㄷ의 길이는 몇 cm인가요?","answer":["6"],"explanation":["120°인 각끼리 대응각이라 점 ㄷ ↔ 점 ㅁ이에요.","변 ㄱㄷ의 대응변은 변 ㄹㅁ이에요.","대응변의 길이는 같으므로 6 cm예요."],"asset":{"type":"geo","items":[{"w":344.0,"h":120.75,"pts":{"ㄱ":[148.0,16.0,"ne"],"ㄴ":[16.0,78.35,"w"],"ㄷ":[112.0,78.35,"s"],"ㄹ":[196.0,42.35,"nw"],"ㅂ":[328.0,104.75,"e"],"ㅁ":[232.0,104.7,"s"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㄹ","ㅂ","ㅁ"]],"lab":[[[64.0,90.35],"8 cm"],[[101.0,59.3],"120°"],[[201.88,80.53],"6 cm"],[[267.13,62.7],"12 cm"],[[219.54,64.03],"35°"]],"arc":[[[148.0,16.0],[112.0,78.35],[16.0,78.35]],[[328.0,104.75],[196.0,42.35],[232.0,104.7]]]}],"tag":false}},{"stem":"문제로 마무리 — 합동인 두 도형을 보고 오른쪽 도형의 ?°에 알맞은 수를 쓰세요.","answer":["75"],"explanation":["오른쪽 도형은 왼쪽 도형을 위아래로 뒤집은 모양이에요.","?°인 각의 대응각은 왼쪽 도형의 75°인 각이에요.","대응각의 크기는 같으므로 75°예요."],"asset":{"type":"geo","items":[{"w":309.6,"h":139.2,"poly":[[[38.4,33.6],[134.4,33.6],[134.4,105.6],[58.68,85.32],[38.4,105.6]],[[194.4,105.6],[290.4,105.6],[290.4,33.6],[214.68,53.88],[194.4,33.6]]],"lab":[[[86.4,19.2],"? cm"],[[19.2,69.6],"? cm"],[[47.58,83.43],"45°"],[[115.41,80.85],"75°"],[[175.2,69.6],"3 cm"],[[242.4,120.0],"4 cm"],[[271.41,58.35],"?°"]],"arc":[[[38.4,33.6],[38.4,105.6],[58.68,85.32]],[[58.68,85.32],[134.4,105.6],[134.4,33.6]],[[214.68,53.88],[290.4,33.6],[290.4,105.6]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#5','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',1,'mc','auto','단원 평가 — 선대칭도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X09','M5-2-u3-X15']::text[],true,'{"seq":5,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"단원 평가 — 선대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다, 바","correct":true},{"t":"가, 다","mis":"M5-2-u3-X08"},{"t":"가, 나, 다, 라, 바","mis":"M5-2-u3-X09"},{"t":"나, 라","mis":"M5-2-u3-X15"}],"explanation":["가(마름모)·다(연 모양)·바는 접으면 완전히 겹치는 직선이 있어요.","나와 라는 180° 돌리면 겹치지만 접어서는 겹치지 않아요.","마도 접어서 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":96.0,"h":76.0,"poly":[[[8.0,38.0],[48.0,8.0],[88.0,38.0],[48.0,68.0]]],"cap":"가"},{"w":76.0,"h":68.0,"poly":[[[8.0,8.0],[48.0,8.0],[48.0,28.0],[68.0,28.0],[68.0,60.0],[28.0,60.0],[28.0,40.0],[8.0,40.0]]],"cap":"나"},{"w":72.0,"h":88.0,"poly":[[[8.0,38.0],[36.0,8.0],[64.0,38.0],[36.0,80.0]]],"cap":"다"},{"w":86.0,"h":66.0,"poly":[[[28.0,8.0],[78.0,8.0],[58.0,58.0],[8.0,58.0]]],"cap":"라"},{"w":96.0,"h":66.0,"poly":[[[28.0,8.0],[58.0,8.0],[88.0,58.0],[8.0,58.0]]],"cap":"마"},{"w":76.0,"h":76.0,"poly":[[[8.0,8.0],[68.0,8.0],[68.0,28.0],[28.0,28.0],[28.0,48.0],[68.0,48.0],[68.0,68.0],[8.0,68.0]]],"cap":"바"}],"tag":false},"variant_rule":{"alt":[{"stem":"형성 평가 — 선대칭도형을 찾아보세요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u3-X02"},{"t":"㉢","mis":"M5-2-u3-X09"},{"t":"㉡과 ㉢","mis":"M5-2-u3-X09"}],"explanation":["㉡(별 모양)은 접으면 완전히 겹치는 직선이 있어요.","㉠은 세 변의 길이가 모두 달라 겹치지 않아요.","㉢(평행사변형)은 접어서 겹치는 직선이 없어요."],"asset":{"type":"geo","items":[{"w":112.0,"h":116.0,"poly":[[[96.0,16.0],[96.0,100.0],[16.0,100.0]]],"cap":"㉠"},{"w":119.5,"h":115.21,"poly":[[[59.75,16.0],[70.92,46.63],[103.5,47.79],[77.82,67.87],[86.79,99.21],[59.75,81.0],[32.71,99.21],[41.68,67.87],[16.0,47.79],[48.58,46.63]]],"cap":"㉡"},{"w":152.0,"h":112.0,"poly":[[[46.0,16.0],[136.0,16.0],[106.0,96.0],[16.0,96.0]]],"cap":"㉢"}],"tag":false}},{"stem":"단원 평가 — 선대칭도형을 찾아보세요.","options":[{"t":"나","correct":true},{"t":"가","mis":"M5-2-u3-X02"},{"t":"다","mis":"M5-2-u3-X09"},{"t":"라","mis":"M5-2-u3-X02"}],"explanation":["나(정오각형)는 꼭짓점과 마주 보는 변의 가운데를 잇는 직선으로 접으면 겹쳐요.","가·라는 어떻게 접어도 겹치지 않아요.","다도 반으로 나눌 수는 있지만 접어서 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":60.0,"h":76.0,"poly":[[[8.0,8.0],[8.0,68.0],[52.0,68.0]]],"cap":"가"},{"w":92.08,"h":88.36,"poly":[[[46.04,8.0],[84.08,35.64],[69.55,80.36],[22.53,80.36],[8.0,35.64]]],"cap":"나"},{"w":76.0,"h":76.0,"poly":[[[16.0,8.0],[68.0,12.0],[60.0,68.0],[8.0,64.0]]],"cap":"다"},{"w":84.0,"h":68.0,"poly":[[[28.0,8.0],[64.0,8.0],[76.0,60.0],[8.0,60.0]]],"cap":"라"}],"tag":false}},{"stem":"문제로 마무리 — 선대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다, 라, 마","correct":true},{"t":"나, 라, 마","mis":"M5-2-u3-X19"},{"t":"다, 라, 마","mis":"M5-2-u3-X20"},{"t":"가, 나, 다, 라, 마, 바","mis":"M5-2-u3-X15"}],"explanation":["나·라·마는 접으면 겹치는 직선이 있어요.","다(원)도 지름을 따라 접으면 겹쳐요.","나와 다는 점대칭도형이기도 해요 — 둘 다인 도형도 있어요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"poly":[[[20,20],[100,20],[140,100],[60,100]]],"grid":20,"cap":"가"},{"w":120,"h":160,"poly":[[[60,20],[100,60],[100,100],[60,140],[20,100],[20,60]]],"grid":20,"cap":"나"},{"w":160,"h":160,"circle":[[[80,80],60]],"grid":20,"cap":"다"},{"w":160,"h":140,"poly":[[[20,20],[140,20],[80,120]]],"grid":20,"cap":"라"},{"w":120,"h":140,"poly":[[[20,20],[100,20],[100,60],[80,60],[80,120],[40,120],[40,60],[20,60]]],"grid":20,"cap":"마"},{"w":160,"h":160,"poly":[[[20,40],[80,40],[140,20],[140,120],[80,120],[20,140]]],"grid":20,"cap":"바"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kin