INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#6','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C7',1,'mc','auto','단원 평가 — 점대칭도형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u3-X20','M5-2-u3-X14','M5-2-u3-X15']::text[],true,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"단원 평가 — 점대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 바","mis":"M5-2-u3-X20"},{"t":"가, 나, 라, 바","mis":"M5-2-u3-X14"},{"t":"라, 마","mis":"M5-2-u3-X15"}],"explanation":["나·라·바는 180° 돌리면 완전히 겹쳐요.","라는 선대칭도형이면서 점대칭도형이에요.","가와 마는 접어서만 겹쳐요."],"asset":{"type":"geo","items":[{"w":92.08,"h":88.36,"poly":[[[46.04,8.0],[84.08,35.64],[69.55,80.36],[22.53,80.36],[8.0,35.64]]],"cap":"가"},{"w":86.0,"h":64.0,"poly":[[[28.0,8.0],[78.0,8.0],[58.0,56.0],[8.0,56.0]]],"cap":"나"},{"w":88.0,"h":68.0,"poly":[[[8.0,60.0],[80.0,52.0],[56.0,8.0]]],"cap":"다"},{"w":96.0,"h":76.0,"poly":[[[8.0,8.0],[48.0,28.0],[88.0,8.0],[88.0,68.0],[48.0,48.0],[8.0,68.0]]],"cap":"라"},{"w":96.0,"h":64.0,"poly":[[[28.0,8.0],[68.0,8.0],[88.0,56.0],[8.0,56.0]]],"cap":"마"},{"w":76.0,"h":80.0,"poly":[[[28.0,8.0],[68.0,8.0],[68.0,48.0],[48.0,48.0],[48.0,72.0],[8.0,72.0],[8.0,32.0],[28.0,32.0]]],"cap":"바"}],"tag":false},"variant_rule":{"alt":[{"stem":"주변에서 찾은 모양 가운데 점대칭도형 모양을 모두 고른 것은 어느 것인가요? (네잎클로버, 숫자 8, 자음자 ㄷ, 알파벳 F)","options":[{"t":"네잎클로버, 숫자 8","correct":true},{"t":"네잎클로버, 숫자 8, 자음자 ㄷ","mis":"M5-2-u3-X15"},{"t":"숫자 8","mis":"M5-2-u3-X19"},{"t":"자음자 ㄷ, 알파벳 F","mis":"M5-2-u3-X17"}],"explanation":["네잎클로버와 숫자 8은 180° 돌리면 겹쳐요.","자음자 ㄷ은 접으면 겹치지만 180° 돌리면 겹치지 않아요.","알파벳 F는 접어도 돌려도 겹치지 않아요."],"asset":null},{"stem":"단원 평가 — 정삼각형, 정사각형, 사다리꼴 가운데 점대칭도형을 찾아보세요.","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X14"},{"t":"사다리꼴","mis":"M5-2-u3-X15"},{"t":"셋 다","mis":"M5-2-u3-X14"}],"explanation":["정사각형은 가운데 점을 중심으로 180° 돌리면 겹쳐요.","정삼각형은 120°에서 겹쳐도 180°에서는 겹치지 않아요.","사다리꼴은 접으면 겹치지만 돌리면 겹치지 않아요."],"asset":null},{"stem":"문제로 마무리 — 점대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다, 바","correct":true},{"t":"가, 바","mis":"M5-2-u3-X20"},{"t":"가, 나, 바","mis":"M5-2-u3-X19"},{"t":"가, 나, 다, 라, 마, 바","mis":"M5-2-u3-X14"}],"explanation":["가·나·바는 가운데 점을 중심으로 180° 돌리면 완전히 겹쳐요.","다(원)도 180° 돌리면 겹쳐요.","나와 다는 선대칭도형이면서 점대칭도형이에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"poly":[[[20,20],[100,20],[140,100],[60,100]]],"grid":20,"cap":"가"},{"w":120,"h":160,"poly":[[[60,20],[100,60],[100,100],[60,140],[20,100],[20,60]]],"grid":20,"cap":"나"},{"w":160,"h":160,"circle":[[[80,80],60]],"grid":20,"cap":"다"},{"w":160,"h":140,"poly":[[[20,20],[140,20],[80,120]]],"grid":20,"cap":"라"},{"w":120,"h":140,"poly":[[[20,20],[100,20],[100,60],[80,60],[80,120],[40,120],[40,60],[20,60]]],"grid":20,"cap":"마"},{"w":160,"h":160,"poly":[[[20,40],[80,40],[140,20],[140,120],[80,120],[20,140]]],"grid":20,"cap":"바"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#7','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C7',1,'mc','auto','단원 평가 — 점대칭도형의 대칭의 중심은 어느 점인가요?',ARRAY['M5-2-u3-X14']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"단원 평가 — 점대칭도형의 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X14"},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["마주 보는 꼭짓점끼리 선분을 그어 보아요.","네 선분이 모두 점 ㄷ에서 만나요.","그래서 대칭의 중심은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":162.0,"h":126.0,"pts":{"ㄱ":[63.0,63.0,"w"],"ㄴ":[81.0,45.0,"n"],"ㄷ":[81.0,63.0,"e"],"ㄹ":[99.0,77.4,"e"]},"poly":[[[9.0,9.0],[63.0,27.0],[81.0,9.0],[153.0,16.2],[153.0,117.0],[99.0,99.0],[81.0,117.0],[9.0,109.8]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 점대칭도형에서 대칭의 중심을 찾아 기호를 고르세요.","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u3-X14"},{"t":"㉡","mis":"M5-2-u3-X14"},{"t":"㉣","mis":"M5-2-u3-X14"}],"explanation":["대응점끼리 잇는 선분을 그어 보아요.","선분들이 모두 ㉢에서 만나요.","꼭짓점이나 가운데쯤 보이는 점을 고르지 않아요."],"asset":{"type":"geo","items":[{"w":200,"h":120,"pts":{"㉠":[20,20,"nw"],"㉡":[60,60,"w"],"㉢":[100,60,"n"],"㉣":[140,78.0,"e"]},"poly":[[[20,20],[140,20],[140,60],[180,100],[60,100],[60,60]]],"grid":20}],"tag":false}},{"stem":"형성 평가 — 점대칭도형에서 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄷ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["마주 보는 꼭짓점끼리 선분을 그어 보아요.","세 선분이 모두 점 ㄱ에서 만나요.","그래서 대칭의 중심은 점 ㄱ이에요."],"asset":{"type":"geo","items":[{"w":312.0,"h":208.0,"pts":{"ㄴ":[130.0,104.0,"w"],"ㄷ":[156.0,72.8,"n"],"ㄱ":[156.0,104.0,"e"],"ㄹ":[197.6,127.4,"e"]},"poly":[[[78.0,52.0],[156.0,26.0],[286.0,52.0],[234.0,156.0],[156.0,182.0],[26.0,156.0]]],"grid":26.0}],"tag":false}},{"stem":"문제로 마무리 — 점대칭도형의 대칭의 중심은 어느 점인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X14"},{"t":"점 ㄷ","mis":"M5-2-u3-X14"},{"t":"점 ㄹ","mis":"M5-2-u3-X14"}],"explanation":["대응점끼리 잇는 선분을 그어 보아요.","선분들이 모두 점 ㄱ에서 만나요.","그래서 대칭의 중심은 점 ㄱ이에요."],"asset":{"type":"geo","items":[{"w":156.0,"h":156.0,"pts":{"ㄴ":[78.0,46.8,"e"],"ㄱ":[78.0,78.0,"e"],"ㄷ":[57.2,101.4,"w"],"ㄹ":[98.8,109.2,"e"]},"poly":[[[26.0,26.0],[52.0,26.0],[104.0,78.0],[104.0,26.0],[130.0,26.0],[130.0,130.0],[104.0,130.0],[52.0,78.0],[52.0,130.0],[26.0,130.0]]],"grid":26.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#8','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',1,'sa','auto','단원 평가 — 정사각형의 대칭축은 모두 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"단원 평가 — 정사각형의 대칭축은 모두 몇 개인가요?","answer":["4"],"explanation":["정사각형은 세로·가로 가운데 선으로 접으면 겹쳐요.","두 대각선으로 접어도 겹쳐요.","그래서 대칭축은 4개예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"단원 평가 — 선대칭도형(이등변삼각형)에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["이 삼각형은 두 변의 길이가 같아요.","뾰족한 꼭짓점과 마주 보는 변의 가운데를 잇는 직선으로 접으면 겹쳐요.","대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":100,"h":100,"poly":[[[20,20],[80,50.0],[20,80]]],"grid":20}],"tag":false}},{"stem":"단원 평가 — 정삼각형의 대칭축은 모두 몇 개인가요?","answer":["3"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","각 꼭짓점과 마주 보는 변의 가운데를 잇는 직선 3개로 접혀요.","그래서 대칭축은 3개예요."]},{"stem":"문제로 마무리 — 화살 모양 선대칭도형에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["화살 모양은 가로 가운데 직선으로 접으면 완전히 겹쳐요.","세로로 접으면 겹치지 않아요.","그래서 대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":176.0,"h":176.0,"poly":[[[22.0,44.0],[66.0,66.0],[66.0,22.0],[110.0,22.0],[154.0,88.0],[110.0,154.0],[66.0,154.0],[66.0,110.0],[22.0,132.0]]],"grid":22.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#9','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C5',2,'sa','auto','단원 평가 — 선대칭도형을 보고 ?°에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"단원 평가 — 선대칭도형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["130"],"explanation":["?°인 각을 대칭축으로 접으면 130°인 각과 겹쳐요.","대응각의 크기는 같아요.","그래서 130°예요 — 40°는 다른 각이에요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.96],"? cm"],[[168.37,71.7],"?°"]],"arc":[[[116.0,58.0],[16.0,40.0],[56.0,88.0]],[[16.0,40.0],[56.0,88.0],[176.0,88.0]],[[216.0,40.0],[176.0,88.0],[56.0,88.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 선대칭도형에서 선분 ㄹㅂ의 길이는 몇 cm인가요?","answer":["24"],"explanation":["점 ㄹ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄹㅂ을 똑같이 둘로 나누어 선분 ㅈㅂ = 12 cm예요.","선분 ㄹㅂ = 12 × 2 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":232.0,"h":192.0,"pts":{"ㄱ":[116.0,36.0,"ne"],"ㄴ":[46.0,76.0,"w"],"ㄷ":[66.0,106.0,"w"],"ㄹ":[16.0,156.0,"sw"],"ㅁ":[116.0,136.0,"n"],"ㅂ":[216.0,156.0,"se"],"ㅅ":[166.0,106.0,"e"],"ㅇ":[186.0,76.0,"e"],"ㅈ":[116.0,156.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[[[116.0,16.0],[116.0,176.0]]],"dash":[["ㄹ","ㅂ"]],"lab":[[[166.0,168.0],"12 cm"]]}],"tag":false}},{"stem":"단원 평가 — 선대칭도형에서 변 ㄷㄹ의 길이는 몇 cm인가요?","answer":["10"],"explanation":["대칭축은 점 ㄱ과 점 ㄹ을 지나요.","변 ㄷㄹ의 대응변은 변 ㅁㄹ이에요.","그래서 10 cm예요."],"asset":{"type":"geo","items":[{"w":206.0,"h":178.0,"pts":{"ㄱ":[110.0,36.0,"ne"],"ㄴ":[30.0,96.0,"w"],"ㄷ":[30.0,146.0,"sw"],"ㄹ":[110.0,126.0,"sw"],"ㅁ":[190.0,146.0,"se"],"ㅂ":[190.0,96.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[110.0,16.0],[110.0,162.0]]],"lab":[[[158.4,54.8],"12 cm"],[[16.0,121.0],"6 cm"],[[147.09,147.64],"10 cm"]]}],"tag":false}},{"stem":"단원 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["왼쪽 아래 변(? cm)을 대칭축으로 접으면 오른쪽 아래 변과 겹쳐요.","대응변의 길이는 같아요.","그래서 5 cm예요 — 8 cm는 위쪽 변이에요."],"asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.96],"? cm"],[[168.37,71.7],"?°"]],"arc":[[[116.0,58.0],[16.0,40.0],[56.0,88.0]],[[16.0,40.0],[56.0,88.0],[176.0,88.0]],[[216.0,40.0],[176.0,88.0],[56.0,88.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
