INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#12','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C3',2,'sa','auto','단원 평가 — 합동인 두 사각형을 보고 ?°에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"단원 평가 — 합동인 두 사각형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["60"],"explanation":["오른쪽 사각형은 왼쪽을 뒤집은 모양이에요.","?°인 각의 대응각은 왼쪽 사각형의 60°인 각이에요.","대응각의 크기는 같으므로 60°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":227.22,"h":111.16,"poly":[[[91.44,19.2],[91.44,79.96],[38.64,79.96],[22.85,58.8]],[[139.44,19.2],[139.44,79.96],[192.24,79.96],[208.02,58.8]]],"lab":[[[79.44,39.98],"60°"],[[19.2,77.99],"2 cm"],[[65.04,91.96],"? cm"],[[151.44,39.98],"?°"],[[179.73,28.61],"6 cm"],[[165.84,91.96],"4 cm"]],"arc":[[[91.44,79.96],[91.44,19.2],[22.85,58.8]],[[139.44,79.96],[139.44,19.2],[208.02,58.8]]],"right":[[[91.44,19.2],[91.44,79.96],[38.64,79.96]],[[139.44,19.2],[139.44,79.96],[192.24,79.96]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"합동인 두 삼각형을 보고 답하세요. 변 ㄱㄴ의 길이는 몇 cm인가요?","answer":["3"],"explanation":["점 ㄱ ↔ 점 ㅁ, 점 ㄴ ↔ 점 ㅂ이에요.","변 ㄱㄴ의 대응변은 변 ㅁㅂ이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":238.71,"h":196.68,"pts":{"ㄱ":[81.42,16.0,"n"],"ㄴ":[16.0,58.48,"w"],"ㄷ":[185.64,94.54,"e"],"ㅁ":[157.29,180.68,"s"],"ㅂ":[222.71,138.2,"e"],"ㄹ":[53.06,102.14,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[45.5,53.01],"45°"],[[149.24,77.95],"25°"],[[198.71,172.86],"3 cm"],[[95.55,154.19],"5 cm"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄴ","ㄷ","ㄱ"]]}],"tag":false}},{"stem":"익힘 — 두 직사각형은 합동이에요. 사각형 ㅁㅂㅅㅇ의 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["변 ㅁㅂ의 대응변은 변 ㄴㄷ이라 5 cm예요.","직사각형의 넓이는 (가로) × (세로)예요.","3 × 5 = 15(cm²)예요."],"asset":{"type":"geo","items":[{"w":252.0,"h":146.0,"pts":{"ㄱ":[16.0,30.0,"nw"],"ㄴ":[16.0,90.0,"sw"],"ㄷ":[116.0,90.0,"se"],"ㄹ":[116.