INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_b#13','math',5,2,'u3','','tb_g5_2_math_u3_review_b','unit_review','M5-2-u3-C6',2,'mc','auto','형성 평가 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 왼쪽 아래 꼭짓점의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X10']::text[],true,'{"seq":13,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"형성 평가 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 왼쪽 아래 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㅁ","mis":"M5-2-u3-X12"},{"t":"점 ㅂ","mis":"M5-2-u3-X10"}],"explanation":["대칭축과 수직인 방향으로 대응점을 찾아요.","대칭축까지의 거리와 같은 거리만큼 반대쪽으로 가요.","그래서 점 ㄷ이에요 — 칸 수가 틀리거나 높이가 어긋난 점이 아니에요."],"asset":{"type":"geo","items":[{"w":220,"h":180,"pts":{"ㄱ":[80,36.0,"n"],"ㄴ":[80,144.0,"s"],"ㄷ":[140,120,"n"],"ㄹ":[160,120,"e"],"ㅁ":[140,140,"s"],"ㅂ":[200,120,"n"]},"seg":[[[80,36.0],[80,144.0]],[[80,60],[40,60]],[[40,60],[20,120]],[[20,120],[80,120]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 직선 ㄱㄴ(가로)을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 가장 위에 있는 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X10"},{"t":"점 ㅂ","mis":"M5-2-u3-X12"}],"explanation":["대칭축과 수직인 방향으로 대응점을 찾아요.","대칭축까지의 거리와 같은 거리만큼 반대쪽으로 가요.","그래서 점 ㅁ이에요 — 칸 수가 틀리거나 높이가 어긋난 점이 아니에요."],"asset":{"type":"geo","items":[{"w":240,"h":160,"pts":{"ㄱ":[20,60,"w"],"ㄴ":[210.0,60,"e"],"ㄷ":[80,120,"s"],"ㄹ":[80,140,"w"],"ㅁ":[80,100,"w"],"ㅂ":[100,100,"e"]},"seg":[[[20,60],[210.0,60]],[[40,60],[80,20]],[[80,20],[120,40]],[[120,40],[180,40]],[[180,40],[180,60]]],"grid":20}],"tag":false}},{"stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄴ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅇ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X10"},{"t":"점 ㅅ","mis":"M5-2-u3-X12"},{"t":"점 ㅈ","mis":"M5-2-u3-X12"}],"explanation":["대칭축과 수직인 방향으로 대응점을 찾아요.","대칭축