INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#15','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C4',2,'ox','auto','선대칭도형이면서 점대칭도형인 도형도 있어요.',ARRAY['M5-2-u3-X20']::text[],true,'{"seq":15,"concept":"M5-2-u3-C4","difficulty":2,"kind":"ox","stem":"선대칭도형이면서 점대칭도형인 도형도 있어요.","answer":"O","reason_options":[{"t":"정사각형·원처럼 접어도 겹치고 180° 돌려도 겹치는 도형이 있으므로","correct":true},{"t":"선대칭도형은 점대칭도형이 될 수 없으므로","mis":"M5-2-u3-X20"}],"mis":"M5-2-u3-X20","explanation":["정사각형은 대칭축이 4개이고 180° 돌려도 겹쳐요.","원도 접어도, 돌려도 겹쳐요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"원은 대칭축이 셀 수 없이 많고, 대칭의 중심은 1개예요.","answer":"O","reason_options":[{"t":"지름은 셀 수 없이 많고, 180° 돌리는 중심은 원의 중심 하나뿐이므로","correct":true},{"t":"원은 곧은 변이 없어 대칭축도 대칭의 중심도 없으므로","mis":"M5-2-u3-X19"}],"explanation":["원은 지름을 따라 접으면 언제나 겹쳐요.","원의 중심을 중심으로 180° 돌려도 겹쳐요.","대칭의 중심은 원의 중심 하나예요 — 맞는 말이에요."]},{"stem":"선대칭도형의 대칭축은 항상 1개예요.","answer":"X","reason_options":[{"t":"대칭축이 1개인 도형도, 2개 이상이거나 셀 수 없이 많은 도형도 있으므로","correct":true},{"t":"대칭축은 도형을 반으로 나누는 선 하나뿐이므로","mis":"M5-2-u3-X08"}],"explanation":["이등변삼각형은 1개, 직사각형은 2개, 정사각형은 4개예요.","원은 대칭축이 셀 수 없이 많아요.","그래서 틀린 말이에요."]},{"stem":"점대칭도형에서 대칭의 중심은 오직 한 개예요.","answer":"O","reason_options":[{"t":"180° 돌려 완전히 겹치게 하는 중심은 대응점끼리 이은 선분들이 만나는 한 점뿐이므로","correct":true},{"t":"대칭축처럼 여러 개일 수 있으므로","mis":"M5-2-u3-X15"}],"explanation":["대응점끼리 이은 선분은 모두 대칭의 중심에서 만나요.","그 점은 하나뿐이에요.","대칭축이 여러 개일 수 있는 선대칭도형과 달라요 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#16','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C10',2,'mc','auto','땅을 나눈 4개의 도형이 서로 합동인지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X16','M5-2-u3-X05']::text[],true,'{"seq":16,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"땅을 나눈 4개의 도형이 서로 합동인지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"4개의 도형을 포개어 완전히 겹치는지 본다","correct":true},{"t":"도형의 색이 같은지 본다","mis":"M5-2-u3-X02"},{"t":"사과나무의 크기를 비교한다","mis":"M5-2-u3-X16"},{"t":"정사각형의 개수만 센다","mis":"M5-2-u3-X05"}],"explanation":["합동은 포개었을 때 완전히 겹치는 것이에요.","뒤집거나 돌려서 포개도 돼요.","정사각형의 개수만 같아서는 모양이 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"땅을 그림처럼 나누었어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"4개의 도형이 서로 합동이고 사과나무가 한 그루씩 들어 있어 조건에 맞다","correct":true},{"t":"ㄱ자 모양은 돌려 놓으면 합동이 아니라서 조건에 맞지 않다","mis":"M5-2-u3-X04"},{"t":"사과나무가 두 그루인 도형이 있어 조건에 맞지 않다","mis":"M5-2-u3-X16"},{"t":"도형의 넓이가 서로 달라 조건에 맞지 않다","mis":"M5-2-u3-X05"}],"explanation":["4개의 도형은 모두 정사각형 3개가 붙은 ㄱ자 모양이에요.","돌리거나 뒤집으면 완전히 겹쳐 서로 합동이에요.","도형마다 사과나무가 한 그루씩 있어 두 조건에 모두 맞아요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[78.2,112.2],[78.2,146.2],[10.2,146.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[112.2,78.2],[112.2,112.2],[44.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,78.2],[146.2,78.2],[146.2,146.2],[78.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}},{"stem":"정사각형 12개가 붙어 있는 땅을 사과나무가 한 그루씩 들어가도록 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙어 있는 모양인가요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M5-2-u3-X16"},{"t":"8개","mis":"M5-2-u3-X16"},{"t":"12개","mis":"M5-2-u3-X16"}],"explanation":["합동인 도형은 정사각형의 개수가 같아요.","12개를 4개의 도형에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}},{"stem":"정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙어 있는 모양인가요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M5-2-u3-X16"},{"t":"8개","mis":"M5-2-u3-X16"},{"t":"6개","mis":"M5-2-u3-X16"}],"explanation":["합동인 도형은 정삼각형의 개수가 같아요.","12개를 4개의 도형에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"asset":{"type":"geo","items":[{"w":240.8,"h":113.79,"poly":[[[36.4,56.9],[92.4,56.9],[64.4,8.4]],[[92.4,56.9],[148.4,56.9],[120.4,8.4]],[[148.4,56.9],[204.4,56.9],[176.4,8.4]],[[64.4,8.4],[120.4,8.4],[92.4,56.9]],[[120.4,8.4],[176.4,8.4],[148.4,56.9]],[[8.4,105.39],[64.4,105.39],[36.4,56.9]],[[64.4,105.39],[120.4,105.39],[92.4,56.9]],[[120.4,105.39],[176.4,105.39],[148.4,56.9]],[[176.4,105.39],[232.4,105.39],[204.4,56.9]],[[36.4,56.9],[92.4,56.9],[64.4,105.39]],[[92.4,56.9],[148.4,56.9],[120.4,105.39]],[[148.4,56.9],[204.4,56.9],[176.4,105.39]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#17','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C5',3,'error','auto','단원 평가 — 선대칭도형을 보고 잘못 설명한 것을 찾아보세요.',ARRAY['M5-2-u3-X07','M5-2-u3-X06','M5-2-u3-X11']::text[],true,'{"seq":17,"concept":"M5-2-u3-C5","difficulty":3,"kind":"error","stem":"단원 평가 — 선대칭도형을 보고 잘못 설명한 것을 찾아보세요.","options":[{"t":"변 ㄱㄴ과 변 ㅁㅂ은 길이가 같습니다.","correct":true,"mis_target":"M5-2-u3-X07"},{"t":"점 ㄱ의 대응점은 점 ㅅ입니다.","mis":"M5-2-u3-X06"},{"t":"선분 ㄱㅇ과 선분 ㅅㅇ은 길이가 같습니다.","mis":"M5-2-u3-X11"}],"explanation":["대칭축은 점 ㅇ과 점 ㄹ을 지나요 — 점 ㄱ ↔ 점 ㅅ, 점 ㄴ ↔ 점 ㅂ이에요.","변 ㄱㄴ의 대응변은 변 ㅅㅂ이에요.","대칭축은 선분 ㄱㅅ을 똑같이 둘로 나눠 선분 ㄱㅇ = 선분 ㅅㅇ이 맞아요."],"asset":{"type":"geo","items":[{"w":192.0,"h":152.0,"pts":{"ㄱ":[16.0,36.0,"nw"],"ㄴ":[36.0,72.0,"w"],"ㄷ":[16.0,116.0,"sw"],"ㄹ":[96.0,96.0,"se"],"ㅁ":[176.0,116.0,"se"],"ㅂ":[156.0,72.0,"e"],"ㅅ":[176.0,36.0,"ne"],"ㅇ":[96.0,36.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[[[96.0,16.0],[96.0,136.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 양쪽 화살표 모양 도형에 대해 잘못 설명한 것을 찾아보세요.","options":[{"t":"㉢ 대칭축은 무수히 많습니다.","correct":true,"mis_target":"M5-2-u3-X08"},{"t":"㉡ 점대칭도형입니다.","mis":"M5-2-u3-X20"},{"t":"㉣ 대칭의 중심은 1개입니다.","mis":"M5-2-u3-X15"}],"explanation":["이 도형은 가로 가운데 선과 세로 가운데 선 2개로만 접혀요.","가운데 점을 중심으로 180° 돌려도 겹쳐 점대칭도형이고, 대칭의 중심은 1개예요.","대칭축이 무수히 많은 것은 원이에요 — ㉢이 틀렸어요."],"asset":{"type":"geo","items":[{"w":136.0,"h":96.0,"poly":[[[8.0,48.0],[48.0,8.0],[48.0,28.0],[88.0,28.0],[88.0,8.0],[128.0,48.0],[88.0,88.0],[88.0,68.0],[48.0,68.0],[48.0,88.0]]]}],"tag":false}},{"stem":"문제로 마무리 — 선대칭도형과 점대칭도형에 대해 잘못 설명한 친구를 찾아보세요.","options":[{"t":"서준 — 「선대칭도형의 대칭축은 항상 1개예요.」","correct":true,"mis_target":"M5-2-u3-X08"},{"t":"지안 — 「선대칭도형의 대칭축은 대응점끼리 이은 선분과 수직으로 만나요.」","mis":"M5-2-u3-X11"},{"t":"도윤 — 「한 점을 중심으로 180° 돌렸을 때 돌리기 전과 완전히 겹치는 도형을 점대칭도형이라고 해요.」","mis":"M5-2-u3-X15"}],"explanation":["선대칭도형의 대칭축은 1개일 수도 있고 여러 개일 수도 있어요.","지안이와 도윤이의 말은 성질과 뜻 그대로예요.","서준이의 말이 틀렸어요."],"asset":null},{"stem":"단원 평가 — 점대칭도형에 대해 잘못 설명한 것을 찾아보세요.","options":[{"t":"㉡ 대칭의 중심은 여러 개 있을 수 있습니다.","correct":true,"mis_target":"M5-2-u3-X15"},{"t":"㉠ 각각의 대응점에서 대칭의 중심까지의 거리는 서로 같습니다.","mis":"M5-2-u3-X10"},{"t":"㉢ 대응점끼리 이은 선분은 대칭의 중심을 지납니다.","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형의 대칭의 중심은 1개예요.","㉠과 ㉢은 점대칭도형의 성질이에요.","그래서 ㉡이 잘못되었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#18','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C8',3,'sa','auto','단원 평가 — 점대칭도형에서 변 ㄱㄴ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"단원 평가 — 점대칭도형에서 변 ㄱㄴ의 길이는 몇 cm인가요?","answer":["2"],"explanation":["180° 돌리면 점 ㄱ ↔ 점 ㄹ, 점 ㄴ ↔ 점 ㅁ이에요.","변 ㄱㄴ의 대응변은 변 ㄹㅁ이에요.","그래서 2 cm예요 — 4 cm와 8 cm는 다른 변이에요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":201.6,"h":132.0,"pts":{"ㄱ":[57.6,19.2,"nw"],"ㄴ":[76.8,48.0,"nw"],"ㄷ":[19.2,100.8,"sw"],"ㄹ":[144.0,100.8,"se"],"ㅁ":[124.8,72.0,"se"],"ㅂ":[182.4,19.2,"ne"]," ":[100.8,60.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"lab":[[[36.65,62.02],"4 cm"],[[146.38,78.41],"2 cm"],[[81.6,112.8],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"익힘 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 반쪽의 변의 길이가 2 cm, 4 cm, 3 cm일 때 완성한 선대칭도형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["대응변의 길이가 같아 반대쪽에도 2 cm, 4 cm, 3 cm인 변이 생겨요.","반쪽의 길이를 두 번 더해요.","(2 + 4 + 3) × 2 = 18(cm)예요."],"asset":null},{"stem":"문제로 마무리 — 점대칭도형의 둘레가 24 cm일 때 변 ㄱㄴ의 길이는 몇 cm인가요?","answer":["5"],"explanation":["대응변이라 변 ㄱㅇ = 변 ㅁㄹ = 3 cm, 변 ㄷㄹ = 변 ㅅㅇ = 1 cm, 변 ㄱㄴ = 변 ㅁㅂ이에요.","(변 ㄱㄴ + 3 + 1 + 3) × 2 = 24이므로 변 ㄱㄴ + 7 = 12예요.","변 ㄱㄴ = 12 − 7 = 5(cm)예요."],"asset":{"type":"geo","items":[{"w":167.2,"h":198.0,"pts":{"ㄱ":[17.6,55.0,"nw"],"ㄴ":[17.6,165.0,"sw"],"ㄷ":[83.6,165.0,"s"],"ㄹ":[83.6,143.0,"s"],"ㅁ":[149.6,143.0,"se"],"ㅂ":[149.6,33.0,"ne"],"ㅅ":[83.6,33.0,"n"],"ㅇ":[83.6,55.0,"n"]," ":[83.6,99.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"lab":[[[50.6,180.4],"3 cm"],[[116.6,17.6],"3 cm"],[[116.6,158.4],"3 cm"],[[68.2,44.0],"1 cm"]]}],"tag":false}},{"stem":"단원 평가 — 점대칭도형이에요. 이 도형의 둘레는 몇 cm인가요?","answer":["38"],"explanation":["점대칭도형은 대응변의 길이가 같아요.","7 cm, 7 cm, 5 cm인 변마다 대응변이 하나씩 더 있어요.","둘레는 (7 + 7 + 5) × 2 = 38(cm)예요."],"asset":{"type":"geo","items":[{"w":156.0,"h":129.2,"pts":{" ":[78.0,64.6,"n"]},"poly":[[[16.0,52.6],[51.0,113.2],[71.0,67.6],[140.0,76.6],[105.0,16.0],[85.0,61.6]]],"lab":[[[51.79,47.18],"7 cm"],[[21.38,89.9],"7 cm"],[[48.18,84.78],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#19','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C3',3,'sa','auto','단원 평가 — 두 삼각형은 합동이에요. 삼각형 ㄹㅁㅂ의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"단원 평가 — 두 삼각형은 합동이에요. 삼각형 ㄹㅁㅂ의 둘레는 몇 cm인가요?","answer":["17"],"explanation":["합동인 두 삼각형은 대응변의 길이가 각각 같아요.","삼각형 ㄹㅁㅂ의 세 변은 4 cm, 6 cm, 7 cm예요.","4 + 6 + 7 = 17(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":172.0,"h":200.44,"pts":{"ㄱ":[16.0,16.0,"nw"],"ㄴ":[57.42,84.44,"s"],"ㄷ":[156.0,16.0,"ne"],"ㅂ":[156.0,116.0,"ne"],"ㅁ":[114.58,184.44,"s"],"ㄹ":[16.0,116.0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅂ","ㅁ","ㄹ"]],"lab":[[[24.73,57.47],"4 cm"],[[114.69,61.72],"6 cm"],[[86.0,104.0],"7 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 합동인 두 삼각형을 보고 답하세요. 변 ㄹㅂ의 길이는 몇 cm인가요?","answer":["14"],"explanation":["삼각형 ㄹㅁㅂ은 삼각형 ㄱㄴㄷ을 반 바퀴 돌린 모양이에요.","변 ㄹㅂ의 대응변은 변 ㄷㄴ이에요.","그래서 14 cm예요."],"asset":{"type":"geo","items":[{"w":353.57,"h":141.22,"pts":{"ㄱ":[73.36,16.0,"n"],"ㄴ":[16.0,97.92,"w"],"ㄷ":[156.0,97.92,"e"],"ㅁ":[280.21,125.22,"s"],"ㅂ":[337.57,43.31,"e"],"ㄹ":[197.57,43.31,"w"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]],"lab":[[[33.21,48.93],"10 cm"],[[86.0,109.92],"14 cm"],[[39.06,85.91],"55°"],[[126.41,85.73],"40°"]],"arc":[[[156.0,97.92],[16.0,97.92],[73.36,16.0]],[[16.0,97.92],[156.0,97.92],[73.36,16.0]]]}],"tag":false}},{"stem":"단원 평가 — 삼각형 ㄱㄴㄷ과 삼각형 ㄷㄹㅁ은 합동이에요. 각 ㄱㄷㅁ의 크기는 몇 도인가요?","answer":["70"],"explanation":["대응각이라 각 ㄷㄱㄴ = 각 ㅁㄷㄹ = 80°예요.","각 ㄱㄷㄴ = 180° − 70° − 80° = 30°예요.","각 ㄱㄷㅁ = 180° − 30° − 80° = 70°예요."],"asset":{"type":"geo","items":[{"w":262.0,"h":144.76,"pts":{"ㄱ":[56.84,71.52,"n"],"ㄴ":[36.0,128.76,"s"],"ㄷ":[156.0,128.76,"s"],"ㄹ":[216.92,128.76,"s"],"ㅁ":[175.88,16.0,"n"]},"seg":[[[16.0,128.76],[246.0,128.76]],[[56.84,71.52],[36.0,128.76]],[[56.84,71.52],[156.0,128.76]],[[175.88,16.0],[156.0,128.76]],[[175.88,16.0],[216.92,128.76]]],"lab":[[[57.3,113.85],"70°"],[[175.92,112.05],"80°"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄹ","ㄷ","ㅁ"]]}],"tag":false}},{"stem":"단원 평가 — 직사각형 모양의 종이를 선분 ㅅㅇ을 따라 그림처럼 접었어요. 각 ㅂㅅㅇ이 55°일 때 각 ㅂㅅㄴ의 크기는 몇 도인가요?","answer":["70"],"explanation":["접힌 부분과 처음 부분은 포개어 완전히 겹치므로 합동이에요.","그래서 각 ㅇㅅㄷ도 각 ㅂㅅㅇ과 같은 55°예요.","한 직선은 180°이므로 각 ㅂㅅㄴ = 180° − 55° − 55° = 70°예요."],"asset":{"type":"geo","items":[{"w":208.8,"h":148.76,"pts":{"ㄱ":[14.4,80.36,"nw"],"ㄴ":[14.4,134.36,"sw"],"ㄷ":[194.4,134.36,"se"],"ㄹ":[194.4,80.36,"ne"],"ㅁ":[49.46,32.87,"nw"],"ㅂ":[66.75,80.36,"sw"],"ㅅ":[86.4,134.36,"s"],"ㅇ":[124.21,80.36,"se"],"ㅈ":[100.21,14.4,"n"]},"poly":[[[14.4,80.36],[14.4,134.36],[86.4,134.36],[124.21,80.36]],[[86.4,134.36],[124.21,80.36],[100.21,14.4],[49.46,32.87]]],"dash":[[[86.4,134.36],[194.4,134.36]],[[194.4,134.36],[194.4,80.36]],[[194.4,80.36],[124.21,80.36]]],"lab":[[[89.45,111.16],"55°"]],"arc":[[[66.75,80.36],[86.4,134.36],[124.21,80.36]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#20','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C8',3,'sa','auto','익힘 — 점대칭도형에서 각 ㄴㅁㅂ의 크기는 몇 도인가요?','{}'::text[],true,'{"seq":20,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"익힘 — 점대칭도형에서 각 ㄴㅁㅂ의 크기는 몇 도인가요?","answer":["35"],"explanation":["대응각이라 각 ㅂㄱㄴ = 각 ㄷㄹㅁ = 90°예요.","사각형 ㄱㄴㅁㅂ의 네 각의 크기의 합은 360°예요.","360° − 160° − 90° − 75° = 35°예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":172.0,"h":147.92,"pts":{"ㄱ":[31.52,16.0,"nw"],"ㄴ":[16.0,73.96,"w"],"ㄷ":[72.82,113.78,"s"],"ㄹ":[140.48,131.92,"se"],"ㅁ":[156.0,73.96,"e"],"ㅂ":[99.18,34.14,"n"]," ":[86.0,73.96,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄴ","ㅁ"]],"lab":[[[90.72,52.26],"160°"],[[128.48,111.14],"90°"],[[41.39,54.48],"75°"]],"arc":[["ㄱ","ㅂ","ㅁ"],["ㄷ","ㄹ","ㅁ"],["ㄱ","ㄴ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 점대칭도형(평행사변형 ㄱㄴㄷㄹ)에서 각 ㄴㄷㄹ의 크기는 몇 도인가요?","answer":["65"],"explanation":["대응각이라 각 ㄷㄹㄱ = 각 ㄱㄴㄷ = 115°예요.","네 각의 크기의 합은 360°예요.","(360° − 115° − 115°) ÷ 2 = 65°예요."],"asset":{"type":"geo","items":[{"w":179.0,"h":90.0,"pts":{"ㄱ":[16.0,16.0,"w"],"ㄴ":[43.0,74.0,"sw"],"ㄷ":[163.0,74.0,"e"],"ㄹ":[136.0,16.0,"ne"]," ":[89.5,45.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[55.9,53.76],"115°"]],"arc":[["ㄱ","ㄴ","ㄷ"]]}],"tag":false}},{"stem":"단원 평가 — 선대칭도형에서 각 ㄴㄷㅂ의 크기는 몇 도인가요?","answer":["90"],"explanation":["직선 ㅂㄷ이 대칭축이고 점 ㄴ과 점 ㄹ은 대응점이에요.","대칭축은 대응점끼리 이은 선분과 수직으로 만나요.","그래서 90°예요."],"asset":{"type":"geo","items":[{"w":192.0,"h":164.0,"pts":{"ㄱ":[48.0,36.0,"nw"],"ㄴ":[16.0,126.0,"sw"],"ㄷ":[96.0,126.0,"se"],"ㄹ":[176.0,126.0,"se"],"ㅁ":[144.0,36.0,"ne"],"ㅂ":[96.0,52.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[96.0,16.0],[96.0,148.0]]],"lab":[[[37.24,111.01],"70°"],[[132.6,59.37],"95°"]],"arc":[["ㄷ","ㄴ","ㄱ"],["ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"단원 평가 — 점대칭도형에서 각 ㄴㄱㅂ의 크기는 몇 도인가요?","answer":["125"],"explanation":["대응각이라 각 ㄱㄴㄷ = 각 ㄹㅁㅂ = 120°예요.","사각형 ㄱㄴㄷㅂ의 네 각의 크기의 합은 360°예요.","360° − 120° − 75° − 40° = 125°예요."],"asset":{"type":"geo","items":[{"w":160.0,"h":138.4,"pts":{"ㄱ":[80.64,16.0,"n"],"ㄴ":[26.35,30.56,"nw"],"ㄷ":[16.0,69.2,"w"],"ㄹ":[79.36,122.4,"s"],"ㅁ":[133.65,107.84,"se"],"ㅂ":[144.0,69.2,"e"]," ":[80.0,69.2,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄷ","ㅂ"]],"lab":[[[113.93,58.25],"40°"],[[116.68,90.87],"120°"],[[39.8,50.94],"75°"]],"arc":[["ㄱ","ㅂ","ㄷ"],["ㄹ","ㅁ","ㅂ"],["ㄴ","ㄷ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#21','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C7',3,'mc','auto','단원 평가 — 선대칭도형이면서 점대칭도형인 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X20']::text[],true,'{"seq":21,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"단원 평가 — 선대칭도형이면서 점대칭도형인 것은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가","mis":"M5-2-u3-X15"},{"t":"나","mis":"M5-2-u3-X15"},{"t":"없어요","mis":"M5-2-u3-X20"}],"explanation":["라는 세로 가운데 선으로 접어도 겹치고 180° 돌려도 겹쳐요.","가는 선대칭도형만, 나는 점대칭도형만이에요.","둘 다인 도형도 있어요."],"asset":{"type":"geo","items":[{"w":92.08,"h":88.36,"poly":[[[46.04,8.0],[84.08,35.64],[69.55,80.36],[22.53,80.36],[8.0,35.64]]],"cap":"가"},{"w":86.0,"h":64.0,"poly":[[[28.0,8.0],[78.0,8.0],[58.0,56.0],[8.0,56.0]]],"cap":"나"},{"w":88.0,"h":68.0,"poly":[[[8.0,60.0],[80.0,52.0],[56.0,8.0]]],"cap":"다"},{"w":96.0,"h":76.0,"poly":[[[8.0,8.0],[48.0,28.0],[88.0,8.0],[88.0,68.0],[48.0,48.0],[8.0,68.0]]],"cap":"라"},{"w":96.0,"h":64.0,"poly":[[[28.0,8.0],[68.0,8.0],[88.0,56.0],[8.0,56.0]]],"cap":"마"},{"w":76.0,"h":80.0,"poly":[[[28.0,8.0],[68.0,8.0],[68.0,48.0],[48.0,48.0],[48.0,72.0],[8.0,72.0],[8.0,32.0],[28.0,32.0]]],"cap":"바"}],"tag":false},"variant_rule":{"alt":[{"stem":"타원에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"선대칭도형이면서 점대칭도형이다","correct":true},{"t":"선대칭도형도 점대칭도형도 아니다","mis":"M5-2-u3-X19"},{"t":"선대칭도형이라서 점대칭도형은 아니다","mis":"M5-2-u3-X20"},{"t":"점대칭도형이지만 대칭의 중심이 여러 개이다","mis":"M5-2-u3-X15"}],"explanation":["타원은 가로·세로 가운데 선으로 접으면 겹쳐요.","가운데 점을 중심으로 180° 돌려도 겹쳐요.","곧은 변이 없어도 대칭일 수 있어요."],"asset":null},{"stem":"단원 평가 — 자음자 ㄹ, ㅂ, ㄷ, ㅅ, ㅇ, ㅁ 가운데 점대칭도형이지만 선대칭도형은 아닌 것은 어느 것인가요?","options":[{"t":"ㄹ","correct":true},{"t":"ㅇ","mis":"M5-2-u3-X20"},{"t":"ㅂ","mis":"M5-2-u3-X15"},{"t":"ㅅ","mis":"M5-2-u3-X15"}],"explanation":["ㄹ은 180° 돌리면 겹치지만 어떤 직선으로 접어도 겹치지 않아요.","ㅇ은 선대칭도형이면서 점대칭도형이에요.","ㅂ·ㅅ은 선대칭도형이에요."],"asset":null},{"stem":"문제로 마무리 — 선대칭도형이면서 점대칭도형인 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"나","mis":"M5-2-u3-X19"},{"t":"다","mis":"M5-2-u3-X20"},{"t":"가, 나, 다, 바","mis":"M5-2-u3-X15"}],"explanation":["나(육각형)는 접어도 겹치고 180° 돌려도 겹쳐요.","다(원)도 접어도, 돌려도 겹쳐요.","가와 바는 점대칭도형이기만 해요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"poly":[[[20,20],[100,20],[140,100],[60,100]]],"grid":20,"cap":"가"},{"w":120,"h":160,"poly":[[[60,20],[100,60],[100,100],[60,140],[20,100],[20,60]]],"grid":20,"cap":"나"},{"w":160,"h":160,"circle":[[[80,80],60]],"grid":20,"cap":"다"},{"w":160,"h":140,"poly":[[[20,20],[140,20],[80,120]]],"grid":20,"cap":"라"},{"w":120,"h":140,"poly":[[[20,20],[100,20],[100,60],[80,60],[80,120],[40,120],[40,60],[20,60]]],"grid":20,"cap":"마"},{"w":160,"h":160,"poly":[[[20,40],[80,40],[140,20],[140,120],[80,120],[20,140]]],"grid":20,"cap":"바"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#22','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C9',3,'ox','auto','텔레파시 놀이에서 반만 그려진 같은 카드라도 선대칭도형으로 완성할 때와 점대칭도형으로 완성할 때 모양이 달라요.',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":22,"concept":"M5-2-u3-C9","difficulty":3,"kind":"ox","stem":"텔레파시 놀이에서 반만 그려진 같은 카드라도 선대칭도형으로 완성할 때와 점대칭도형으로 완성할 때 모양이 달라요.","answer":"O","reason_options":[{"t":"선대칭은 대칭축으로 접은 자리, 점대칭은 중심을 지나 180° 돌린 자리에 나머지를 그리므로","correct":true},{"t":"반쪽이 같으면 어떻게 완성해도 같은 모양이 되므로","mis":"M5-2-u3-X15"}],"mis":"M5-2-u3-X15","explanation":["선대칭으로 완성하면 반쪽을 뒤집은 모양이 붙어요.","점대칭으로 완성하면 반쪽을 180° 돌린 모양이 붙어요.","그래서 모양이 달라요 — 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 완성한 뒤 투명 종이에 본떠 대칭축을 따라 접어 보면 점대칭도형인지 확인할 수 있어요.","answer":"X","reason_options":[{"t":"점대칭도형은 대칭의 중심을 중심으로 180° 돌려 보아야 확인할 수 있으므로","correct":true},{"t":"점대칭도형도 접어서 확인하므로","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형은 180° 돌렸을 때 완전히 겹치는 도형이에요.","본뜬 종이를 대칭의 중심에 누름 못으로 고정하고 돌려 봐요.","접어 보는 것은 선대칭도형을 확인하는 방법이에요 — 틀린 말이에요."]},{"stem":"선대칭도형을 완성할 때와 점대칭도형을 완성할 때 대응점을 찾는 방법은 같아요.","answer":"X","reason_options":[{"t":"선대칭은 대칭축과 수직인 방향으로, 점대칭은 대칭의 중심을 지나는 방향으로 같은 거리만큼 가므로","correct":true},{"t":"둘 다 기준에서 같은 거리만큼만 가면 되므로","mis":"M5-2-u3-X15"}],"explanation":["선대칭도형은 대칭축에 수선을 긋고 같은 거리에 대응점을 찍어요.","점대칭도형은 대칭의 중심을 지나 같은 거리만큼 더 간 곳에 찍어요.","방향이 달라요 — 틀린 말이에요."]},{"stem":"점대칭도형을 그릴 때 대칭의 중심에서 대응점까지의 거리가 같다는 성질을 이용해요.","answer":"O","reason_options":[{"t":"대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나누므로","correct":true},{"t":"대응점은 대칭의 중심과 같은 점이므로","mis":"M5-2-u3-X13"}],"explanation":["대칭의 중심은 대응점끼리 이은 선분의 가운데에 있어요.","그래서 중심에서 두 대응점까지의 거리가 같아요.","이 성질로 대응점을 찍어요 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#23','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C8',4,'essay','teacher','단원 평가 — 점대칭도형(평행사변형)에서 선분 ㄴㄹ과 선분 ㄱㄷ의 길이의 차는 몇 cm인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u3-C8","difficulty":4,"kind":"essay","stem":"단원 평가 — 점대칭도형(평행사변형)에서 선분 ㄴㄹ과 선분 ㄱㄷ의 길이의 차는 몇 cm인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"점대칭도형의 대칭의 중심은 대응점끼리 이은 선분을 똑같이 둘로 나누므로 (선분 ㄱㄷ) = 6 + 6 = 12(cm), (선분 ㄴㄹ) = 8 + 8 = 16(cm)입니다. 따라서 길이의 차는 16 − 12 = 4(cm)입니다.","scoring_points":["대칭의 중심이 대응점끼리 이은 선분을 똑같이 둘로 나눈다고 썼는가","선분 ㄱㄷ 12 cm, 선분 ㄴㄹ 16 cm를 구했는가","답 4 cm를 구했는가"]},"explanation":["대칭의 중심에서 두 대응점까지의 거리는 같아요.","선분 ㄱㄷ = 12 cm, 선분 ㄴㄹ = 16 cm예요.","16 − 12 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":161.4,"h":140.0,"pts":{"ㄱ":[43.4,16.0,"nw"],"ㄴ":[16.0,110.0,"sw"],"ㄷ":[118.0,110.0,"se"],"ㄹ":[145.4,16.0,"ne"]," ":[80.7,63.0,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"dash":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"lab":[[[72.7,31.0],"6 cm"],[[118.7,53.0],"8 cm"],[[67.0,124.0],"10 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 선대칭도형인 사각형 ㄱㄴㄷㄹ의 둘레가 34 cm일 때 선분 ㄴㅂ의 길이는 몇 cm인지 풀이 과정을 쓰고 답을 구해 보세요.","explanation":["대응변과 대칭축의 성질을 함께 써요.","변 ㄴㄷ = 34 − 4 − 4 − 6 − 6 = 14(cm)예요.","14 ÷ 2 = 7(cm)예요."],"answer_guide":{"answer":"(선분 ㄹㅁ) = (선분 ㄱㅁ) = 4 cm, (변 ㄱㄴ) = (변 ㄹㄷ) = 6 cm이므로 (변 ㄴㄷ) = 34 − 4 − 6 − 6 − 4 = 14(cm)입니다. 따라서 선분 ㄴㅂ의 길이는 14 ÷ 2 = 7(cm)입니다.","scoring_points":["대응변의 길이가 같음을 이용했는가","변 ㄴㄷ 14 cm를 구했는가","대칭축이 변 ㄴㄷ을 똑같이 둘로 나눠 7 cm를 구했는가"]},"asset":{"type":"geo","items":[{"w":200.0,"h":122.35,"pts":{"ㄱ":[52.0,30.0,"nw"],"ㄴ":[16.0,92.35,"w"],"ㄷ":[184.0,92.35,"e"],"ㄹ":[148.0,30.0,"ne"],"ㅁ":[100.0,30.0,"ne"],"ㅂ":[100.0,92.35,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[100.0,16.0],[100.0,106.35]]],"lab":[[[76.0,16.0],"4 cm"],[[178.12,54.18],"6 cm"]]}],"tag":false}},{"stem":"문제로 마무리 — 서준이는 「선대칭도형의 대칭축은 항상 1개예요.」라고 말했어요. 서준이의 설명이 잘못된 이유를 써 보세요.","explanation":["대칭축의 수는 도형마다 달라요.","정사각형 4개, 원은 셀 수 없이 많아요.","대칭축은 반드시 1개가 아니라는 내용이 들어가면 정답이에요."],"answer_guide":{"answer":"선대칭도형에서 대칭축은 1개일 수도 있고 여러 개일 수도 있기 때문입니다. 예를 들어 정사각형은 대칭축이 4개이고, 원은 대칭축이 셀 수 없이 많습니다.","scoring_points":["대칭축이 1개가 아닐 수 있다고 썼는가","2개 이상이거나 셀 수 없이 많을 수 있다는 내용이 있는가","알맞은 예(정사각형·원 등)를 들었는가"]},"asset":null},{"stem":"단원 평가 — 「대칭의 중심은 여러 개 있을 수 있습니다.」가 잘못된 까닭을 써 보세요.","explanation":["점대칭도형의 대칭의 중심은 하나뿐이에요.","대응점끼리 이은 선분은 모두 그 점을 지나요.","대칭축이 여러 개일 수 있는 선대칭도형과 달라요."],"answer_guide":{"answer":"점대칭도형에서 대칭의 중심은 1개입니다. 대응점끼리 이은 선분은 모두 한 점(대칭의 중심)에서 만나기 때문입니다.","scoring_points":["대칭의 중심은 1개라고 썼는가","대응점끼리 이은 선분이 한 점에서 만난다는 까닭을 썼는가","선대칭도형의 대칭축과 헷갈리지 않았는가"]},"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#24','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C9',4,'sa','auto','단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?','{}'::text[],true,'{"seq":24,"concept":"M5-2-u3-C9","difficulty":4,"kind":"sa","stem":"단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?","answer":["8"],"explanation":["반쪽의 양 끝 두 점은 서로의 대응점이에요.","나머지 꼭짓점 3개는 점 ㅇ을 지나 반대쪽에 대응점이 하나씩 생겨요.","그래서 2 + 3 + 3 = 8(개)예요."],"mis":"M5-2-u3-X13","asset":{"type":"geo","items":[{"w":120,"h":140,"pts":{"ㅇ":[100,80,"e"]},"seg":[[[100,40],[40,20]],[[40,20],[20,80]],[[20,80],[60,120]],[[60,120],[100,120]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 삼각형 ㄱㄴㄷ은 선분 ㄱㄹ을 대칭축으로 하는 선대칭도형이에요. 삼각형 ㄱㄴㄷ의 둘레가 22 cm일 때 선분 ㄴㄹ의 길이는 몇 cm인가요?","answer":["5"],"explanation":["대응변이라 변 ㄱㄷ = 변 ㄱㄴ = 6 cm예요.","변 ㄴㄷ = 22 − 6 − 6 = 10(cm)예요.","대칭축이 변 ㄴㄷ을 똑같이 둘로 나눠 선분 ㄴㄹ = 10 ÷ 2 = 5(cm)예요."],"asset":{"type":"geo","items":[{"w":172.0,"h":72.0,"pts":{"ㄴ":[16.0,56.0,"w"],"ㄷ":[156.0,56.0,"e"],"ㄱ":[86.0,16.0,"n"],"ㄹ":[86.0,56.0,"s"]},"poly":[["ㄴ","ㄷ","ㄱ"]],"seg":[[[86.0,16.0],[86.0,56.0]]],"lab":[[[44.05,23.84],"6 cm"]],"right":[[[86.0,16.0],[86.0,56.0],[156.0,56.0]]]}],"tag":false}},{"stem":"단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 완성한 점대칭도형의 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["점 ㅇ은 점선의 가운데라, 180° 돌린 삼각형이 반대쪽에 생겨요.","완성한 도형은 가로 4 cm, 세로 3 cm인 직사각형이에요.","4 × 3 = 12(cm²)예요."],"asset":{"type":"geo","items":[{"w":130.0,"h":106.0,"pts":{"ㅇ":[74.0,46.0,"se"]},"seg":[[[34.0,16.0],[34.0,76.0]],[[34.0,76.0],[114.0,76.0]]],"dash":[[[34.0,16.0],[114.0,76.0]]],"lab":[[[16.0,46.0],"3 cm"],[[74.0,90.0],"4 cm"]],"right":[[[34.0,16.0],[34.0,76.0],[114.0,76.0]]]}],"tag":false}},{"stem":"문제로 마무리 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하면 꼭짓점은 모두 몇 개인가요?","answer":["7"],"explanation":["반쪽의 꼭짓점 5개 가운데 대칭축 위의 2개는 대응점이 그 점 자신이에요.","위쪽 대칭축 위의 점은 완성하면 한 직선의 가운데라 꼭짓점이 아니게 돼요.","그래서 3 + 3 + 1 = 7(개)예요."],"asset":{"type":"geo","items":[{"w":126.0,"h":216.0,"pts":{"ㄱ":[18.0,27.0,"n"],"ㄴ":[18.0,194.4,"s"]},"seg":[[[18.0,27.0],[18.0,194.4]],[[18.0,54.0],[54.0,54.0]],[[54.0,54.0],[108.0,126.0]],[[108.0,126.0],[54.0,180.0]],[[54.0,180.0],[18.0,162.0]]],"grid":18.0}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_c#25','math',5,2,'u3','','tb_g5_2_math_u3_review_c','unit_review','M5-2-u3-C10',4,'essay','teacher','이 땅을 정사각형 3개가 한 줄로 붙은 일자 모양 4개로는 나눌 수 없는 까닭을 써 보세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u3-C10","difficulty":4,"kind":"essay","stem":"이 땅을 정사각형 3개가 한 줄로 붙은 일자 모양 4개로는 나눌 수 없는 까닭을 써 보세요.","answer_guide":{"answer":"왼쪽 위 두 줄은 가로가 2칸뿐이라 일자 모양을 세로로만 놓을 수 있습니다. 세로로 놓으면 아래 두 줄에 남는 칸들이 일자 모양으로 채워지지 않기 때문에 일자 모양 4개로는 나눌 수 없습니다.","scoring_points":["위쪽 가로 2칸에는 세로로만 놓을 수 있다고 썼는가","남는 칸을 일자 모양으로 채울 수 없다고 썼는가","그래서 ㄱ자 모양으로 나눠야 함을 알았는가"]},"explanation":["일자 모양은 3칸이 한 줄이에요.","가로 2칸인 곳에는 세로로만 들어가요.","그러면 남는 칸이 한 줄 3칸이 되지 않아요."],"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"친구가 땅을 정사각형 3개씩 4조각으로 나누었다고 했어요. 바르게 나누었는지 확인하려면 무엇을 물어보아야 하는지 두 가지 써 보세요.","explanation":["정사각형 3개씩이라도 모양이 다르면 합동이 아니에요.","사과나무 조건도 확인해야 해요.","친구의 설명을 잘 듣고 궁금한 점을 질문해요."],"answer_guide":{"answer":"① 4개의 도형을 포개면 완전히 겹치나요(서로 합동인가요)? ② 도형마다 사과나무가 한 그루씩 들어 있나요?","scoring_points":["합동인지 묻는 질문을 썼는가","사과나무가 한 그루씩인지 묻는 질문을 썼는가","정사각형 수만으로는 부족함을 알았는가"]},"asset":null},{"stem":"땅을 조건(합동인 도형 4개 · 사과나무 한 그루씩)에 맞게 나누는 방법을 설명해 보세요.","explanation":["먼저 한 도형의 크기를 정해요.","사과나무의 위치로 모양을 정해요.","두 조건을 다시 확인해요."],"answer_guide":{"answer":"땅은 정사각형 12개가 붙어 있는 모양이므로 12 ÷ 4 = 3으로 정사각형 3개가 붙어 있는 모양으로 나눕니다. 사과나무의 위치를 생각하여 사과나무가 한 그루씩 들어가도록 ㄱ자 모양의 합동인 도형 4개로 나눕니다.","scoring_points":["12 ÷ 4 = 3을 썼는가","사과나무가 한 그루씩 들어가게 했는가","4개의 도형이 서로 합동임을 썼는가"]},"asset":{"type":"geo","items":[{"w":156.4,"h":156.4,"poly":[[[10.2,10.2],[44.2,10.2],[44.2,44.2],[10.2,44.2]],[[10.2,44.2],[44.2,44.2],[44.2,78.2],[10.2,78.2]],[[10.2,78.2],[44.2,78.2],[44.2,112.2],[10.2,112.2]],[[10.2,112.2],[44.2,112.2],[44.2,146.2],[10.2,146.2]],[[44.2,10.2],[78.2,10.2],[78.2,44.2],[44.2,44.2]],[[44.2,44.2],[78.2,44.2],[78.2,78.2],[44.2,78.2]],[[44.2,78.2],[78.2,78.2],[78.2,112.2],[44.2,112.2]],[[44.2,112.2],[78.2,112.2],[78.2,146.2],[44.2,146.2]],[[78.2,78.2],[112.2,78.2],[112.2,112.2],[78.2,112.2]],[[78.2,112.2],[112.2,112.2],[112.2,146.2],[78.2,146.2]],[[112.2,78.2],[146.2,78.2],[146.2,112.2],[112.2,112.2]],[[112.2,112.2],[146.2,112.2],[146.2,146.2],[112.2,146.2]]],"lab":[[[27.2,27.2],"나무"],[[61.2,61.2],"나무"],[[129.2,95.2],"나무"],[[61.2,129.2],"나무"]]}],"tag":false}},{"stem":"정삼각형 12개가 붙어 있는 모양을 합동인 도형 4개로 나누는 방법을 쓰고 확인하는 방법도 써 보세요.","explanation":["12개를 4개로 똑같이 나눠요.","정삼각형 3개가 붙은 모양은 사다리꼴이에요.","포개어 완전히 겹치는지 확인해요."],"answer_guide":{"answer":"12 ÷ 4 = 3이므로 정삼각형 3개가 붙어 있는 모양으로 나눕니다. 나눈 4개의 도형을 포개어 보아 완전히 겹치면 서로 합동입니다.","scoring_points":["정삼각형 3개씩임을 썼는가","나누는 방법을 썼는가","포개어 확인한다고 썼는가"]},"asset":{"type":"geo","items":[{"w":240.8,"h":113.79,"poly":[[[36.4,56.9],[92.4,56.9],[64.4,8.4]],[[92.4,56.9],[148.4,56.9],[120.4,8.4]],[[148.4,56.9],[204.4,56.9],[176.4,8.4]],[[64.4,8.4],[120.4,8.4],[92.4,56.9]],[[120.4,8.4],[176.4,8.4],[148.4,56.9]],[[8.4,105.39],[64.4,105.39],[36.4,56.9]],[[64.4,105.39],[120.4,105.39],[92.4,56.9]],[[120.4,105.39],[176.4,105.39],[148.4,56.9]],[[176.4,105.39],[232.4,105.39],[204.4,56.9]],[[36.4,56.9],[92.4,56.9],[64.4,105.39]],[[92.4,56.9],[148.4,56.9],[120.4,105.39]],[[148.4,56.9],[204.4,56.9],[176.4,105.39]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#1','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C2',1,'mc','auto','단원 평가 — 나머지 셋과 합동이 아닌 도형은 어느 것인가요?',ARRAY['M5-2-u3-X17','M5-2-u3-X04']::text[],true,'{"seq":1,"concept":"M5-2-u3-C2","difficulty":1,"kind":"mc","stem":"단원 평가 — 나머지 셋과 합동이 아닌 도형은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M5-2-u3-X17"},{"t":"나","mis":"M5-2-u3-X04"},{"t":"라","mis":"M5-2-u3-X04"}],"explanation":["가, 나, 라는 뒤집거나 돌리면 서로 완전히 겹쳐요.","다는 모양도 크기도 달라 겹치지 않아요.","물음이 「합동이 아닌」 도형을 묻는 것을 확인해요."],"asset":{"type":"geo","items":[{"w":80.0,"h":56.0,"poly":[[[8.0,8.0],[8.0,48.0],[72.0,48.0]]],"cap":"가"},{"w":80.0,"h":56.0,"poly":[[[72.0,8.0],[72.0,48.0],[8.0,48.0]]],"cap":"나"},{"w":68.0,"h":48.0,"poly":[[[8.0,40.0],[60.0,40.0],[34.0,8.0]]],"cap":"다"},{"w":56.0,"h":80.0,"poly":[[[8.0,8.0],[48.0,8.0],[8.0,72.0]]],"cap":"라"}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 — 서로 합동인 도형을 모두 찾아 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가와 다, 나와 마","correct":true},{"t":"가와 다","mis":"M5-2-u3-X04"},{"t":"나와 마","mis":"M5-2-u3-X04"},{"t":"가와 다, 나와 마, 다와 바","mis":"M5-2-u3-X03"}],"explanation":["가와 다는 돌려서, 나와 마는 뒤집어서 포개면 완전히 겹쳐요.","바는 정사각형이라 직사각형 가·다와 모양이 달라요.","그래서 가와 다, 나와 마예요."],"asset":{"type":"geo","items":[{"w":80,"h":120,"poly":[[[20,20],[60,20],[60,100],[20,100]]],"grid":20,"cap":"가"},{"w":120,"h":120,"poly":[[[20,20],[20,100],[100,100]]],"grid":20,"cap":"나"},{"w":120,"h":80,"poly":[[[20,20],[100,20],[100,60],[20,60]]],"grid":20,"cap":"다"},{"w":120,"h":120,"poly":[[[60,20],[100,100],[20,100]]],"grid":20,"cap":"라"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[20,100]]],"grid":20,"cap":"마"},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,100],[20,100]]],"grid":20,"cap":"바"}],"tag":false}},{"stem":"단원 평가 — 서로 합동인 도형을 모두 찾아 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"가와 사, 다와 마","correct":true},{"t":"다와 마","mis":"M5-2-u3-X04"},{"t":"가와 사, 다와 마, 마와 아","mis":"M5-2-u3-X03"},{"t":"나와 바, 다와 마","mis":"M5-2-u3-X03"}],"explanation":["가와 사는 뒤집어서 포개면 완전히 겹쳐요.","다와 마는 반지름이 같은 원이라 겹쳐요 — 아는 더 작은 원이에요.","나와 바는 둘 다 직사각형이지만 크기가 달라요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,60],[80,20],[80,60]]],"grid":20,"cap":"가"},{"w":60,"h":100,"poly":[[[20,20],[50.0,20],[50.0,80],[20,80]]],"grid":20,"cap":"나"},{"w":100,"h":100,"circle":[[[50.0,50.0],30.0]],"grid":20,"cap":"다"},{"w":100,"h":100,"poly":[[[20,20],[80,20],[50.0,72.0]]],"grid":20,"cap":"라"},{"w":100,"h":100,"circle":[[[50.0,50.0],30.0]],"grid":20,"cap":"마"},{"w":60,"h":80,"poly":[[[20,20],[50.0,20],[50.0,64.0],[20,64.0]]],"grid":20,"cap":"바"},{"w":100,"h":80,"poly":[[[20,20],[20,60],[80,60]]],"grid":20,"cap":"사"},{"w":80,"h":80,"circle":[[[42.0,42.0],22.0]],"grid":20,"cap":"아"}],"tag":false}},{"stem":"단원 평가 — 도형 가와 합동인 도형을 찾아보세요.","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u3-X03"},{"t":"㉢","mis":"M5-2-u3-X02"},{"t":"없어요","mis":"M5-2-u3-X04"}],"explanation":["㉡은 도형 가를 돌려 세운 모양이라 포개면 완전히 겹쳐요.","㉠은 정사각형, ㉢은 한쪽이 비스듬한 사각형이라 겹치지 않아요.","돌려서 겹쳐도 합동이에요."],"asset":{"type":"geo","items":[{"w":76.0,"h":56.0,"poly":[[[8.0,8.0],[68.0,8.0],[68.0,48.0],[8.0,48.0]]],"cap":"도형 가"},{"w":56.0,"h":56.0,"poly":[[[8.0,8.0],[48.0,8.0],[48.0,48.0],[8.0,48.0]]],"cap":"㉠"},{"w":56.0,"h":76.0,"poly":[[[8.0,8.0],[48.0,8.0],[48.0,68.0],[8.0,68.0]]],"cap":"㉡"},{"w":76.0,"h":56.0,"poly":[[[8.0,8.0],[48.0,8.0],[68.0,48.0],[8.0,48.0]]],"cap":"㉢"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
