INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#6','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C7',1,'mc','auto','단원 평가 — 정삼각형, 정사각형, 사다리꼴 가운데 점대칭도형을 찾아보세요.',ARRAY['M5-2-u3-X14','M5-2-u3-X15']::text[],true,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"단원 평가 — 정삼각형, 정사각형, 사다리꼴 가운데 점대칭도형을 찾아보세요.","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X14"},{"t":"사다리꼴","mis":"M5-2-u3-X15"},{"t":"셋 다","mis":"M5-2-u3-X14"}],"explanation":["정사각형은 가운데 점을 중심으로 180° 돌리면 겹쳐요.","정삼각형은 120°에서 겹쳐도 180°에서는 겹치지 않아요.","사다리꼴은 접으면 겹치지만 돌리면 겹치지 않아요."],"variant_rule":{"alt":[{"stem":"문제로 마무리 — 점대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 다, 바","correct":true},{"t":"가, 바","mis":"M5-2-u3-X20"},{"t":"가, 나, 바","mis":"M5-2-u3-X19"},{"t":"가, 나, 다, 라, 마, 바","mis":"M5-2-u3-X14"}],"explanation":["가·나·바는 가운데 점을 중심으로 180° 돌리면 완전히 겹쳐요.","다(원)도 180° 돌리면 겹쳐요.","나와 다는 선대칭도형이면서 점대칭도형이에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"poly":[[[20,20],[100,20],[140,100],[60,100]]],"grid":20,"cap":"가"},{"w":120,"h":160,"poly":[[[60,20],[100,60],[100,100],[60,140],[20,100],[20,60]]],"grid":20,"cap":"나"},{"w":160,"h":160,"circle":[[[80,80],60]],"grid":20,"cap":"다"},{"w":160,"h":140,"poly":[[[20,20],[140,20],[80,120]]],"grid":20,"cap":"라"},{"w":120,"h":140,"poly":[[[20,20],[100,20],[100,60],[80,60],[80,120],[40,120],[40,60],[20,60]]],"grid":20,"cap":"마"},{"w":160,"h":160,"poly":[[[20,40],[80,40],[140,20],[140,120],[80,120],[20,140]]],"grid":20,"cap":"바"}],"tag":false}},{"stem":"단원 평가 — 점대칭도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 바","mis":"M5-2-u3-X20"},{"t":"가, 나, 라, 바","mis":"M5-2-u3-X14"},{"t":"라, 마","mis":"M5-2-u3-X15"}],"explanation":["나·라·바는 180° 돌리면 완전히 겹쳐요.","라는 선대칭도형이면서 점대칭도형이에요.","가와 마는 접어서만 겹쳐요."],"asset":{"type":"geo","items":[{"w"