INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#8','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C4',1,'sa','auto','단원 평가 — 정삼각형의 대칭축은 모두 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"단원 평가 — 정삼각형의 대칭축은 모두 몇 개인가요?","answer":["3"],"explanation":["정삼각형은 세 변의 길이가 모두 같아요.","각 꼭짓점과 마주 보는 변의 가운데를 잇는 직선 3개로 접혀요.","그래서 대칭축은 3개예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"문제로 마무리 — 화살 모양 선대칭도형에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["화살 모양은 가로 가운데 직선으로 접으면 완전히 겹쳐요.","세로로 접으면 겹치지 않아요.","그래서 대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":176.0,"h":176.0,"poly":[[[22.0,44.0],[66.0,66.0],[66.0,22.0],[110.0,22.0],[154.0,88.0],[110.0,154.0],[66.0,154.0],[66.0,110.0],[22.0,132.0]]],"grid":22.0}],"tag":false}},{"stem":"단원 평가 — 정사각형의 대칭축은 모두 몇 개인가요?","answer":["4"],"explanation":["정사각형은 세로·가로 가운데 선으로 접으면 겹쳐요.","두 대각선으로 접어도 겹쳐요.","그래서 대칭축은 4개예요."]},{"stem":"단원 평가 — 선대칭도형(이등변삼각형)에 대칭축을 그으면 모두 몇 개인가요?","answer":["1"],"explanation":["이 삼각형은 두 변의 길이가 같아요.","뾰족한 꼭짓점과 마주 보는 변의 가운데를 잇는 직선으로 접으면 겹쳐요.","대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":100,"h":100,"poly":[[[20,20],[80,50.0],[20,80]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#9','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C5',2,'sa','auto','단원 평가 — 선대칭도형에서 변 ㄷㄹ의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"단원 평가 — 선대칭도형에서 변 ㄷㄹ의 길이는 몇 cm인가요?","answer":["10"],"explanation":["대칭축은 점 ㄱ과 점 ㄹ을 지나요.","변 ㄷㄹ의 대응변은 변 ㅁㄹ이에요.","그래서 10 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":206.0,"h":178.0,"pts":{"ㄱ":[110.0,36.0,"ne"],"ㄴ":[30.0,96.0,"w"],"ㄷ":[30.0,146.0,"sw"],"ㄹ":[110.0,126.0,"sw"],"ㅁ":[190.0,146.0,"se"],"ㅂ":[190.0,96.0,"e"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[110.0,16.0],[110.0,162.0]]],"lab":[[[158.4,54.8],"12 cm"],[[16.0,121.0],"6 cm"],[[147.09,147.64],"10 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가 — 선대칭도형을 보고 ? cm에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["왼쪽 아래 변(? cm)을 대칭축으로 접으면 오른쪽 아래 변과 겹쳐요.","대응변의 길이는 같아요.","그래서 5 cm예요 — 8 cm는 위쪽 변이에요."],"asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.96],"? cm"],[[168.37,71.7],"?°"]],"arc":[[[116.0,58.0],[16.0,40.0],[56.0,88.0]],[[16.0,40.0],[56.0,88.0],[176.0,88.0]],[[216.0,40.0],[176.0,88.0],[56.0,88.0]]]}],"tag":false}},{"stem":"단원 평가 — 선대칭도형을 보고 ?°에 알맞은 수를 쓰세요.","answer":["130"],"explanation":["?°인 각을 대칭축으로 접으면 130°인 각과 겹쳐요.","대응각의 크기는 같아요.","그래서 130°예요 — 40°는 다른 각이에요."],"asset":{"type":"geo","items":[{"w":232.0,"h":126.0,"poly":[[[16.0,40.0],[116.0,58.0],[216.0,40.0],[176.0,88.0],[56.0,88.0]]],"seg":[[[116.0,16.0],[116.0,110.0]]],"lab":[[[40.2,54.08],"40°"],[[63.63,71.7],"130°"],[[164.23,39.16],"8 cm"],[[205.22,71.68],"5 cm"],[[25.24,72.9