INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#13','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C6',2,'mc','auto','직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄴ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X10','M5-2-u3-X12']::text[],true,'{"seq":13,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"직선 ㄹㅁ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 점 ㄴ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㅇ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X10"},{"t":"점 ㅅ","mis":"M5-2-u3-X12"},{"t":"점 ㅈ","mis":"M5-2-u3-X12"}],"explanation":["대칭축과 수직인 방향으로 대응점을 찾아요.","대칭축까지의 거리와 같은 거리만큼 반대쪽으로 가요.","그래서 점 ㅇ이에요 — 칸 수가 틀리거나 높이가 어긋난 점이 아니에요."],"asset":{"type":"geo","items":[{"w":408.0,"h":340.0,"pts":{"ㄹ":[187.0,17.0,"n"],"ㅁ":[187.0,323.0,"s"],"ㄱ":[85.0,51.0,"w"],"ㄴ":[85.0,153.0,"w"],"ㄷ":[17.0,289.0,"w"],"ㅂ":[391.0,153.0,"n"],"ㅅ":[289.0,170.0,"s"],"ㅇ":[289.0,153.0,"n"],"ㅈ":[306.0,153.0,"e"]},"seg":[[[187.0,17.0],[187.0,323.0]],[[85.0,51.0],[85.0,153.0]],[[85.0,153.0],[17.0,289.0]],[[85.0,51.0],[187.0,153.0]],[[17.0,289.0],[187.0,255.0]]],"grid":17.0}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려고 해요. 가장 오른쪽에 있는 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㅁ","mis":"M5-2-u3-X10"},{"t":"점 ㅂ","mis":"M5-2-u3-X12"}],"explanation":["대칭축과 수직인 방향으로 대응점을 찾아요.","대칭축까지의 거리와 같은 거리만큼 반대쪽으로 가요.","그래서 점 ㄹ이에요 — 칸 수가 틀리거나 높이가 어긋난 점이 아니에요."],"asset":{"type":"geo","items":[{"w":306.0,"h":216.0,"pts":{"ㄱ":[198.0,27.0,"n"],"ㄴ":[198.0,194.4,"s"],"ㄷ":[108.0,144.0,"s"],"ㄹ":[108.0,126.0,"n"],"ㅁ":[18.0,126.0,"n"],"ㅂ":[126.0,126.0,"e"]},"seg":[[[198.0,27.0],[198.0,194.4]],[[198.0,54.0],[234.0,54.0]],[[234.0,54.0],[288.0,126.0]],[[288.0,126.0],[234.0,180.0]],[[234.0,180.0],[198.0,162.0]]],"grid":18.0}],"tag":false}},{"stem":"형성 평가 — 직선 ㄱㄴ을 대칭축으로 하는 선대칭도형을 완성하려