INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u3_review_d#14','math',5,2,'u3','','tb_g5_2_math_u3_review_d','unit_review','M5-2-u3-C9',2,'mc','auto','단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 왼쪽 아래 꼭짓점의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X13','M5-2-u3-X15']::text[],true,'{"seq":14,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"단원 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 왼쪽 아래 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X13"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"}],"explanation":["꼭짓점에서 점 ㅇ까지 간 만큼(가로·세로 칸 수)을 세어요.","점 ㅇ을 지나 같은 만큼 한 번 더 가면 대응점이에요.","그래서 점 ㄴ이에요 — 가로나 세로 한쪽만 거꾸로 간 자리가 아니에요."],"asset":{"type":"geo","items":[{"w":180,"h":140,"pts":{"ㅇ":[100,80,"e"],"ㄱ":[160,60,"se"],"ㄴ":[140,40,"nw"],"ㄷ":[60,40,"w"],"ㄹ":[140,120,"e"]},"seg":[[[100,40],[40,20]],[[40,20],[20,80]],[[20,80],[60,120]],[[60,120],[100,120]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 가장 왼쪽 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X13"}],"explanation":["꼭짓점에서 점 ㅇ까지 간 만큼(가로·세로 칸 수)을 세어요.","점 ㅇ을 지나 같은 만큼 한 번 더 가면 대응점이에요.","그래서 점 ㄴ이에요 — 가로나 세로 한쪽만 거꾸로 간 자리가 아니에요."],"asset":{"type":"geo","items":[{"w":270.0,"h":162.0,"pts":{"ㅇ":[126.0,90.0,"ne"],"ㄱ":[18.0,126.0,"w"],"ㄴ":[234.0,126.0,"nw"],"ㄷ":[234.0,54.0,"e"],"ㄹ":[252.0,144.0,"se"]},"seg":[[[126.0,126.0],[54.0,126.0]],[[54.0,126.0],[18.0,54.0]],[[18.0,54.0],[72.0,18.0]]],"grid":18.0}],"tag":false}},{"stem":"형성 평가 — 점 ㅇ을 대칭의 중심으로 하는 점대칭도형을 완성하려고 해요. 왼쪽 위 꼭짓점의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X13"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"}],"explanation":["꼭짓점에서 점 ㅇ까지 간 만큼(가로·세로